var recoveryResumeBacktickedFragmentPattern = regexp.MustCompile("`([^`]+)`")

var projectContinuationPromptTaskIDPattern = regexp.MustCompile(`id=([0-9a-fA-F-]{36})`)
var projectContinuationPromptLeafTaskIDPattern = regexp.MustCompile(`leaf_task_id=([0-9a-fA-F-]{36})`)
var projectContinuationPromptDependencyPathPattern = regexp.MustCompile(`(?:depends_on_path|deliverable_path)=([^\s]+)`)
var projectContinuationPromptLiveDeliverablePathPattern = regexp.MustCompile(`(?s)work_status=(?:in_progress|review).*?deliverable_path=([^\s]+)`)
var projectContinuationBatchRangePattern = regexp.MustCompile(`(?i)\bposts?\s+(\d{1,3})\s*[–-]\s*(\d{1,3})\b`)
var projectContinuationCompletedBatchRangePattern = regexp.MustCompile(`\bThat completed task covers batch_range=([0-9]{1,3}-[0-9]{1,3})\b`)
var projectContinuationWorkspacePathPattern = regexp.MustCompile(`\b(?:content|templates|results|planning|docs|scripts|src|app|internal|config|data|pipeline|deliverables)/[A-Za-z0-9._/\-]+\b`)
var workspacePathInBackticksPattern = regexp.MustCompile("`([^`]+)`")
var explicitDeliverablePathPatterns = []*regexp.Regexp{
	regexp.MustCompile(`(?i)\b(?:deliverable|output):\s*([^\s,;]+)`),
	regexp.MustCompile(`(?i)\boutput\b[^.;:\n]{0,80}?\s+(?:at|to)\s+([^\s,;]+)`),
	regexp.MustCompile(`(?i)\b(?:write|create|produce)\b[^.;:\n]{0,80}?\s+(?:at|to)\s+([^\s,;]+)`),
	regexp.MustCompile(`(?i)\b(?:append|add|update)\b[^.;:\n]{0,120}?\s+(?:to|into)\s+(?:the\s+existing\s+)?([^\s,;]+)`),
	regexp.MustCompile(`(?i)\bsave\s+as\s+([^\s,;]+)`),
}
var leadingVerbDeliverablePathPattern = regexp.MustCompile(`(?i)^\s*(?:write|create|produce|append|add|update)\s+([^\s,;]+)`)
var explicitDeliverableActionWords = map[string]struct{}{
	"add":      {},
	"append":   {},
	"build":    {},
	"create":   {},
	"draft":    {},
	"generate": {},
	"produce":  {},
	"update":   {},
	"write":    {},
}
var preferredDeliverableRootPatterns = []*regexp.Regexp{
	regexp.MustCompile(`(?i)\b(?:under|in)\s+/?((?:content(?:/[A-Za-z0-9._-]+)+)/?)`),
}

var reviewPromptDescriptionOutputPathPattern = regexp.MustCompile(`(?i)\b(content(?:/[A-Za-z0-9._-]+)+\.(?:md|markdown|html|txt|json|ya?ml))\b`)

const reviewRepeatedFileReadNotFoundTurnStopSubstring = "[Repeated identical file.read validation failure in this turn (2/3): not_found."
const projectContinuationRediscoveryGuardPrefix = "[Project continuation rediscovery guard blocked only broad rereads."
const projectContinuationMissingDependencyGuardPrefix = "[Project continuation found that prerequisite artifact `"
const projectContinuationTaskLaneBoundaryGuardPrefix = "[Project continuation found that task-owned active lane work must stay inside its project_task session."
const projectContinuationSuccessfulHandoffPrefix = "[Project continuation successfully handed off the focused replacement child work."
const projectContinuationReviewLaneResumePrefix = "[Project continuation resumed blocked review lane "

