func (e *TurnEngine) RecoverCancelledBootstrapSessions(ctx context.Context) (int, error) {
	if e == nil || e.pool == nil || e.chat == nil {
		return 0, nil
	}

	rows, err := e.pool.Query(ctx, `
		WITH latest_turn AS (
			SELECT DISTINCT ON (session_id)
				session_id,
				id,
				status
			FROM chat_turn
			ORDER BY session_id, turn_number DESC, created_at DESC, id DESC
		)
		SELECT s.id, lt.id
		FROM chat_session s
		JOIN latest_turn lt ON lt.session_id = s.id
		WHERE s.scope_type = 'project'
		  AND s.mode = 'async'
		  AND s.status = 'active'
		  AND s.current_turn_id IS NULL
		  AND COALESCE(NULLIF(s.metadata->'project_bootstrap'->>'status', ''), '') = 'active'
		  AND lt.status = 'cancelled'
		  AND NOT EXISTS (
			SELECT 1
			FROM job_queue jq
			WHERE jq.job_type = $1
			  AND jq.status IN ('pending', 'claimed')
			  AND jq.payload->>'session_id' = s.id::text
		  )
	`, AgentTurnJobType)
	if err != nil {
		return 0, err
	}
	defer rows.Close()

	recovered := 0
	for rows.Next() {
		var sessionID, turnID uuid.UUID
		if err := rows.Scan(&sessionID, &turnID); err != nil {
			return recovered, err
		}
		session, err := e.chat.GetSession(ctx, sessionID)
		if err != nil {
			if errors.Is(err, repo.ErrNotFound) {
				continue
			}
			return recovered, err
		}
		before, err := e.countActiveAgentTurnJobsForSession(ctx, sessionID)
		if err != nil {
			return recovered, err
		}
		if err := e.handleProjectBootstrapCancelledTurn(ctx, session, turnID); err != nil {
			return recovered, err
		}
		after, err := e.countActiveAgentTurnJobsForSession(ctx, sessionID)
		if err != nil {
			return recovered, err
		}
		if after > before {
			recovered++
		}
	}
	if rows.Err() != nil {
		return recovered, rows.Err()
	}
	return recovered, nil
}

func (e *TurnEngine) CleanupLegacyCancelConsumerCursors(ctx context.Context) (int, error) {
	if e == nil || e.pool == nil {
		return 0, nil
	}

	commandTag, err := e.pool.Exec(ctx, `
		DELETE FROM consumer_cursor
		WHERE consumer_name LIKE $1
		  AND consumer_name <> $2
	`, defaultCancelConsumerPrefix+".%", defaultCancelConsumerPrefix)
	if err != nil {
		return 0, err
	}
	return int(commandTag.RowsAffected()), nil
}

func (e *TurnEngine) HandleTurnJob(ctx context.Context, job jobqueue.Job) error {
	if strings.TrimSpace(job.JobType) != AgentTurnJobType {
		return nil
	}
	var payload AgentTurnPayload
	if err := json.Unmarshal(job.Payload, &payload); err != nil {
		return fmt.Errorf("decode %s payload: %w", AgentTurnJobType, err)
	}
	if payload.SessionID == uuid.Nil || payload.MessageID == uuid.Nil {
		return fmt.Errorf("%s payload missing session_id or message_id", AgentTurnJobType)
	}
	if e.logger != nil {
		e.logger.Debug("agent_turn job: begin",
			"job_id", job.ID,
			"session_id", payload.SessionID,
			"message_id", payload.MessageID,
			"retry_count", payload.RetryCount,
		)
	}
	if session, err := e.chat.GetSession(ctx, payload.SessionID); err == nil {
		if paused, reason, pauseErr := e.projectPausedForSession(ctx, session); pauseErr != nil {
			return pauseErr
		} else if paused {
			e.logPausedTurnSkip("skipping queued agent turn for paused project", session, reason, payload.MessageID)
			return nil
		}
	}
	err := e.handleUserMessage(ctx, payload.SessionID, payload.MessageID, payload.AgentID, payload.RetryCount, &job.ID)
	if err == nil {
		if e.logger != nil {
			e.logger.Debug("agent_turn job: completed", "job_id", job.ID, "session_id", payload.SessionID, "message_id", payload.MessageID)
		}
		return nil
	}
	if handled, recoverErr := e.handleRecoverableBootstrapTurnJobFailure(ctx, payload, &job.ID, err); recoverErr != nil {
		return recoverErr
	} else if handled {
		return nil
	}
	return err
}

func (e *TurnEngine) HandleUserMessageEvent(ctx context.Context, event eventbus.DomainEvent) error {
	// Only enqueue on user_sent, not on the generic created event, to avoid
	// duplicate jobs (both events fire for the same user message).
	if event.EventType != "chat.message.user_sent" {
		return nil
	}
	payload, err := parseAgentTurnPayload(event.Payload)
	if err != nil {
		return nil
	}
	if session, getErr := e.chat.GetSession(ctx, payload.SessionID); getErr == nil {
		if !strings.EqualFold(strings.TrimSpace(session.Status), "active") {
			return nil
		}
		if paused, reason, pauseErr := e.projectPausedForSession(ctx, session); pauseErr != nil {
			return pauseErr
		} else if paused {
			e.logPausedTurnSkip("skipping agent turn enqueue for paused project", session, reason, payload.MessageID)
			return nil
		}
		if seeded, seedErr := e.maybeSeedProjectBootstrapKickoffFromHumanMessage(ctx, session, payload, event); seedErr != nil {
			return seedErr
		} else if seeded {
			return nil
		}
		if responderID, resolveErr := e.resolveSessionAgentForSession(ctx, session); resolveErr == nil && responderID != uuid.Nil {
			responderID = e.resolveNonSelfLoopResponder(ctx, session, event, responderID)
			payload.AgentID = &responderID
		}
		enqueued, enqueueErr := e.enqueueAgentTurnIfActive(ctx, session, payload, nil)
		if enqueueErr != nil {
			return enqueueErr
		}
		if !enqueued {
			return nil
		}
		return nil
	}
	if payload.FlowNodeExecutionID != nil && *payload.FlowNodeExecutionID != uuid.Nil {
		return nil
	}
	_, err = e.enqueuer.Enqueue(ctx, nil, AgentTurnJobType, e.jobPriority, payload, nil)
	return err
}

func (e *TurnEngine) maybeSeedProjectBootstrapKickoffFromHumanMessage(ctx context.Context, session *chat.ChatSession, payload AgentTurnPayload, event eventbus.DomainEvent) (bool, error) {
	if e == nil || e.chat == nil || e.messages == nil || session == nil || payload.MessageID == uuid.Nil {
		return false, nil
	}
	if !strings.EqualFold(strings.TrimSpace(session.ScopeType), "project") ||
		!strings.EqualFold(strings.TrimSpace(session.Mode), "async") ||
		session.ScopeID == uuid.Nil {
		return false, nil
	}
	if strings.EqualFold(strings.TrimSpace(event.ActorType), "agent") {
		return false, nil
	}
	if projectBootstrapStateActive(projectBootstrapStateFromMetadata(session.Metadata)) {
		return false, nil
	}
	if !e.shouldRouteScaffoldedProjectSessionToLori(ctx, session) {
		return false, nil
	}

	messages, err := e.messages.ListBySession(ctx, session.ID)
	if err != nil {
		return false, err
	}
	for _, message := range messages {
		if message.ID == payload.MessageID {
			continue
		}
		if strings.EqualFold(strings.TrimSpace(message.Role), "assistant") {
			return false, nil
		}
		if strings.EqualFold(strings.TrimSpace(message.Role), "user") &&
			message.AuthorID != nil && *message.AuthorID != uuid.Nil &&
			strings.EqualFold(strings.TrimSpace(stringValue(messageMetadataMap(message.Metadata)["source"])), projectBootstrapSource) {
			return false, nil
		}
	}

	triggerMessage, err := e.messages.GetByID(ctx, payload.MessageID)
	if err != nil {
		if errors.Is(err, repo.ErrNotFound) {
			return false, nil
		}
		return false, err
	}
	if !strings.EqualFold(strings.TrimSpace(triggerMessage.Role), "user") {
		return false, nil
	}
	now := e.now().UTC()
	state := projectBootstrapStateFromMetadata(session.Metadata)
	state.Status = projectBootstrapStatusActive
	state.CurrentPhase = "kickoff_handoff"
	state.InitialMessageID = payload.MessageID.String()
	state.LastTurnID = ""
	state.AutoTurnCount = 0
	state.StartedAt = &now
	state.UpdatedAt = &now
	state.CompletedAt = nil
	state.FailedAt = nil
	state.FailureCategory = ""
	state.FailureClass = ""
	state.FailurePhase = ""
	state.FailureReason = ""
	state.ProviderFailureClass = ""
	state.ProviderFailureReason = ""
	acquired, err := e.tryActivateProjectBootstrapKickoff(ctx, session, state)
	if err != nil {
		return false, err
	}
	if !acquired {
		return true, nil
	}

	frankID, err := e.resolveFrankStarterID(ctx, session.OrganizationID)
	if err != nil || frankID == uuid.Nil {
		return false, err
	}
	loriID, loriErr := e.resolveLoriStarterID(ctx, session.OrganizationID)
	if loriErr != nil {
		return false, loriErr
	}
	if err := e.ensureAgentParticipant(ctx, session.ID, frankID); err != nil {
		return false, err
	}
	if loriID != uuid.Nil {
		if err := e.ensureAgentParticipant(ctx, session.ID, loriID); err != nil {
			return false, err
		}
	}

	projectSlug := ""
	if e.projects != nil {
		if projectRecord, projectErr := e.projects.GetByID(ctx, session.ScopeID); projectErr == nil {
			projectSlug = strings.TrimSpace(projectRecord.Slug)
		} else if !errors.Is(projectErr, repo.ErrNotFound) {
			return false, projectErr
		}
	}

	handoff, err := e.chat.AppendMessage(ctx, chat.AppendMessageInput{
		SessionID:  session.ID,
		AuthorType: stringPtr("agent"),
		AuthorID:   &frankID,
		Role:       "user",
		Content:    buildSyntheticProjectKickoffHandoffFromRequest(session.ScopeID, projectSlug, triggerMessage.Content),
		Metadata: mustJSONRaw(map[string]any{
			"source": projectBootstrapSource,
		}),
	})
	if err != nil {
		return false, err
	}
	state.InitialMessageID = projectBootstrapWorkflowMessageID(handoff).String()
	state.UpdatedAt = &now
	if err := e.updateProjectBootstrapState(ctx, session, state); err != nil {
		return false, err
	}

	nextAgentID := frankID
	if loriID != uuid.Nil {
		nextAgentID = loriID
	}
	_, err = e.enqueueAgentTurnIfActive(ctx, session, AgentTurnPayload{
		SessionID: session.ID,
		MessageID: handoff.ID,
		AgentID:   &nextAgentID,
	}, nil)
	return true, err
}

func (e *TurnEngine) tryActivateProjectBootstrapKickoff(ctx context.Context, session *chat.ChatSession, state projectBootstrapState) (bool, error) {
	if e == nil || e.pool == nil || session == nil || session.ID == uuid.Nil {
		return false, nil
	}
	previous := projectBootstrapStateFromMetadata(session.Metadata)
	state = normalizeProjectBootstrapStateCounts(state)
	state = projectBootstrapStateWithDerived(previous, state)
	metadata, err := projectBootstrapMetadataJSON(session.Metadata, state)
	if err != nil {
		return false, err
	}
	tag, err := e.pool.Exec(ctx, `
		UPDATE chat_session
		SET metadata = $2::jsonb
		WHERE id = $1
		  AND COALESCE(metadata->'project_bootstrap'->>'status', '') <> $3
	`, session.ID, metadata, projectBootstrapStatusActive)
	if err != nil {
		return false, err
	}
	if tag.RowsAffected() == 0 {
		return false, nil
	}
	session.Metadata = metadata
	if strings.EqualFold(strings.TrimSpace(session.ScopeType), "project") && session.ScopeID != uuid.Nil {
		if err := e.updateProjectBootstrapProjectState(ctx, session.ScopeID, state); err != nil {
			return false, err
		}
	}
	return true, nil
}

func (e *TurnEngine) resolveNonSelfLoopResponder(ctx context.Context, session *chat.ChatSession, event eventbus.DomainEvent, responderID uuid.UUID) uuid.UUID {
	if session == nil || responderID == uuid.Nil {
		return responderID
	}
	if !strings.EqualFold(strings.TrimSpace(event.ActorType), "agent") || event.ActorID == nil || *event.ActorID == uuid.Nil {
		return responderID
	}
	actorID := *event.ActorID
	if responderID != actorID {
		return responderID
	}
	if !strings.EqualFold(strings.TrimSpace(session.ScopeType), "project") {
		return responderID
	}

	if participantID, err := e.resolveFirstAgentParticipantExcluding(ctx, session.ID, actorID); err == nil && participantID != uuid.Nil {
		return participantID
	}

	frankID, err := e.resolveFrankStarterID(ctx, session.OrganizationID)
	if err != nil || frankID != actorID {
		return responderID
	}
	loriID, err := e.resolveLoriStarterID(ctx, session.OrganizationID)
	if err != nil || loriID == uuid.Nil || loriID == actorID {
		return responderID
	}
	if err := e.ensureAgentParticipant(ctx, session.ID, loriID); err != nil {
		return responderID
	}
	return loriID
}

func (e *TurnEngine) HandleReactionEvent(ctx context.Context, event eventbus.DomainEvent) error {
	if event.EventType != "chat.reaction.added" {
		return nil
	}
	payload := map[string]any{}
	if err := json.Unmarshal(event.Payload, &payload); err != nil {
		return nil
	}
	messageID, ok := payloadUUID(payload, "message_id")
	if !ok {
		return nil
	}
	emoji, _ := payloadString(payload, "emoji")
	delta, applies := reactionDelta(emoji)
	if !applies {
		return nil
	}

	message, err := e.messages.GetByID(ctx, messageID)
	if err != nil {
		return nil
	}
	if !strings.EqualFold(strings.TrimSpace(message.Role), "assistant") || message.TurnID == nil {
		return nil
	}

	sources, err := e.sources.ListBySession(ctx, message.SessionID)
	if err != nil {
		return nil
	}
	for _, source := range sources {
		if strings.TrimSpace(source.SourceType) != "chat_message" || source.SourceID == nil {
			continue
		}
		sourceMessage, getErr := e.messages.GetByID(ctx, *source.SourceID)
		if getErr != nil || sourceMessage.TurnID == nil || *sourceMessage.TurnID != *message.TurnID {
			continue
		}
		memoryRow, getMemErr := e.memories.GetByID(ctx, source.MemoryID)
		if getMemErr != nil {
			continue
		}
		next := memoryRow.Confidence + delta
		if next < 0 {
			next = 0
		}
		if next > 1 {
			next = 1
		}
		_, _ = e.memories.UpdateConfidence(ctx, source.MemoryID, next)
	}
	return nil
}

func (e *TurnEngine) HandleTurnCompletedEvent(ctx context.Context, event eventbus.DomainEvent) error {
	if event.EventType != "chat.turn.completed" {
		return nil
	}

	var payload struct {
		SessionID uuid.UUID `json:"session_id"`
		TurnID    uuid.UUID `json:"turn_id"`
	}
	if err := json.Unmarshal(event.Payload, &payload); err != nil {
		return nil
	}
	if payload.SessionID == uuid.Nil || payload.TurnID == uuid.Nil {
		return nil
	}

	session, err := e.chat.GetSession(ctx, payload.SessionID)
	if err != nil {
		if errors.Is(err, repo.ErrNotFound) {
			return nil
		}
		return err
	}
	if strings.EqualFold(strings.TrimSpace(session.ScopeType), "project") {
		return e.handleProjectBootstrapCompletedTurn(ctx, session, payload.TurnID)
	}
	if !strings.EqualFold(strings.TrimSpace(session.ScopeType), "project_task") {
		return nil
	}
	if !strings.EqualFold(strings.TrimSpace(session.Status), "active") {
		return nil
	}
	if paused, reason, pauseErr := e.projectPausedForSession(ctx, session); pauseErr != nil {
		return pauseErr
	} else if paused {
		e.logPausedTurnSkip("skipping auto continuation for paused project", session, reason, payload.TurnID)
		return nil
	}
	if e.tasks == nil || e.flowNodes == nil {
		return nil
	}

	taskRecord, err := e.tasks.GetByID(ctx, session.ScopeID)
	if err != nil {
		if errors.Is(err, repo.ErrNotFound) {
			return nil
		}
		return err
	}
	if continued, continueErr := e.maybeContinueProjectExecutionAfterTerminalTaskTurn(ctx, taskRecord); continueErr != nil {
		return continueErr
	} else if continued {
		return nil
	}
	turns, err := e.turns.ListBySession(ctx, session.ID)
	if err != nil {
		return err
	}
	latestCompleted := latestCompletedTurn(turns)
	if latestCompleted == nil || latestCompleted.ID != payload.TurnID {
		return nil
	}
	if shouldSuppressAutoContinuationForStopReason(latestCompleted.StopReason) {
		return nil
	}

	messages, err := e.messages.ListBySession(ctx, session.ID)
	if err != nil {
		return err
	}
	latestUser := latestUserMessage(messages)
	if latestUser == nil {
		return nil
	}

	taskStatus := strings.ToLower(strings.TrimSpace(taskRecord.WorkStatus))
	blockedRecoveryLane := false
	if taskStatus == "blocked" {
		blockedRecoveryLane = isRecoveryResumeMessage(*latestUser) || taskContinuationResumeMessageRootsHistory(*latestUser)
	}
	if taskStatus != "in_progress" && taskStatus != "review" && !blockedRecoveryLane {
		return nil
	}
	if taskRecord.CurrentFlowNodeID == nil {
		return nil
	}

	currentNode, err := e.flowNodes.GetByID(ctx, *taskRecord.CurrentFlowNodeID)
	if err != nil {
		if errors.Is(err, repo.ErrNotFound) {
			return nil
		}
		return err
	}
	nodeType := strings.ToLower(strings.TrimSpace(currentNode.NodeType))
	effectiveTaskStatus := taskStatus
	if blockedRecoveryLane {
		switch nodeType {
		case "work":
			effectiveTaskStatus = "in_progress"
		case "review":
			effectiveTaskStatus = "review"
		default:
			return nil
		}
	}
	if effectiveTaskStatus == "in_progress" && nodeType != "work" {
		return nil
	}
	if effectiveTaskStatus == "review" && nodeType != "review" {
		return nil
	}
	if retryDelay, ok := exhaustedTransientRetryAutoContinuationDelay(messages, payload.TurnID); ok {
		nextPayload := AgentTurnPayload{
			SessionID: session.ID,
			MessageID: latestUser.ID,
		}
		if latestCompleted.RespondingID != uuid.Nil {
			agentID := latestCompleted.RespondingID
			nextPayload.AgentID = &agentID
		}
		runAfter := e.now().Add(retryDelay).UTC()
		enqueued, err := e.enqueueAgentTurnIfActive(ctx, session, nextPayload, &runAfter)
		if err != nil {
			return err
		}
		if !enqueued {
			return nil
		}
		return nil
	}
	if effectiveTaskStatus == "review" {
		if reviewTurnCompletedWithDecision(messages, payload.TurnID) {
			return nil
		}
		assistant := latestAssistantFinalForTurn(messages, payload.TurnID)
		assistantContent := ""
		if assistant != nil {
			assistantContent = assistant.Content
		}
		if handled, handleErr := e.handleCompletedReviewTurnWithoutDecision(ctx, session, taskRecord, latestCompleted, latestUser, assistantContent); handleErr != nil {
			return handleErr
		} else if handled {
			return nil
		}
		return nil
	}
	if shouldSuppressAutoContinuationForRecoveryHalt(messages, payload.TurnID, taskRecord.Metadata) {
		return nil
	}
	assistant := latestAssistantFinalForTurn(messages, payload.TurnID)
	if assistant == nil {
		if handled, handleErr := e.handleCompletedTaskResumeWithoutUsableAssistant(ctx, session, taskRecord, latestCompleted, latestUser, ""); handleErr != nil {
			return handleErr
		} else if handled {
			return nil
		}
		return nil
	}
	if handled, handleErr := e.handleCompletedTaskResumeWithoutUsableAssistant(ctx, session, taskRecord, latestCompleted, latestUser, assistant.Content); handleErr != nil {
		return handleErr
	} else if handled {
		return nil
	}
	if latestUser.SequenceNumber > assistant.SequenceNumber {
		return nil
	}
	if handled, handleErr := e.handleCompletedWorkTurn(ctx, taskRecord, latestCompleted.RespondingID, messages, payload.TurnID); handleErr != nil {
		return handleErr
	} else if handled {
		return nil
	}
	if indicatesTaskCompletion(assistant.Content) {
		return nil
	}
	if handled, handleErr := e.enqueueTaskValidationBlockedContinuationPrompt(ctx, session, taskRecord, latestCompleted, latestUser, messages); handleErr != nil {
		return handleErr
	} else if handled {
		return nil
	}

	if consecutive := consecutiveAutoTurnsSinceLatestUser(turns, messages, latestUser.SequenceNumber); consecutive >= maxConsecutiveAutoTurns {
		e.logger.Warn("auto continuation cap reached",
			"session_id", session.ID,
			"turn_id", payload.TurnID,
			"task_id", session.ScopeID,
			"consecutive_auto_turns", consecutive,
		)
		return nil
	}

	nextPayload := AgentTurnPayload{
		SessionID: session.ID,
		MessageID: latestUser.ID,
	}
	if latestCompleted.RespondingID != uuid.Nil {
		agentID := latestCompleted.RespondingID
		nextPayload.AgentID = &agentID
	}
	runAfter := e.now().Add(defaultAutoContinueDelay).UTC()
	enqueued, err := e.enqueueAgentTurnIfActive(ctx, session, nextPayload, &runAfter)
	if err != nil {
		return err
	}
	if !enqueued {
		return nil
	}
	return nil
}

func (e *TurnEngine) handleCompletedTaskResumeWithoutUsableAssistant(
	ctx context.Context,
	session *chat.ChatSession,
	taskRecord repo.ProjectTask,
	latestCompleted *repo.ChatTurn,
	latestUser *repo.ChatMessage,
	assistantContent string,
) (bool, error) {
	if session == nil || latestCompleted == nil || latestUser == nil {
		return false, nil
	}
	isRecoveryLike := isRecoveryResumeMessage(*latestUser) || taskContinuationResumeMessageRootsHistory(*latestUser)
	isExecutionKickoff := taskExecutionKickoffMessage(*latestUser)
	if !isRecoveryLike && !isExecutionKickoff {
		return false, nil
	}
	sessionMessages := messagesFromTaskSession(ctx, e, session)
	if recoveryTurnProducedDurableWrite(taskRecord, messagesForTurn(sessionMessages, latestCompleted.ID)) {
		if e.flowAdvancer != nil && latestCompleted.RespondingID != uuid.Nil {
			if commitSHA, commitErr := e.ensureCanonicalTaskExecutionCommit(ctx, taskRecord); commitErr != nil {
				return true, commitErr
			} else if strings.TrimSpace(commitSHA) != "" {
				if _, err := e.flowAdvancer.RecordNodeCommit(ctx, taskRecord.ID, commitSHA, ""); err != nil {
					return true, err
				}
			}
			if _, err := e.flowAdvancer.AdvanceFlow(ctx, taskRecord.ID, flowsvc.Actor{Type: "agent", ID: latestCompleted.RespondingID}); err != nil {
				return true, err
			}
			return true, nil
		}
		return true, nil
	}
	if strings.TrimSpace(assistantContent) != "" && !looksLikeGenericTaskRecoveryReply(assistantContent) {
		return false, nil
	}

	if latestCompleted.RetryCount >= maxGenericRecoveryReplyRetries {
		reason := buildGenericRecoveryReplyBlockedReason(assistantContent, latestCompleted.RetryCount+1)
		haltLabel := "Recovery turn halted"
		if isExecutionKickoff {
			haltLabel = "Task kickoff halted"
		}
		if _, err := e.appendSystemMessage(ctx, latestCompleted.ID, session.ID, "["+haltLabel+": "+reason+"]"); err != nil {
			return true, err
		}
		if e.taskTransitions == nil {
			return true, fmt.Errorf(errMissingTaskTransitionServiceForRecoveryBlock)
		}
		if _, err := e.taskTransitions.MarkBlocked(ctx, taskRecord.ID, reason, tasksvc.Actor{Type: "system"}); err != nil {
			return true, err
		}
		return true, nil
	}

	nextMessageID := latestUser.ID
	if e.chat != nil {
		retryMessage, appendErr := e.chat.AppendMessage(ctx, chat.AppendMessageInput{
			SessionID: session.ID,
			TurnID:    &latestCompleted.ID,
			Role:      "user",
			Content:   latestUser.Content,
			Metadata:  latestUser.Metadata,
		})
		if appendErr != nil {
			return true, appendErr
		}
		if retryMessage != nil && retryMessage.ID != uuid.Nil {
			nextMessageID = retryMessage.ID
		}
	}

	nextPayload := AgentTurnPayload{
		SessionID:  session.ID,
		MessageID:  nextMessageID,
		RetryCount: latestCompleted.RetryCount + 1,
	}
	if latestCompleted.RespondingID != uuid.Nil {
		agentID := latestCompleted.RespondingID
		nextPayload.AgentID = &agentID
	}
	runAfter := e.now().Add(defaultAutoContinueDelay).UTC()
	enqueued, err := e.enqueueAgentTurnIfActive(ctx, session, nextPayload, &runAfter)
	if err != nil {
		return true, err
	}
	return enqueued, nil
}

func buildTaskExecutionMissingDeliverableRetryPrompt(targetPath string) string {
	targetPath = normalizeWorkspaceRelativePath(targetPath)
	lines := []string{
		"Continue the active task now from the narrowed continuation below.",
		fmt.Sprintf("Your last task turn already established that the current deliverable target `%s` is missing from the workspace.", targetPath),
		fmt.Sprintf("Do not call file.read on `%s` again until you have created it.", targetPath),
		"Do not inspect sibling path variants, broad planning artifacts, or the repository root before taking a concrete mutation step.",
		fmt.Sprintf("Create the next concrete deliverable file body for `%s` directly with file.write, or give one short blocker sentence explaining why it cannot be created from the current task context.", targetPath),
		"Do not reply with a plan, explanation, or narration about what you will write.",
	}
	return strings.Join(lines, " ")
}

func buildTaskExecutionRecoveryTargetFocusRetryPrompt(targetPath string) string {
	targetPath = normalizeWorkspaceRelativePath(targetPath)
	lines := []string{
		"Continue the active task now from the narrowed continuation below.",
		fmt.Sprintf("Your last task turn already established that recovery identified `%s` as the current deliverable target for this task.", targetPath),
		fmt.Sprintf("Do not call file.read or file.list on sibling path variants while `%s` is the active target.", targetPath),
		"Do not inspect sibling fixture files, broad planning artifacts, or the repository root before taking a concrete mutation step on the target deliverable.",
		fmt.Sprintf("Continue directly with `%s` using file.write or file.edit, or give one short blocker sentence explaining why that target still cannot be advanced from the current task context.", targetPath),
		"Do not reply with a plan, explanation, or narration about what you will do next.",
	}
	return strings.Join(lines, " ")
}

func taskExecutionRetryPromptForMissingPreferredDeliverable(messages []repo.ChatMessage, latestCompleted *repo.ChatTurn, latestUser *repo.ChatMessage, targetPath string) (string, bool) {
	if latestCompleted == nil || latestCompleted.ID == uuid.Nil || latestUser == nil {
		return "", false
	}
	if strings.TrimSpace(targetPath) == "" {
		return "", false
	}
	if !taskExecutionKickoffMessage(*latestUser) && !taskContinuationResumeMessageRootsHistory(*latestUser) {
		return "", false
	}

	normalizedTarget := normalizeWorkspaceRelativePath(targetPath)
	turnMessages := messagesForTurn(messages, latestCompleted.ID)
	if len(turnMessages) == 0 {
		return "", false
	}

	sawTargetReadNotFound := false
	for _, message := range turnMessages {
		if !strings.EqualFold(strings.TrimSpace(message.Role), "tool_result") {
			continue
		}
		toolName, output, errText, ok := parseToolResultMessage(message.Content)
		if !ok {
			continue
		}
		errorCode := normalizeValidationFailureCode(errText)
		if errorCode == "" {
			errorCode = normalizeValidationFailureCode(anyString(output["error"]))
		}
		path := normalizeWorkspaceRelativePath(anyString(output["path"]))
		switch strings.ToLower(strings.TrimSpace(toolName)) {
		case "file.read":
			if errorCode == "not_found" && sameWorkspaceRelativePath(path, normalizedTarget) {
				sawTargetReadNotFound = true
				continue
			}
			if errorCode == "" && sameWorkspaceRelativePath(path, normalizedTarget) && intValue(output["byte_size"]) > 0 {
				return "", false
			}
		case "file.write":
			if errorCode == "" && sameWorkspaceRelativePath(path, normalizedTarget) && intValue(output["byte_size"]) > 0 {
				return "", false
			}
		}
	}
	if !sawTargetReadNotFound {
		return "", false
	}
	return buildTaskExecutionMissingDeliverableRetryPrompt(normalizedTarget), true
}

func taskExecutionRetryPromptForRecoveryTargetFocus(messages []repo.ChatMessage, latestCompleted *repo.ChatTurn, latestUser *repo.ChatMessage, targetPath string) (string, bool) {
	if latestCompleted == nil || latestCompleted.ID == uuid.Nil || latestUser == nil {
		return "", false
	}
	if strings.TrimSpace(targetPath) == "" {
		return "", false
	}
	if !taskExecutionKickoffMessage(*latestUser) && !taskContinuationResumeMessageRootsHistory(*latestUser) {
		return "", false
	}

	normalizedTarget := normalizeWorkspaceRelativePath(targetPath)
	turnMessages := messagesForTurn(messages, latestCompleted.ID)
	if len(turnMessages) == 0 {
		return "", false
	}

	sawFocusRedirect := false
	for _, message := range turnMessages {
		if !strings.EqualFold(strings.TrimSpace(message.Role), "tool_result") {
			continue
		}
		toolName, output, errText, ok := parseToolResultMessage(message.Content)
		if !ok {
			continue
		}
		errorCode := normalizeValidationFailureCode(errText)
		if errorCode == "" {
			errorCode = normalizeValidationFailureCode(anyString(output["error"]))
		}
		path := normalizeWorkspaceRelativePath(anyString(output["path"]))
		switch strings.ToLower(strings.TrimSpace(toolName)) {
		case "file.read", "file.list":
			deliverablePath := normalizeWorkspaceRelativePath(anyString(output["deliverable_path"]))
			if (errorCode == "recovery_target_focus_required" || errorCode == "explicit_deliverable_focus_required" || errorCode == "deliverable_path_required") &&
				sameWorkspaceRelativePath(deliverablePath, normalizedTarget) &&
				path != "" &&
				!sameWorkspaceRelativePath(path, normalizedTarget) {
				sawFocusRedirect = true
				continue
			}
			if errorCode == "" && sameWorkspaceRelativePath(path, normalizedTarget) && intValue(output["byte_size"]) > 0 {
				return "", false
			}
		case "file.write", "file.edit":
			if errorCode == "" && sameWorkspaceRelativePath(path, normalizedTarget) {
				return "", false
			}
		}
	}
	if !sawFocusRedirect {
		return "", false
	}
	return buildTaskExecutionRecoveryTargetFocusRetryPrompt(normalizedTarget), true
}

func (e *TurnEngine) enqueueTaskValidationBlockedContinuationPrompt(
	ctx context.Context,
	session *chat.ChatSession,
	taskRecord repo.ProjectTask,
	latestCompleted *repo.ChatTurn,
	latestUser *repo.ChatMessage,
	messages []repo.ChatMessage,
) (bool, error) {
	if e == nil || e.chat == nil || session == nil || latestCompleted == nil || latestUser == nil {
		return false, nil
	}
	if latestCompleted.StopReason == nil || !strings.EqualFold(strings.TrimSpace(*latestCompleted.StopReason), stopReasonValidationBlocked) {
		return false, nil
	}
	if strings.EqualFold(strings.TrimSpace(taskRecord.WorkStatus), "review") {
		return false, nil
	}
	targetPath := strings.TrimSpace(e.sessionTaskDeliverablePath(ctx, session.ID, taskRecord))
	retryPrompt, ok := taskExecutionRetryPromptForMissingPreferredDeliverable(messages, latestCompleted, latestUser, targetPath)
	if !ok {
		retryPrompt, ok = taskExecutionRetryPromptForRecoveryTargetFocus(messages, latestCompleted, latestUser, targetPath)
		if !ok {
			return false, nil
		}
	}
	retryAttempt := e.taskContinuationResumeAttempt(ctx, latestUser.ID) + 1
	actionMessage, err := e.chat.AppendMessage(ctx, chat.AppendMessageInput{
		SessionID: session.ID,
		TurnID:    &latestCompleted.ID,
		Role:      "user",
		Content:   retryPrompt,
		Metadata:  taskContinuationResumeMessageMetadata(session, retryAttempt),
	})
	if err != nil {
		return true, err
	}
	nextPayload := AgentTurnPayload{
		SessionID: session.ID,
		MessageID: actionMessage.ID,
	}
	if latestCompleted.RespondingID != uuid.Nil {
		agentID := latestCompleted.RespondingID
		nextPayload.AgentID = &agentID
	}
	runAfter := e.now().Add(defaultAutoContinueDelay).UTC()
	enqueued, err := e.enqueueAgentTurnIfActive(ctx, session, nextPayload, &runAfter)
	if err != nil {
		return true, err
	}
	return enqueued, nil
}

func (e *TurnEngine) handleCompletedReviewTurnWithoutDecision(
	ctx context.Context,
	session *chat.ChatSession,
	taskRecord repo.ProjectTask,
	latestCompleted *repo.ChatTurn,
	latestUser *repo.ChatMessage,
	assistantContent string,
) (bool, error) {
	if session == nil || latestCompleted == nil || latestUser == nil {
		return false, nil
	}
	assistantContent = strings.TrimSpace(assistantContent)
	reviewRecoveryResume := isRecoveryResumeMessage(*latestUser)
	if !taskReviewActionMessage(*latestUser) && !taskExecutionKickoffMessage(*latestUser) && !reviewRecoveryResume {
		return false, nil
	}
	if decision, ok := explicitReviewDecisionFromText(assistantContent); ok && e.flowAdvancer != nil {
		actor := flowsvc.Actor{Type: "system"}
		if latestCompleted.RespondingID != uuid.Nil {
			actor = flowsvc.Actor{Type: "agent", ID: latestCompleted.RespondingID}
		}
		if decision == "approve" {
			if _, err := e.flowAdvancer.AdvanceFlow(ctx, taskRecord.ID, actor); err != nil {
				return true, err
			}
		} else {
			if _, err := e.flowAdvancer.RejectFlowNode(ctx, taskRecord.ID, actor); err != nil {
				return true, err
			}
		}
		if _, err := e.appendSystemMessage(ctx, latestCompleted.ID, session.ID, "[Review decision auto-applied from explicit assistant output: "+decision+".]"); err != nil {
			return true, err
		}
		return true, nil
	}
	if e.messages != nil {
		executionID := parseFlowNodeExecutionIDFromMetadata(latestUser.Metadata)
		if executionID != uuid.Nil {
			messages, err := e.messages.ListBySession(ctx, session.ID)
			if err != nil {
				return true, err
			}
			if latestReviewApprovalAttemptRequiresHumanContinuation(messages, executionID) {
				return e.blockReviewTurnWithoutDecision(
					ctx,
					session,
					taskRecord,
					latestUser,
					latestCompleted,
					"review approval recorded but blocked task requires direct human operator continuation",
					"[Review approval was already recorded, but this task remains blocked and requires direct human operator continuation before the flow can advance. Leaving this review lane blocked instead of retrying flow.review_decision.]",
					assistantContent,
				)
			}
		}
	}

	reason := "review turn completed without calling flow.review_decision"
	if readNotFoundCount, readNotFoundCapReached, readNotFoundErr := e.repeatedReviewValidationLoopMessageTurnCapReached(ctx, session.ID, latestCompleted, reviewRepeatedFileReadNotFoundTurnStopSubstring, maxRepeatedReviewReadNotFoundCapTurns); readNotFoundErr != nil {
		return true, readNotFoundErr
	} else if readNotFoundCapReached {
		return e.blockReviewTurnWithoutDecision(
			ctx,
			session,
			taskRecord,
			latestUser,
			latestCompleted,
			fmt.Sprintf("review turn repeatedly hit file.read not_found across %d consecutive turns", readNotFoundCount),
			fmt.Sprintf("[Review turn halted after %d consecutive file.read not_found retries. The task is now blocked instead of re-reading missing secondary artifacts again. Inspect the current deliverables and call flow.review_decision with the active flow_node_execution_id to approve or reject the review step.]", readNotFoundCount),
			assistantContent,
		)
	}
	if assistantContent == "" {
		if emptyCount, emptyCapReached, emptyCapErr := e.repeatedEmptyReviewOutputTurnCapReached(ctx, session.ID, latestCompleted); emptyCapErr != nil {
			return true, emptyCapErr
		} else if emptyCapReached {
			return e.blockReviewTurnWithoutDecision(
				ctx,
				session,
				taskRecord,
				latestUser,
				latestCompleted,
				fmt.Sprintf("review turn repeatedly returned empty assistant output across %d consecutive turns", emptyCount),
				fmt.Sprintf("[Review turn halted after %d consecutive empty assistant outputs. The task is now blocked instead of auto-retrying another blank review pass. Inspect the current deliverables and call flow.review_decision with the active flow_node_execution_id to approve or reject the review step.]", emptyCount),
				assistantContent,
			)
		}
		if latestCompleted.RetryCount >= maxGenericRecoveryReplyRetries {
			return e.blockReviewTurnWithoutDecision(
				ctx,
				session,
				taskRecord,
				latestUser,
				latestCompleted,
				reason,
				"[Review turn halted: "+reason+" after repeated retries. The task is now blocked. Inspect the current deliverables and call flow.review_decision with the active flow_node_execution_id to approve or reject the review step.]",
				assistantContent,
			)
		}
		if _, err := e.appendSystemMessage(ctx, latestCompleted.ID, session.ID, "[Review turn returned empty assistant output. Retrying with a fresh review-decision prompt.]"); err != nil {
			return true, err
		}
		nextMessageID := latestUser.ID
		if e.chat != nil {
			retryPrompt := e.buildTaskReviewActionPrompt(ctx, session) +
				"\nYour last review turn returned empty assistant output." +
				" Do not reply with blank text, acknowledgement, or a review plan." +
				" Your next assistant action must either emit the concrete flow.review_decision tool call for this review step or provide one short blocker sentence explaining why bounded review could not complete."
			if resolvedPrompt, ok, promptErr := e.reviewApprovalRetryPrompt(ctx, session, taskRecord, latestUser, latestCompleted); promptErr != nil {
				return true, promptErr
			} else if ok {
				retryPrompt = resolvedPrompt
			}
			retryMessage, appendErr := e.chat.AppendMessage(ctx, chat.AppendMessageInput{
				SessionID: session.ID,
				TurnID:    &latestCompleted.ID,
				Role:      "user",
				Content:   retryPrompt,
				Metadata:  e.syntheticContinuationActionMessageMetadataWithCarryForward(ctx, session, "task_review_action", latestUser.Metadata),
			})
			if appendErr != nil {
				return true, appendErr
			}
			if retryMessage != nil && retryMessage.ID != uuid.Nil {
				nextMessageID = retryMessage.ID
			}
		}
		nextPayload := AgentTurnPayload{
			SessionID:  session.ID,
			MessageID:  nextMessageID,
			RetryCount: latestCompleted.RetryCount + 1,
		}
		if latestCompleted.RespondingID != uuid.Nil {
			agentID := latestCompleted.RespondingID
			nextPayload.AgentID = &agentID
		}
		runAfter := e.now().Add(defaultAutoContinueDelay).UTC()
		enqueued, err := e.enqueueAgentTurnIfActive(ctx, session, nextPayload, &runAfter)
		if err != nil {
			return true, err
		}
		return enqueued, nil
	}
	if latestCompleted.RetryCount >= maxGenericRecoveryReplyRetries {
		return e.blockReviewTurnWithoutDecision(
			ctx,
			session,
			taskRecord,
			latestUser,
			latestCompleted,
			reason,
			"[Review turn halted: "+reason+" after repeated retries. The task is now blocked. Inspect the current deliverables and call flow.review_decision with the active flow_node_execution_id to approve or reject the review step.]",
			assistantContent,
		)
	}

	nextMessageID := latestUser.ID
	if e.chat != nil {
		retryContent := latestUser.Content
		retryMetadata := latestUser.Metadata
		if reviewRecoveryResume {
			retryContent = e.buildTaskReviewActionPrompt(ctx, session)
			retryMetadata = e.syntheticContinuationActionMessageMetadataWithCarryForward(ctx, session, "task_review_action", latestUser.Metadata)
		} else if taskReviewActionMessage(*latestUser) {
			retryContent = e.buildTaskReviewActionPrompt(ctx, session)
			retryMetadata = e.syntheticContinuationActionMessageMetadataWithCarryForward(ctx, session, "task_review_action", latestUser.Metadata)
		}
		if resolvedPrompt, ok, promptErr := e.reviewApprovalRetryPrompt(ctx, session, taskRecord, latestUser, latestCompleted); promptErr != nil {
			return true, promptErr
		} else if ok {
			retryContent = resolvedPrompt
		}
		retryMessage, appendErr := e.chat.AppendMessage(ctx, chat.AppendMessageInput{
			SessionID: session.ID,
			TurnID:    &latestCompleted.ID,
			Role:      "user",
			Content:   retryContent,
			Metadata:  retryMetadata,
		})
		if appendErr != nil {
			return true, appendErr
		}
		if retryMessage != nil && retryMessage.ID != uuid.Nil {
			nextMessageID = retryMessage.ID
		}
	}

	nextPayload := AgentTurnPayload{
		SessionID:  session.ID,
		MessageID:  nextMessageID,
		RetryCount: latestCompleted.RetryCount + 1,
	}
	if latestCompleted.RespondingID != uuid.Nil {
		agentID := latestCompleted.RespondingID
		nextPayload.AgentID = &agentID
	}
	runAfter := e.now().Add(defaultAutoContinueDelay).UTC()
	enqueued, err := e.enqueueAgentTurnIfActive(ctx, session, nextPayload, &runAfter)
	if err != nil {
		return true, err
	}
	return enqueued, nil
}

func (e *TurnEngine) reviewApprovalRetryPrompt(ctx context.Context, session *chat.ChatSession, taskRecord repo.ProjectTask, latestUser *repo.ChatMessage, latestCompleted *repo.ChatTurn) (string, bool, error) {
	if e == nil || e.messages == nil || latestUser == nil {
		return "", false, nil
	}
	executionID := parseFlowNodeExecutionIDFromMetadata(latestUser.Metadata)
	if executionID == uuid.Nil {
		return "", false, nil
	}
	basePrompt := e.buildTaskReviewActionPrompt(ctx, session)
	messages, err := e.messages.ListBySession(ctx, session.ID)
	if err != nil {
		return "", false, err
	}
	if !latestReviewApprovalAttemptBlockedOnDirtyWorkspace(messages, executionID) {
		if retryPrompt, ok := reviewRetryPromptForMissingPreferredDeliverable(messages, latestCompleted, latestUser, executionID, basePrompt); ok {
			return retryPrompt, true, nil
		}
		if retryPrompt, ok := reviewRetryPromptForRepeatedCheckpointOutputRereads(messages, latestCompleted, latestUser, executionID, basePrompt); ok {
			return retryPrompt, true, nil
		}
		if retryPrompt, ok := reviewRetryPromptForOrchestrationParentMissingDirectChildren(messages, latestCompleted, latestUser, taskRecord, executionID, basePrompt); ok {
			return retryPrompt, true, nil
		}
		if retryPrompt, ok := reviewRetryPromptForPersistedOrchestrationParentMissingDirectChildren(messages, latestUser, taskRecord, executionID, basePrompt); ok {
			return retryPrompt, true, nil
		}
		if retryPrompt, ok := reviewRetryPromptForOrchestrationParentIncompleteDirectChildren(messages, latestCompleted, latestUser, taskRecord, executionID, basePrompt); ok {
			return retryPrompt, true, nil
		}
		if retryPrompt, ok := reviewRetryPromptForPersistedOrchestrationParentIncompleteDirectChildren(messages, latestUser, taskRecord, executionID, basePrompt); ok {
			return retryPrompt, true, nil
		}
		if retryPrompt, ok := reviewRetryPromptForOrchestrationParentChildEvidence(messages, latestCompleted, latestUser, taskRecord, executionID, basePrompt); ok {
			return retryPrompt, true, nil
		}
		if retryPrompt, ok := reviewRetryPromptForMissingRequiredTests(messages, latestCompleted, taskRecord, executionID, basePrompt); ok {
			return retryPrompt, true, nil
		}
		if retryPrompt, ok := reviewRetryPromptForPersistedMissingRequiredTests(messages, latestUser, taskRecord, executionID, basePrompt); ok {
			return retryPrompt, true, nil
		}
		if retryPrompt, ok := reviewRetryPromptForMissingSecondaryPlanningArtifacts(messages, latestCompleted, latestUser, taskRecord, executionID, basePrompt); ok {
			return retryPrompt, true, nil
		}
		return "", false, nil
	}
	clean, err := e.reviewApprovalWorkspaceClean(ctx, taskRecord)
	if err != nil {
		return "", false, err
	}
	if !clean {
		retryPrompt := basePrompt +
			"\nYour previous approve attempt for this exact review step failed because the workspace is still dirty." +
			" Do not explain the error, summarize the runtime message, or attempt approval again while file changes remain." +
			" Inspect the dirty deliverable state and reissue flow.review_decision immediately with decision=reject and concise findings for flow_node_execution_id " + executionID.String() + "." +
			" Do not reply with narration, a plan, or placeholder arguments."
		return retryPrompt, true, nil
	}
	retryPrompt := basePrompt +
		"\nYour previous approve attempt for this exact review step failed only because the workspace was dirty." +
		" The workspace is now clean." +
		" Reissue flow.review_decision immediately with decision=approve and flow_node_execution_id " + executionID.String() + "." +
		" Do not reply with explanation text, a review plan, or placeholder arguments."
	return retryPrompt, true, nil
}

func reviewRetryPromptForMissingRequiredTests(messages []repo.ChatMessage, latestCompleted *repo.ChatTurn, taskRecord repo.ProjectTask, executionID uuid.UUID, basePrompt string) (string, bool) {
	if latestCompleted == nil || latestCompleted.ID == uuid.Nil || executionID == uuid.Nil {
		return "", false
	}
	if !taskReviewRequiresTests(taskRecord) {
		return "", false
	}
	turnMessages := messagesForTurn(messages, latestCompleted.ID)
	if len(turnMessages) == 0 {
		return "", false
	}
	mentionedTests := false
	primaryDeliverableReadable := false
	missingRequiredTests := false
	recoveryFocusedOnTests := false
	for _, message := range turnMessages {
		role := strings.ToLower(strings.TrimSpace(message.Role))
		switch role {
		case "assistant":
			if textMentionsTests(message.Content) {
				mentionedTests = true
			}
		case "tool_result":
			toolName, output, errText, ok := parseToolResultMessage(message.Content)
			if !ok {
				continue
			}
			if _, matched := reviewMissingTestsRejectEvidenceFromGuardError(errText); matched {
				mentionedTests = true
				missingRequiredTests = true
				recoveryFocusedOnTests = true
			}
			errorCode := normalizeValidationFailureCode(errText)
			if errorCode == "" {
				errorCode = normalizeValidationFailureCode(anyString(output["error"]))
			}
			normalizedToolName := strings.ToLower(strings.TrimSpace(toolName))
			if normalizedToolName == "file.read" && errorCode == "" && intValue(output["byte_size"]) > 0 {
				primaryDeliverableReadable = true
			}
			if (normalizedToolName == "file.read" || normalizedToolName == "file.list" || normalizedToolName == "file.search") && errorCode == "not_found" {
				missingRequiredTests = true
			}
			if (errorCode == "recovery_target_focus_required" || errorCode == "explicit_deliverable_focus_required") && textMentionsTests(anyString(output["path"])) {
				recoveryFocusedOnTests = true
				mentionedTests = true
			}
		case "system":
			if strings.Contains(message.Content, reviewRepeatedFileReadNotFoundTurnStopSubstring) {
				missingRequiredTests = true
			}
			if strings.Contains(message.Content, "Repeated identical file.list validation failure in this turn (2/3): recovery_target_focus_required") {
				recoveryFocusedOnTests = true
			}
			if strings.Contains(message.Content, "Review retry required after repeated same-turn read-only discovery churn") {
				recoveryFocusedOnTests = true
			}
		}
	}
	if !(mentionedTests && primaryDeliverableReadable && (missingRequiredTests || recoveryFocusedOnTests)) {
		return "", false
	}
	retryPrompt := basePrompt +
		"\nYour last review attempt already established that the preferred deliverable is present and substantive." +
		" This task explicitly requires tests or test verification, and the follow-on review attempt could not verify those test artifacts from the current workspace state." +
		" Stop searching for more files now." +
		" Call flow.review_decision immediately with decision=reject, flow_node_execution_id " + executionID.String() + ", and concise findings that the required test coverage or related test artifacts could not be verified from the delivered workspace." +
		" Use the missing or inaccessible test artifacts as evidence." +
		" Do not reply with explanation text, a review plan, or placeholder arguments."
	return retryPrompt, true
}

func reviewRetryPromptForPersistedMissingRequiredTests(messages []repo.ChatMessage, latestUser *repo.ChatMessage, taskRecord repo.ProjectTask, executionID uuid.UUID, basePrompt string) (string, bool) {
	if latestUser == nil || executionID == uuid.Nil {
		return "", false
	}
	if !taskReviewRequiresTests(taskRecord) {
		return "", false
	}

	mentionedTests := false
	primaryDeliverableReadable := false
	missingRequiredTests := false
	recoveryFocusedOnTests := false
	for _, message := range messages {
		role := strings.ToLower(strings.TrimSpace(message.Role))
		switch role {
		case "assistant":
			if textMentionsTests(message.Content) {
				mentionedTests = true
			}
		case "tool_result":
			toolName, output, errText, ok := parseToolResultMessage(message.Content)
			if !ok {
				continue
			}
			if _, matched := reviewMissingTestsRejectEvidenceFromGuardError(errText); matched {
				mentionedTests = true
				missingRequiredTests = true
				recoveryFocusedOnTests = true
			}
			errorCode := normalizeValidationFailureCode(errText)
			if errorCode == "" {
				errorCode = normalizeValidationFailureCode(anyString(output["error"]))
			}
			normalizedToolName := strings.ToLower(strings.TrimSpace(toolName))
			path := normalizeWorkspaceRelativePath(anyString(output["path"]))
			if normalizedToolName == "file.read" && errorCode == "" && intValue(output["byte_size"]) > 0 {
				primaryDeliverableReadable = true
			}
			if textMentionsTests(path) {
				mentionedTests = true
				if errorCode == "" {
					missingRequiredTests = false
					recoveryFocusedOnTests = false
					continue
				}
				if normalizedToolName == "file.read" || normalizedToolName == "file.list" || normalizedToolName == "file.search" {
					if errorCode == "not_found" {
						missingRequiredTests = true
					}
					if errorCode == "recovery_target_focus_required" || errorCode == "explicit_deliverable_focus_required" {
						recoveryFocusedOnTests = true
					}
				}
			}
		case "system":
			if strings.Contains(message.Content, reviewRepeatedFileReadNotFoundTurnStopSubstring) {
				missingRequiredTests = true
			}
			if strings.Contains(message.Content, "Repeated identical file.list validation failure in this turn (2/3): recovery_target_focus_required") {
				recoveryFocusedOnTests = true
			}
			if strings.Contains(message.Content, "Review retry required after repeated same-turn read-only discovery churn") {
				recoveryFocusedOnTests = true
			}
		}
	}
	if !(mentionedTests && primaryDeliverableReadable && (missingRequiredTests || recoveryFocusedOnTests)) {
		return "", false
	}
	retryPrompt := basePrompt +
		"\nYour prior review evidence already established that the preferred deliverable is present and substantive." +
		" This task explicitly requires tests or test verification, and recent review attempts could not verify those test artifacts from the current workspace state." +
		" Stop searching for more files now." +
		" Call flow.review_decision immediately with decision=reject, flow_node_execution_id " + executionID.String() + ", and concise findings that the required test coverage or related test artifacts could not be verified from the delivered workspace." +
		" Use the missing or inaccessible test artifacts as evidence." +
		" Do not reply with explanation text, a review plan, or placeholder arguments."
	return retryPrompt, true
}

func reviewRetryPromptForOrchestrationParentChildEvidence(messages []repo.ChatMessage, latestCompleted *repo.ChatTurn, latestUser *repo.ChatMessage, taskRecord repo.ProjectTask, executionID uuid.UUID, basePrompt string) (string, bool) {
	if latestCompleted == nil || latestCompleted.ID == uuid.Nil || latestUser == nil || executionID == uuid.Nil {
		return "", false
	}
	if !taskLooksLikeOrchestrationOnlyParent(taskRecord) {
		return "", false
	}
	targetPath := parsePromptDeliverableTarget(latestUser.Content)
	if targetPath == "" {
		return "", false
	}
	turnMessages := messagesForTurn(messages, latestCompleted.ID)
	if len(turnMessages) == 0 {
		return "", false
	}

	parentSummaryReadable := false
	directChildLookupObserved := false
	for _, message := range turnMessages {
		if !strings.EqualFold(strings.TrimSpace(message.Role), "tool_result") {
			continue
		}
		toolName, output, errText, ok := parseToolResultMessage(message.Content)
		if !ok {
			continue
		}
		errorCode := normalizeValidationFailureCode(errText)
		if errorCode == "" {
			errorCode = normalizeValidationFailureCode(anyString(output["error"]))
		}
		switch strings.ToLower(strings.TrimSpace(toolName)) {
		case "file.read":
			if errorCode == "" && normalizeWorkspaceRelativePath(anyString(output["path"])) == targetPath && intValue(output["byte_size"]) > 0 {
				parentSummaryReadable = true
			}
		case "task.list":
			if errorCode == "" {
				directChildLookupObserved = true
			}
		}
	}
	if !parentSummaryReadable || directChildLookupObserved {
		return "", false
	}

	retryPrompt := basePrompt +
		"\nYour last review attempt already established that the parent orchestration summary `" + targetPath + "` is present and substantive." +
		" Do not reread that summary or call task.get on the parent again." +
		" Continue directly with direct child-task evidence by calling task.list with parent_task_id " + taskRecord.ID.String() + " and status=all, then inspect only the direct child outputs needed for the review decision." +
		" Do not re-list the broader project task tree, do not inspect planning companion files, and do not restart from the parent summary."
	return retryPrompt, true
}

func reviewRetryPromptForOrchestrationParentMissingDirectChildren(messages []repo.ChatMessage, latestCompleted *repo.ChatTurn, latestUser *repo.ChatMessage, taskRecord repo.ProjectTask, executionID uuid.UUID, basePrompt string) (string, bool) {
	if latestCompleted == nil || latestCompleted.ID == uuid.Nil || latestUser == nil || executionID == uuid.Nil {
		return "", false
	}
	if !taskLooksLikeOrchestrationOnlyParent(taskRecord) {
		return "", false
	}
	targetPath := parsePromptDeliverableTarget(latestUser.Content)
	if targetPath == "" {
		return "", false
	}
	turnMessages := messagesForTurn(messages, latestCompleted.ID)
	if len(turnMessages) == 0 {
		return "", false
	}

	parentSummaryReadable := false
	childLookupObserved := false
	childLookupCount := -1
	for _, message := range turnMessages {
		if !strings.EqualFold(strings.TrimSpace(message.Role), "tool_result") {
			continue
		}
		toolName, output, errText, ok := parseToolResultMessage(message.Content)
		if !ok {
			continue
		}
		errorCode := normalizeValidationFailureCode(errText)
		if errorCode == "" {
			errorCode = normalizeValidationFailureCode(anyString(output["error"]))
		}
		switch strings.ToLower(strings.TrimSpace(toolName)) {
		case "file.read":
			if errorCode == "" && normalizeWorkspaceRelativePath(anyString(output["path"])) == targetPath && intValue(output["byte_size"]) > 0 {
				parentSummaryReadable = true
			}
		case "task.list":
			if errorCode == "" {
				childLookupObserved = true
				childLookupCount = anySliceLen(output["tasks"])
			}
		}
	}
	if !parentSummaryReadable || !childLookupObserved || childLookupCount != 0 {
		return "", false
	}

	retryPrompt := basePrompt +
		"\nYour last review attempt already established that the parent orchestration summary `" + targetPath + "` is present and substantive." +
		" It also established that task.list returned zero direct child tasks beneath this orchestration parent." +
		" Call flow.review_decision immediately with decision=reject, flow_node_execution_id " + executionID.String() + ", and concise findings that the orchestration parent has no direct child-task evidence to validate against its summary." +
		" Use the empty direct child-task lookup as the rejection evidence." +
		" Do not reread the parent summary, do not re-list the broader project task tree, and do not search planning companion files."
	return retryPrompt, true
}

func reviewRetryPromptForPersistedOrchestrationParentMissingDirectChildren(messages []repo.ChatMessage, latestUser *repo.ChatMessage, taskRecord repo.ProjectTask, executionID uuid.UUID, basePrompt string) (string, bool) {
	if latestUser == nil || executionID == uuid.Nil {
		return "", false
	}
	if !taskLooksLikeOrchestrationOnlyParent(taskRecord) {
		return "", false
	}
	targetPath := parsePromptDeliverableTarget(latestUser.Content)
	if targetPath == "" {
		return "", false
	}

	parentSummaryReadable := false
	latestDirectChildCount := -1
	expectDirectChildTaskListResult := false
	for _, message := range messages {
		switch strings.ToLower(strings.TrimSpace(message.Role)) {
		case "assistant":
			expectDirectChildTaskListResult = assistantCarriesDirectChildTaskListCall(message, taskRecord.ID)
		case "tool_result":
			toolName, output, errText, ok := parseToolResultMessage(message.Content)
			if !ok {
				expectDirectChildTaskListResult = false
				continue
			}
			errorCode := normalizeValidationFailureCode(errText)
			if errorCode == "" {
				errorCode = normalizeValidationFailureCode(anyString(output["error"]))
			}
			switch strings.ToLower(strings.TrimSpace(toolName)) {
			case "file.read":
				if errorCode == "" && normalizeWorkspaceRelativePath(anyString(output["path"])) == targetPath && intValue(output["byte_size"]) > 0 {
					parentSummaryReadable = true
				}
			case "task.list":
				if errorCode == "" && expectDirectChildTaskListResult {
					latestDirectChildCount = anySliceLen(output["tasks"])
				}
				expectDirectChildTaskListResult = false
			default:
				expectDirectChildTaskListResult = false
			}
		default:
			expectDirectChildTaskListResult = false
		}
	}
	if !parentSummaryReadable || latestDirectChildCount != 0 {
		return "", false
	}

	retryPrompt := basePrompt +
		"\nYour prior review evidence already established that the parent orchestration summary `" + targetPath + "` is present and substantive." +
		" It also established that task.list returned zero direct child tasks beneath this orchestration parent." +
		" Call flow.review_decision immediately with decision=reject, flow_node_execution_id " + executionID.String() + ", and concise findings that the orchestration parent has no direct child-task evidence to validate against its summary." +
		" Use the empty direct child-task lookup as the rejection evidence." +
		" Do not reread the parent summary, do not re-list the broader project task tree, and do not search planning companion files."
	return retryPrompt, true
}

func reviewRetryPromptForOrchestrationParentIncompleteDirectChildren(messages []repo.ChatMessage, latestCompleted *repo.ChatTurn, latestUser *repo.ChatMessage, taskRecord repo.ProjectTask, executionID uuid.UUID, basePrompt string) (string, bool) {
	if latestCompleted == nil || latestCompleted.ID == uuid.Nil || latestUser == nil || executionID == uuid.Nil {
		return "", false
	}
	if !taskLooksLikeOrchestrationOnlyParent(taskRecord) {
		return "", false
	}
	targetPath := parsePromptDeliverableTarget(latestUser.Content)
	if targetPath == "" {
		return "", false
	}
	turnMessages := messagesForTurn(messages, latestCompleted.ID)
	if len(turnMessages) == 0 {
		return "", false
	}

	parentSummaryReadable := false
	childEvidence := orchestrationParentChildStatusEvidence{}
	for _, message := range turnMessages {
		if !strings.EqualFold(strings.TrimSpace(message.Role), "tool_result") {
			continue
		}
		toolName, output, errText, ok := parseToolResultMessage(message.Content)
		if !ok {
			continue
		}
		errorCode := normalizeValidationFailureCode(errText)
		if errorCode == "" {
			errorCode = normalizeValidationFailureCode(anyString(output["error"]))
		}
		switch strings.ToLower(strings.TrimSpace(toolName)) {
		case "file.read":
			if errorCode == "" && normalizeWorkspaceRelativePath(anyString(output["path"])) == targetPath && intValue(output["byte_size"]) > 0 {
				parentSummaryReadable = true
			}
		case "task.list":
			if errorCode == "" {
				childEvidence = collectOrchestrationParentChildStatusEvidence(output["tasks"])
			}
		}
	}
	if !parentSummaryReadable || !childEvidence.hasUnfinished() {
		return "", false
	}

	retryPrompt := basePrompt +
		"\nYour last review attempt already established that the parent orchestration summary `" + targetPath + "` is present and substantive." +
		" It also established that one or more direct child tasks remain unfinished beneath this orchestration parent." +
		" The current direct child-task evidence is: " + childEvidence.summary() + "." +
		" Call flow.review_decision immediately with decision=reject, flow_node_execution_id " + executionID.String() + ", and concise findings that the orchestration parent cannot be approved while direct child tasks remain unfinished." +
		" Use the unfinished direct child-task statuses as the rejection evidence." +
		" Do not reread the parent summary, do not inspect child deliverable files, and do not re-list the broader project task tree."
	return retryPrompt, true
}

