func assistantCarriesDirectChildTaskListCall(message repo.ChatMessage, taskID uuid.UUID) bool {
	if taskID == uuid.Nil || len(message.Metadata) == 0 {
		return false
	}
	var meta struct {
		ToolCalls []storedAssistantToolCall `json:"tool_calls"`
	}
	if err := json.Unmarshal(message.Metadata, &meta); err != nil {
		return false
	}
	for _, call := range meta.ToolCalls {
		switch strings.ToLower(strings.TrimSpace(call.Name)) {
		case "task.list", "task_list":
			if parentID, ok := parseUUIDAny(call.Arguments["parent_task_id"]); ok && parentID == taskID {
				return true
			}
			if projectID, ok := parseUUIDAny(call.Arguments["project_id"]); ok && projectID == taskID {
				return true
			}
		}
	}
	return false
}

type orchestrationParentChildStatusEvidence struct {
	unfinished []string
}

func (e orchestrationParentChildStatusEvidence) hasUnfinished() bool {
	return len(e.unfinished) > 0
}

func (e orchestrationParentChildStatusEvidence) summary() string {
	if len(e.unfinished) == 0 {
		return "no unfinished direct child tasks"
	}
	if len(e.unfinished) == 1 {
		return e.unfinished[0]
	}
	if len(e.unfinished) == 2 {
		return e.unfinished[0] + "; " + e.unfinished[1]
	}
	return e.unfinished[0] + "; " + e.unfinished[1] + fmt.Sprintf("; and %d more unfinished direct child tasks", len(e.unfinished)-2)
}

func collectOrchestrationParentChildStatusEvidence(raw any) orchestrationParentChildStatusEvidence {
	evidence := orchestrationParentChildStatusEvidence{}
	switch typed := raw.(type) {
	case []any:
		for _, item := range typed {
			task, ok := item.(map[string]any)
			if !ok {
				continue
			}
			if summary, ok := summarizeOrchestrationParentChildStatus(task); ok {
				evidence.unfinished = append(evidence.unfinished, summary)
			}
		}
	case []map[string]any:
		for _, task := range typed {
			if summary, ok := summarizeOrchestrationParentChildStatus(task); ok {
				evidence.unfinished = append(evidence.unfinished, summary)
			}
		}
	}
	return evidence
}

func summarizeOrchestrationParentChildStatus(task map[string]any) (string, bool) {
	status := strings.ToLower(strings.TrimSpace(anyString(task["work_status"])))
	if status == "" || projectBootstrapTaskStatusTerminal(status) {
		return "", false
	}
	taskLabel := ""
	if taskNumber := anyInt(task["task_number"]); taskNumber > 0 {
		taskLabel = fmt.Sprintf("OC-%d", taskNumber)
	}
	title := strings.TrimSpace(anyString(task["title"]))
	switch {
	case taskLabel != "" && title != "":
		return fmt.Sprintf("%s (%s) is %s", taskLabel, title, status), true
	case taskLabel != "":
		return fmt.Sprintf("%s is %s", taskLabel, status), true
	case title != "":
		return fmt.Sprintf("%s is %s", title, status), true
	default:
		return fmt.Sprintf("a direct child task is %s", status), true
	}
}

type reviewMissingTestsEvidence struct {
	Summary string
}

func reviewMissingTestsRejectEvidenceFromGuardError(errText string) (string, bool) {
	trimmed := strings.TrimSpace(errText)
	if trimmed == "" {
		return "", false
	}
	lower := strings.ToLower(trimmed)
	if !strings.Contains(lower, "required test artifacts under") || !strings.Contains(lower, "call flow.review_decision with decision=reject immediately") {
		return "", false
	}
	const marker = "cannot be approved because "
	if idx := strings.Index(lower, marker); idx >= 0 {
		summary := strings.TrimSpace(trimmed[idx+len(marker):])
		if stop := strings.Index(strings.ToLower(summary), ". do not "); stop >= 0 {
			summary = strings.TrimSpace(summary[:stop])
		}
		summary = strings.TrimSpace(strings.TrimSuffix(summary, "."))
		if summary != "" {
			return summary, true
		}
	}
	return "required test artifacts could not be verified from the current workspace state", true
}

func currentTurnReviewMissingTestsEvidence(turnMessages []repo.ChatMessage, targetPath string) (reviewMissingTestsEvidence, bool) {
	targetPath = normalizeWorkspaceRelativePath(targetPath)
	primaryDeliverableReadable := false
	var summary string
	for _, message := range turnMessages {
		if !strings.EqualFold(strings.TrimSpace(message.Role), "tool_result") {
			continue
		}
		toolName, output, errText, ok := parseToolResultMessage(message.Content)
		if !ok {
			continue
		}
		if guardSummary, matched := reviewMissingTestsRejectEvidenceFromGuardError(errText); matched {
			summary = guardSummary
		}
		errorCode := normalizeValidationFailureCode(errText)
		if errorCode == "" {
			errorCode = normalizeValidationFailureCode(anyString(output["error"]))
		}
		normalizedToolName := strings.ToLower(strings.TrimSpace(toolName))
		path := normalizeWorkspaceRelativePath(anyString(output["path"]))
		if normalizedToolName == "file.read" && errorCode == "" && intValue(output["byte_size"]) > 0 && (targetPath == "" || sameWorkspaceRelativePath(path, targetPath)) {
			primaryDeliverableReadable = true
			continue
		}
		if !textMentionsTests(path) {
			continue
		}
		switch errorCode {
		case "not_found":
			summary = fmt.Sprintf("required test artifacts under `%s` were not found", path)
		case "recovery_target_focus_required", "explicit_deliverable_focus_required":
			deliverablePath := normalizeWorkspaceRelativePath(anyString(output["deliverable_path"]))
			if deliverablePath == "" {
				deliverablePath = targetPath
			}
			if deliverablePath != "" {
				summary = fmt.Sprintf("required test artifacts under `%s` could not be verified because review was redirected back to `%s`", path, deliverablePath)
			} else {
				summary = fmt.Sprintf("required test artifacts under `%s` could not be verified from the current workspace state", path)
			}
		}
	}
	if !primaryDeliverableReadable || strings.TrimSpace(summary) == "" {
		return reviewMissingTestsEvidence{}, false
	}
	return reviewMissingTestsEvidence{Summary: summary}, true
}

func reviewRetryPromptForMissingPreferredDeliverable(messages []repo.ChatMessage, latestCompleted *repo.ChatTurn, latestUser *repo.ChatMessage, executionID uuid.UUID, basePrompt string) (string, bool) {
	if latestCompleted == nil || latestCompleted.ID == uuid.Nil || latestUser == nil || executionID == uuid.Nil {
		return "", false
	}
	targetPath := parsePromptDeliverableTarget(latestUser.Content)
	if targetPath == "" {
		return "", false
	}
	turnMessages := messagesForTurn(messages, latestCompleted.ID)
	if len(turnMessages) == 0 {
		return "", false
	}

	firstFileReadResultSeen := false
	firstFileReadWasNotFound := false
	successfulTargetRead := false
	for _, message := range turnMessages {
		if !strings.EqualFold(strings.TrimSpace(message.Role), "tool_result") {
			continue
		}
		toolName, output, errText, ok := parseToolResultMessage(message.Content)
		if !ok || !strings.EqualFold(strings.TrimSpace(toolName), "file.read") {
			continue
		}
		errorCode := normalizeValidationFailureCode(errText)
		if errorCode == "" {
			errorCode = normalizeValidationFailureCode(anyString(output["error"]))
		}
		path := normalizeWorkspaceRelativePath(anyString(output["path"]))
		if !firstFileReadResultSeen {
			firstFileReadResultSeen = true
			firstFileReadWasNotFound = errorCode == "not_found" && (path == "" || path == targetPath)
		}
		if errorCode == "" && path == targetPath && intValue(output["byte_size"]) > 0 {
			successfulTargetRead = true
		}
	}
	if successfulTargetRead || !firstFileReadWasNotFound {
		return "", false
	}

	retryPrompt := basePrompt +
		"\nYour last review attempt already established that the preferred deliverable target `" + targetPath + "` is missing from the workspace." +
		" Do not search alternate paths, casing variants, sibling directories, or companion files now." +
		" Call flow.review_decision immediately with decision=reject, flow_node_execution_id " + executionID.String() + ", and concise findings that the expected deliverable `" + targetPath + "` is missing." +
		" Use the missing preferred deliverable as the rejection evidence." +
		" Do not reply with explanation text, a review plan, or placeholder arguments."
	return retryPrompt, true
}

func reviewRetryPromptForRepeatedCheckpointOutputRereads(messages []repo.ChatMessage, latestCompleted *repo.ChatTurn, latestUser *repo.ChatMessage, executionID uuid.UUID, basePrompt string) (string, bool) {
	if latestCompleted == nil || latestCompleted.ID == uuid.Nil || latestUser == nil || executionID == uuid.Nil {
		return "", false
	}
	rootPath := parsePromptDeliverableRoot(latestUser.Content)
	if rootPath == "" || !strings.Contains(latestUser.Content, "The checkpoint already identifies the task-owned outputs under `"+rootPath+"`") {
		return "", false
	}
	turnMessages := messagesForTurn(messages, latestCompleted.ID)
	currentPaths := successfulReviewReadPathsWithinRoot(turnMessages, rootPath)
	if len(currentPaths) < 2 {
		return "", false
	}
	previousPaths := successfulReviewReadPathsBeforeTurn(messages, latestCompleted.ID, rootPath)
	if len(previousPaths) == 0 {
		return "", false
	}
	repeatedPaths := make([]string, 0, len(currentPaths))
	for _, path := range currentPaths {
		if _, ok := previousPaths[path]; ok {
			repeatedPaths = append(repeatedPaths, path)
		}
	}
	if len(repeatedPaths) < 2 {
		return "", false
	}

	retryPrompt := basePrompt +
		"\nCheckpoint outputs already inspected in earlier review turns under `" + rootPath + "`." +
		"\nDo not reread these already-inspected checkpoint outputs this turn: " + quotedPathList(repeatedPaths, 4) + "." +
		" Those files were already read successfully in earlier review turns for this same review step." +
		" Do not reread those files from byte 0 again, and do not re-list `" + rootPath + "` just to sample the same batch." +
		" Use the evidence already gathered across this review session and call flow.review_decision now with flow_node_execution_id " + executionID.String() + "." +
		" If one final spot-check is truly required, inspect at most one different output under `" + rootPath + "` that is not already named above." +
		" Do not reply with a review plan or generic explanation."
	return retryPrompt, true
}

func reviewRetryPromptForMissingSecondaryPlanningArtifacts(messages []repo.ChatMessage, latestCompleted *repo.ChatTurn, latestUser *repo.ChatMessage, taskRecord repo.ProjectTask, executionID uuid.UUID, basePrompt string) (string, bool) {
	if latestCompleted == nil || latestCompleted.ID == uuid.Nil || latestUser == nil || executionID == uuid.Nil {
		return "", false
	}
	if taskLooksLikeOrchestrationOnlyParent(taskRecord) || len(reviewPromptArtifactContracts(taskRecord)) != 0 {
		return "", false
	}

	turnMessages := messagesForTurn(messages, latestCompleted.ID)
	if len(turnMessages) == 0 || !reviewTurnContainsRepeatedFileReadNotFoundStop(turnMessages) {
		return "", false
	}

	rootPath, samplePaths, hasDeliverables := reviewTurnDeliverableEvidence(turnMessages)
	if !hasDeliverables {
		return "", false
	}
	planningPaths := reviewTurnPlannedPlanningReadPaths(turnMessages)
	if len(planningPaths) == 0 {
		return "", false
	}

	deliverableEvidence := "the current deliverables"
	if rootPath != "" {
		deliverableEvidence = "the current deliverables under `" + rootPath + "`"
	}
	if len(samplePaths) > 0 {
		deliverableEvidence += " (for example " + quotedPathList(samplePaths, 3) + ")"
	}

	retryPrompt := basePrompt +
		"\nYour last review attempt already established that " + deliverableEvidence + " exist in the workspace." +
		" The missing files were secondary planning artifacts (" + quotedPathList(planningPaths, 3) + ")." +
		" Do not read `planning/` files again for this review, and do not repeat task.get, git.log, or broad workspace discovery just to restate the same context." +
		" Continue bounded review from the current deliverables only. If more evidence is needed, inspect one or two existing deliverables instead of rereading companion planning files." +
		" Then call flow.review_decision with flow_node_execution_id " + executionID.String() + " to approve or reject this review step." +
		" Do not reply with a review plan or generic explanation."
	return retryPrompt, true
}

func reviewTurnContainsRepeatedFileReadNotFoundStop(turnMessages []repo.ChatMessage) bool {
	for _, message := range turnMessages {
		if !strings.EqualFold(strings.TrimSpace(message.Role), "system") {
			continue
		}
		if strings.Contains(message.Content, reviewRepeatedFileReadNotFoundTurnStopSubstring) {
			return true
		}
	}
	return false
}

func reviewTurnDeliverableEvidence(turnMessages []repo.ChatMessage) (string, []string, bool) {
	rootPath := ""
	samplePaths := make([]string, 0, 3)
	seen := map[string]struct{}{}
	for _, message := range turnMessages {
		if !strings.EqualFold(strings.TrimSpace(message.Role), "tool_result") {
			continue
		}
		toolName, output, errText, ok := parseToolResultMessage(message.Content)
		if !ok || normalizeValidationFailureCode(errText) != "" {
			continue
		}
		switch strings.ToLower(strings.TrimSpace(toolName)) {
		case "file.list":
			path := normalizeWorkspaceRelativePath(anyString(output["path"]))
			if path == "" || projectBootstrapRecoveryReadsPlanningPath(map[string]any{"path": path}) {
				continue
			}
			entries, _ := output["entries"].([]any)
			if len(entries) == 0 {
				continue
			}
			if rootPath == "" {
				rootPath = path
			}
			for _, rawEntry := range entries {
				entry, _ := rawEntry.(map[string]any)
				entryPath := normalizeWorkspaceRelativePath(anyString(entry["path"]))
				if entryPath == "" {
					continue
				}
				if projectBootstrapRecoveryReadsPlanningPath(map[string]any{"path": entryPath}) {
					continue
				}
				if _, ok := seen[entryPath]; ok {
					continue
				}
				seen[entryPath] = struct{}{}
				samplePaths = append(samplePaths, entryPath)
				if len(samplePaths) >= 3 {
					break
				}
			}
		case "file.read":
			path := normalizeWorkspaceRelativePath(anyString(output["path"]))
			if path == "" || projectBootstrapRecoveryReadsPlanningPath(map[string]any{"path": path}) || intValue(output["byte_size"]) <= 0 {
				continue
			}
			if rootPath == "" {
				rootPath = path
			}
			if _, ok := seen[path]; ok {
				continue
			}
			seen[path] = struct{}{}
			samplePaths = append(samplePaths, path)
		}
		if len(samplePaths) >= 3 && rootPath != "" {
			break
		}
	}
	if rootPath == "" && len(samplePaths) == 0 {
		return "", nil, false
	}
	return rootPath, samplePaths, true
}

func reviewTurnPlannedPlanningReadPaths(turnMessages []repo.ChatMessage) []string {
	paths := make([]string, 0, 3)
	seen := map[string]struct{}{}
	for _, message := range turnMessages {
		if !strings.EqualFold(strings.TrimSpace(message.Role), "assistant") || len(message.Metadata) == 0 {
			continue
		}
		var meta struct {
			ToolCalls []storedAssistantToolCall `json:"tool_calls"`
		}
		if err := json.Unmarshal(message.Metadata, &meta); err != nil {
			continue
		}
		for _, call := range meta.ToolCalls {
			switch strings.ToLower(strings.TrimSpace(call.Name)) {
			case "file.read", "file_read":
			default:
				continue
			}
			path := normalizeWorkspaceRelativePath(anyString(call.Arguments["path"]))
			if path == "" || !projectBootstrapRecoveryReadsPlanningPath(map[string]any{"path": path}) {
				continue
			}
			if _, ok := seen[path]; ok {
				continue
			}
			seen[path] = struct{}{}
			paths = append(paths, path)
			if len(paths) >= 3 {
				return paths
			}
		}
	}
	return paths
}

func successfulReviewReadPathsWithinRoot(messages []repo.ChatMessage, rootPath string) []string {
	rootPath = normalizeWorkspaceRelativePath(rootPath)
	if rootPath == "" || len(messages) == 0 {
		return nil
	}
	seen := make(map[string]struct{})
	paths := make([]string, 0, 4)
	for _, message := range messages {
		if !strings.EqualFold(strings.TrimSpace(message.Role), "tool_result") {
			continue
		}
		toolName, output, errText, ok := parseToolResultMessage(message.Content)
		if !ok || !strings.EqualFold(strings.TrimSpace(toolName), "file.read") {
			continue
		}
		if errorCode := normalizeValidationFailureCode(errText); errorCode != "" {
			continue
		}
		path := normalizeWorkspaceRelativePath(anyString(output["path"]))
		if path == "" || !workspacePathWithinRoot(path, rootPath) || intValue(output["byte_size"]) <= 0 {
			continue
		}
		if offsetBytes := intValue(output["offset_bytes"]); offsetBytes > 0 {
			continue
		}
		if _, ok := seen[path]; ok {
			continue
		}
		seen[path] = struct{}{}
		paths = append(paths, path)
	}
	return paths
}

func successfulReviewReadPathsBeforeTurn(messages []repo.ChatMessage, currentTurnID uuid.UUID, rootPath string) map[string]struct{} {
	rootPath = normalizeWorkspaceRelativePath(rootPath)
	if rootPath == "" || currentTurnID == uuid.Nil || len(messages) == 0 {
		return nil
	}
	paths := make(map[string]struct{})
	for _, message := range messages {
		if message.TurnID == nil || *message.TurnID == currentTurnID {
			continue
		}
		if !strings.EqualFold(strings.TrimSpace(message.Role), "tool_result") {
			continue
		}
		toolName, output, errText, ok := parseToolResultMessage(message.Content)
		if !ok || !strings.EqualFold(strings.TrimSpace(toolName), "file.read") {
			continue
		}
		if errorCode := normalizeValidationFailureCode(errText); errorCode != "" {
			continue
		}
		path := normalizeWorkspaceRelativePath(anyString(output["path"]))
		if path == "" || !workspacePathWithinRoot(path, rootPath) || intValue(output["byte_size"]) <= 0 {
			continue
		}
		if offsetBytes := intValue(output["offset_bytes"]); offsetBytes > 0 {
			continue
		}
		paths[path] = struct{}{}
	}
	if len(paths) == 0 {
		return nil
	}
	return paths
}

func quotedPathList(paths []string, limit int) string {
	if len(paths) == 0 {
		return ""
	}
	if limit <= 0 || limit > len(paths) {
		limit = len(paths)
	}
	parts := make([]string, 0, limit)
	for _, path := range paths[:limit] {
		normalized := normalizeWorkspaceRelativePath(path)
		if normalized == "" {
			continue
		}
		parts = append(parts, "`"+normalized+"`")
	}
	return strings.Join(parts, ", ")
}

func taskReviewRequiresTests(taskRecord repo.ProjectTask) bool {
	description := ""
	if taskRecord.Description != nil {
		description = strings.TrimSpace(*taskRecord.Description)
	}
	return textMentionsTests(strings.TrimSpace(taskRecord.Title)) || textMentionsTests(description)
}

func textMentionsTests(content string) bool {
	lower := strings.ToLower(strings.TrimSpace(content))
	return containsAny(lower,
		"write tests",
		"test coverage",
		"tests",
		"test file",
		"pytest",
	)
}

func (e *TurnEngine) blockReviewTurnWithoutDecision(
	ctx context.Context,
	session *chat.ChatSession,
	taskRecord repo.ProjectTask,
	latestUser *repo.ChatMessage,
	latestCompleted *repo.ChatTurn,
	reason string,
	systemMessage string,
	assistantContent string,
) (bool, error) {
	if e == nil || session == nil || latestUser == nil || latestCompleted == nil {
		return true, nil
	}
	if _, err := e.appendSystemMessage(ctx, latestCompleted.ID, session.ID, systemMessage); err != nil {
		return true, err
	}
	if e.taskTransitions == nil {
		return true, fmt.Errorf(errMissingTaskTransitionServiceForRecoveryBlock)
	}
	updatedTask, err := e.persistBlockedReviewDecisionValidationGuard(ctx, taskRecord, latestUser, latestCompleted)
	if err != nil {
		return true, err
	}
	if strings.TrimSpace(assistantContent) != "" {
		snippet, _ := truncateRecoveryResumeExcerpt(assistantContent, 160)
		reason += fmt.Sprintf(": %s", snippet)
	}
	if _, err := e.taskTransitions.MarkBlocked(ctx, updatedTask.ID, reason, tasksvc.Actor{Type: "system"}); err != nil {
		return true, err
	}
	return true, nil
}

func (e *TurnEngine) repeatedEmptyReviewOutputTurnCapReached(ctx context.Context, sessionID uuid.UUID, currentTurn *repo.ChatTurn) (int, bool, error) {
	if e == nil || e.turns == nil || e.messages == nil || sessionID == uuid.Nil || currentTurn == nil || currentTurn.ID == uuid.Nil {
		return 0, false, nil
	}
	turns, err := e.turns.ListBySession(ctx, sessionID)
	if err != nil {
		return 0, false, err
	}
	messages, err := e.messages.ListBySession(ctx, sessionID)
	if err != nil {
		return 0, false, err
	}
	count := consecutiveRecentReviewEmptyOutputTurnCount(turns, messages, currentTurn, maxEmptyReviewOutputCapTurns)
	return count, count >= maxEmptyReviewOutputCapTurns, nil
}

func (e *TurnEngine) repeatedReviewValidationLoopMessageTurnCapReached(ctx context.Context, sessionID uuid.UUID, currentTurn *repo.ChatTurn, substring string, threshold int) (int, bool, error) {
	if e == nil || e.turns == nil || e.messages == nil || sessionID == uuid.Nil || currentTurn == nil || currentTurn.ID == uuid.Nil || strings.TrimSpace(substring) == "" || threshold <= 0 {
		return 0, false, nil
	}
	turns, err := e.turns.ListBySession(ctx, sessionID)
	if err != nil {
		return 0, false, err
	}
	messages, err := e.messages.ListBySession(ctx, sessionID)
	if err != nil {
		return 0, false, err
	}
	count := consecutiveRecentReviewSystemMessageTurnCount(turns, messages, currentTurn, substring, threshold)
	return count, count >= threshold, nil
}

func (e *TurnEngine) reviewApprovalWorkspaceClean(ctx context.Context, taskRecord repo.ProjectTask) (bool, error) {
	root, err := e.taskWorkspaceRoot(ctx, taskRecord)
	if err != nil {
		return false, err
	}
	dirty, err := flowcommit.WorktreeDirty(ctx, root)
	if err != nil {
		return false, err
	}
	return !dirty, nil
}

func latestReviewApprovalAttemptBlockedOnDirtyWorkspace(messages []repo.ChatMessage, executionID uuid.UUID) bool {
	if executionID == uuid.Nil {
		return false
	}
	for i := len(messages) - 1; i >= 0; i-- {
		msg := messages[i]
		if !strings.EqualFold(strings.TrimSpace(msg.Role), "tool_result") {
			continue
		}
		if !strings.Contains(msg.Content, "review_approval_requires_clean_workspace") {
			continue
		}
		for j := i - 1; j >= 0; j-- {
			assistant := messages[j]
			if !strings.EqualFold(strings.TrimSpace(assistant.Role), "assistant") {
				continue
			}
			if assistantEmittedReviewDecisionCall(assistant.Metadata, executionID, "approve") {
				return true
			}
		}
	}
	return false
}

func latestReviewApprovalAttemptRequiresHumanContinuation(messages []repo.ChatMessage, executionID uuid.UUID) bool {
	if executionID == uuid.Nil {
		return false
	}
	humanContinuationText := strings.ToLower(tasksvc.ErrBlockedInProgressRequiresHumanActor.Error())
	for i := len(messages) - 1; i >= 0; i-- {
		msg := messages[i]
		if !strings.EqualFold(strings.TrimSpace(msg.Role), "tool_result") {
			continue
		}
		if !strings.Contains(strings.ToLower(msg.Content), humanContinuationText) {
			continue
		}
		for j := i - 1; j >= 0; j-- {
			assistant := messages[j]
			if !strings.EqualFold(strings.TrimSpace(assistant.Role), "assistant") {
				continue
			}
			if assistantEmittedReviewDecisionCall(assistant.Metadata, executionID, "approve") {
				return true
			}
		}
	}
	return false
}

func parseFlowNodeExecutionIDFromMetadata(metadata json.RawMessage) uuid.UUID {
	value := strings.TrimSpace(stringValue(messageMetadataMap(metadata)["flow_node_execution_id"]))
	if value == "" {
		return uuid.Nil
	}
	parsed, err := uuid.Parse(value)
	if err != nil {
		return uuid.Nil
	}
	return parsed
}

func assistantEmittedReviewDecisionCall(metadata json.RawMessage, executionID uuid.UUID, decision string) bool {
	if executionID == uuid.Nil || strings.TrimSpace(decision) == "" || len(metadata) == 0 {
		return false
	}
	var payload struct {
		ToolCalls []struct {
			Name      string         `json:"name"`
			Arguments map[string]any `json:"arguments"`
		} `json:"tool_calls"`
	}
	if err := json.Unmarshal(metadata, &payload); err != nil {
		return false
	}
	for _, call := range payload.ToolCalls {
		name := strings.TrimSpace(call.Name)
		if !strings.EqualFold(name, "flow.review_decision") && !strings.EqualFold(name, "flow_review_decision") {
			continue
		}
		if !strings.EqualFold(strings.TrimSpace(stringValue(call.Arguments["decision"])), decision) {
			continue
		}
		if !strings.EqualFold(strings.TrimSpace(stringValue(call.Arguments["flow_node_execution_id"])), executionID.String()) {
			continue
		}
		return true
	}
	return false
}

func (e *TurnEngine) handleCompletedProjectBootstrapEmptyAssistantTurn(
	ctx context.Context,
	session *chat.ChatSession,
	latestCompleted *repo.ChatTurn,
	latestUser *repo.ChatMessage,
	assistant *repo.ChatMessage,
	messages []repo.ChatMessage,
	state projectBootstrapState,
	progress projectBootstrapProgress,
	now time.Time,
) (bool, error) {
	if e == nil || session == nil || latestCompleted == nil || latestUser == nil || assistant == nil {
		return false, nil
	}
	if !strings.EqualFold(strings.TrimSpace(session.ScopeType), "project") ||
		!strings.EqualFold(strings.TrimSpace(session.Mode), "async") {
		return false, nil
	}
	if !strings.EqualFold(strings.TrimSpace(stringValue(messageMetadataMap(latestUser.Metadata)["source"])), projectBootstrapSource) {
		return false, nil
	}
	assistantContent := strings.TrimSpace(assistant.Content)
	emptyAssistant := assistantContent == ""
	genericAssistant := looksLikeGenericTaskRecoveryReply(assistantContent)
	if (!emptyAssistant && !genericAssistant) || turnHasSuccessfulToolResult(messages, latestCompleted.ID) {
		return false, nil
	}

	nextAutoTurnCount := state.AutoTurnCount + 1
	if nextAutoTurnCount >= maxProjectBootstrapAutoTurns {
		return false, nil
	}

	state.Status = projectBootstrapStatusActive
	state.LastTurnID = latestCompleted.ID.String()
	state.BootstrapTaskID = progress.BootstrapTaskID.String()
	state.BootstrapTaskOutstanding = progress.BootstrapTaskOutstanding
	applyProjectBootstrapProgressState(&state, progress)
	state.AutoTurnCount = nextAutoTurnCount
	state.UpdatedAt = &now
	state.CompletedAt = nil
	state.FailedAt = nil
	state.FailureCategory = ""
	state.FailureClass = ""
	state.FailurePhase = ""
	state.FailureReason = ""
	state.ProviderFailureClass = ""
	state.ProviderFailureReason = ""
	if latestCompleted.RespondingID != uuid.Nil {
		state.LastResponderID = latestCompleted.RespondingID.String()
	}
	if err := e.updateProjectBootstrapState(ctx, session, state); err != nil {
		return true, err
	}
	notice := "[Bootstrap follow-on turn returned empty assistant output. Retrying with a fresh bootstrap-resume prompt that requires concrete tool action or a concrete blocker.]"
	retryTail := " Your last bootstrap follow-on turn returned empty assistant output. Do not reply with blank text, acknowledgement, or a state summary. Your next assistant action must either emit the concrete tool calls that materially advance bootstrap or explain one concrete blocker preventing those tool calls."
	if genericAssistant {
		notice = "[Bootstrap follow-on turn returned a generic non-action reply. Retrying with a fresh bootstrap-resume prompt that requires direct bootstrap action.]"
		retryTail = " Your last bootstrap follow-on turn returned a generic non-action reply instead of acting directly. Do not ask for details, ask what to do next, or ask what function call is needed. Your next assistant action must either emit the concrete tool calls that materially advance bootstrap or explain one concrete blocker preventing those tool calls."
	}
	if _, err := e.appendSystemMessage(ctx, latestCompleted.ID, session.ID, notice); err != nil {
		return true, err
	}
	if queued, err := e.hasQueuedAgentTurnForSession(ctx, session.ID, nil); err != nil {
		return true, err
	} else if queued {
		return true, nil
	}

	snapshot, err := e.loadProjectBootstrapResumeSnapshot(ctx, session.ScopeID, state)
	if err != nil {
		return true, err
	}
	retryPrompt := strings.TrimSpace(buildProjectBootstrapResumeActionPrompt(state, snapshot) + retryTail)
	continuationAgentID := e.projectBootstrapContinuationAgent(ctx, session, latestCompleted.RespondingID)
	continuationMessage, err := e.appendProjectBootstrapContinuationMessageWithContent(
		ctx,
		session.ID,
		continuationAgentID,
		state.InitialMessageID,
		state.AutoTurnCount,
		retryPrompt,
	)
	if err != nil {
		return true, err
	}

	nextPayload := AgentTurnPayload{
		SessionID:  session.ID,
		MessageID:  continuationMessage.ID,
		RetryCount: latestCompleted.RetryCount + 1,
	}
	if continuationAgentID != uuid.Nil {
		nextAgentID := continuationAgentID
		nextPayload.AgentID = &nextAgentID
	}
	runAfter := now.Add(defaultAutoContinueDelay)
	_, err = e.enqueueAgentTurnIfActive(ctx, session, nextPayload, &runAfter)
	if err != nil {
		return true, err
	}
	return true, nil
}

func (e *TurnEngine) persistBlockedReviewDecisionValidationGuard(
	ctx context.Context,
	taskRecord repo.ProjectTask,
	latestUser *repo.ChatMessage,
	latestCompleted *repo.ChatTurn,
) (repo.ProjectTask, error) {
	if e == nil || e.tasks == nil || latestUser == nil || latestCompleted == nil || taskRecord.ID == uuid.Nil {
		return taskRecord, nil
	}
	state := taskValidationGuardState{
		InitialMessageID:   latestUser.ID.String(),
		Fingerprint:        "flow.review_decision:required",
		AttemptFingerprint: "flow.review_decision:required:attempt",
		ToolName:           "flow.review_decision",
		FailureClass:       "tool_validation",
		FailureCode:        "review_decision_required",
		FailureReason:      "review turn completed without calling flow.review_decision",
		Count:              validationLoopBlockThreshold,
		BlockThreshold:     validationLoopBlockThreshold,
		Blocked:            true,
		LastTurnID:         latestCompleted.ID.String(),
	}
	nowValue := e.now().UTC().Format(time.RFC3339Nano)
	state.FirstSeenAt = nowValue
	state.LastSeenAt = nowValue
	merged, err := mergeTaskValidationGuardMetadata(taskRecord.Metadata, state)
	if err != nil {
		return taskRecord, err
	}
	taskRecord.Metadata = merged
	return updateTurnTaskMetadata(ctx, e.tasks, taskRecord)
}

func explicitReviewDecisionFromText(content string) (string, bool) {
	text := strings.ToLower(normalizeInstructionText(content))
	if strings.TrimSpace(text) == "" {
		return "", false
	}
	rejectSignals := []string{
		"review decision: reject",
		"review decision reject",
		"decision: reject",
		"decision reject",
		"sufficient evidence to reject",
		"enough evidence to reject",
		"reject for rework",
		"i am rejecting",
		"i'm rejecting",
		"do not approve",
		"rework required",
	}
	for _, signal := range rejectSignals {
		if strings.Contains(text, signal) {
			return "reject", true
		}
	}
	approveSignals := []string{
		"review decision: approve",
		"review decision approve",
		"decision: approve",
		"decision approve",
		"i am approving",
		"i'm approving",
		"approved for merge",
		"approve for merge",
	}
	for _, signal := range approveSignals {
		if strings.Contains(text, signal) {
			return "approve", true
		}
	}
	if inferredReviewRejectFromText(text) {
		return "reject", true
	}
	return "", false
}

func inferredReviewRejectFromText(text string) bool {
	trimmed := strings.TrimSpace(text)
	if trimmed == "" {
		return false
	}
	if strings.Contains(trimmed, "let me check") || strings.Contains(trimmed, "let me inspect") || strings.Contains(trimmed, "let me read") {
		// Keep this heuristic for findings-forward review output, not tentative exploration.
		// If the reviewer already states enough failure evidence before proposing more browsing,
		// the stronger evidence checks below still allow synthesis.
	}

	strongRejectSignals := []string{
		"**rejection**",
		"the work deliverable is incomplete",
		"does not meet acceptance criteria",
		"placeholder text",
		"contains only a placeholder",
		"scaffold placeholder",
		"scaffolds only",
		"not met",
	}
	for _, signal := range strongRejectSignals {
		if strings.Contains(text, signal) {
			return true
		}
	}

	evidenceSignals := 0
	for _, signal := range []string{
		"placeholder",
		"incomplete",
		"missing",
		"not present",
		"not found",
		"scaffold",
		"does not meet",
		"not met",
		"required planning artifacts",
		"required companion artifacts",
		"required artifacts",
	} {
		if strings.Contains(text, signal) {
			evidenceSignals++
		}
	}
	return evidenceSignals >= 2 && strings.Contains(text, "deliverable")
}

func messagesFromTaskSession(ctx context.Context, e *TurnEngine, session *chat.ChatSession) []repo.ChatMessage {
	if e == nil || e.messages == nil || session == nil {
		return nil
	}
	messages, err := e.messages.ListBySession(ctx, session.ID)
	if err != nil {
		return nil
	}
	return messages
}

func messagesForTurn(messages []repo.ChatMessage, turnID uuid.UUID) []repo.ChatMessage {
	if turnID == uuid.Nil || len(messages) == 0 {
		return nil
	}
	filtered := make([]repo.ChatMessage, 0, len(messages))
	for _, message := range messages {
		if message.TurnID == nil || *message.TurnID != turnID {
			continue
		}
		filtered = append(filtered, message)
	}
	return filtered
}

func recoveryTurnProducedDurableWrite(taskRecord repo.ProjectTask, messages []repo.ChatMessage) bool {
	if len(messages) == 0 {
		return false
	}
	checkpoint, hasCheckpoint := taskcheckpoint.ParseRecoveryFileWriteCheckpoint(taskRecord.Metadata)
	for _, message := range messages {
		if !strings.EqualFold(strings.TrimSpace(message.Role), "tool_result") {
			continue
		}
		toolName, output, errText, ok := parseToolResultMessage(message.Content)
		if !ok || strings.TrimSpace(errText) != "" {
			continue
		}
		result := ToolResult{Name: toolName, Output: output}
		if substantiveExecutionDeliverableReadCompleted(taskRecord, result) || explicitExecutionDeliverableWriteCompleted(taskRecord, result) {
			return true
		}
		if !hasCheckpoint && strings.EqualFold(strings.TrimSpace(toolName), "file.write") && anyInt(output["byte_size"]) > 0 {
			return true
		}
		targetPath := ""
		if hasCheckpoint {
			targetPath = normalizeWorkspaceRelativePath(checkpoint.TargetPath)
		}
		if targetPath == "" {
			continue
		}
		switch strings.ToLower(strings.TrimSpace(toolName)) {
		case "file.write":
			writtenPath := normalizeWorkspaceRelativePath(anyString(output["path"]))
			if writtenPath != "" && sameWorkspaceRelativePath(writtenPath, targetPath) && anyInt(output["byte_size"]) > 0 {
				return true
			}
		case "file.read":
			readPath := normalizeWorkspaceRelativePath(anyString(output["path"]))
			if readPath != "" && sameWorkspaceRelativePath(readPath, targetPath) && strings.TrimSpace(anyString(output["content"])) != "" {
				return true
			}
		}
	}
	return false
}

func (e *TurnEngine) HandleTurnCancelledEvent(ctx context.Context, event eventbus.DomainEvent) error {
	if event.EventType != "chat.turn.cancelled" {
		return nil
	}
	if strings.EqualFold(strings.TrimSpace(event.ActorType), "human") {
		return nil
	}

	var payload struct {
		SessionID uuid.UUID `json:"session_id"`
		TurnID    uuid.UUID `json:"turn_id"`
	}
	if err := json.Unmarshal(event.Payload, &payload); err != nil {
		return nil
	}
	if payload.SessionID == uuid.Nil || payload.TurnID == uuid.Nil {
		return nil
	}

	session, err := e.chat.GetSession(ctx, payload.SessionID)
	if err != nil {
		if errors.Is(err, repo.ErrNotFound) {
			return nil
		}
		return err
	}
	if strings.EqualFold(strings.TrimSpace(session.ScopeType), "project") {
		return e.handleProjectBootstrapCancelledTurn(ctx, session, payload.TurnID)
	}
	if !strings.EqualFold(strings.TrimSpace(session.ScopeType), "project_task") || e.tasks == nil {
		return nil
	}
	taskRecord, err := e.tasks.GetByID(ctx, session.ScopeID)
	if err != nil {
		if errors.Is(err, repo.ErrNotFound) {
			return nil
		}
		return err
	}
	_, err = e.maybeContinueProjectExecutionAfterTerminalTaskTurn(ctx, taskRecord)
	return err
}

func (e *TurnEngine) maybeContinueProjectExecutionAfterTerminalTaskTurn(ctx context.Context, taskRecord repo.ProjectTask) (bool, error) {
	if e == nil || e.pool == nil || taskRecord.ID == uuid.Nil || taskRecord.ProjectID == uuid.Nil {
		return false, nil
	}
	switch strings.ToLower(strings.TrimSpace(taskRecord.WorkStatus)) {
	case "done", "cancelled":
	default:
		return false, nil
	}
	metadata := messageMetadataMap(taskRecord.Metadata)
	if bootstrapGate, _ := metadata["bootstrap_gate"].(bool); bootstrapGate {
		return false, nil
	}
	if setupTask, _ := metadata["bootstrap_setup_task"].(bool); setupTask {
		return false, nil
	}
	if err := e.maybeContinueProjectExecutionAfterTaskCompletion(ctx, taskRecord.ProjectID, taskRecord); err != nil {
		return false, err
	}
	return true, nil
}

func (e *TurnEngine) HandleTaskStatusChangedEvent(ctx context.Context, event eventbus.DomainEvent) error {
	if event.EventType != "task.status_changed" || e == nil || e.pool == nil {
		return nil
	}

	var payload struct {
		TaskID    string `json:"task_id"`
		ProjectID string `json:"project_id"`
		ToStatus  string `json:"to_status"`
	}
	if err := json.Unmarshal(event.Payload, &payload); err != nil {
		return nil
	}
	if !strings.EqualFold(strings.TrimSpace(payload.ToStatus), "done") {
		return nil
	}

	projectID, err := uuid.Parse(strings.TrimSpace(payload.ProjectID))
	if err != nil || projectID == uuid.Nil {
		return nil
	}
	taskID, err := uuid.Parse(strings.TrimSpace(payload.TaskID))
	if err != nil || taskID == uuid.Nil {
		return nil
	}

	taskRecord, err := repo.NewProjectTaskRepo(e.pool).GetByID(ctx, taskID)
	if err != nil {
		if errors.Is(err, repo.ErrNotFound) {
			return nil
		}
		return err
	}
	metadata := messageMetadataMap(taskRecord.Metadata)
	if bootstrapGate, _ := metadata["bootstrap_gate"].(bool); !bootstrapGate {
		if setupTask, _ := metadata["bootstrap_setup_task"].(bool); !setupTask {
			return e.maybeContinueProjectExecutionAfterTaskCompletion(ctx, projectID, taskRecord)
		}
	}

	session, err := repo.NewChatSessionRepo(e.pool).GetByScopeAndMode(ctx, "project", projectID, "async")
	if err != nil {
		if errors.Is(err, repo.ErrNotFound) {
			return nil
		}
		return err
	}

	progress, err := e.loadProjectBootstrapProgress(ctx, projectID)
	if err != nil {
		return err
	}
	if progress.BootstrapTaskID == uuid.Nil {
		return nil
	}
	if progress.ValidationFailed() {
		return e.refreshProjectBootstrapSessionState(ctx, session, progress)
	}

	progress, err = e.ensureProjectBootstrapFirstWaveExecution(ctx, progress)
	if err != nil {
		return err
	}
	return e.refreshProjectBootstrapSessionState(ctx, session, progress)
}

func (e *TurnEngine) maybeContinueProjectExecutionAfterTaskCompletion(ctx context.Context, projectID uuid.UUID, completedTask repo.ProjectTask) error {
	if e == nil || e.pool == nil || e.chat == nil || e.enqueuer == nil || projectID == uuid.Nil {
		return nil
	}

	session, err := repo.NewChatSessionRepo(e.pool).GetByScopeAndMode(ctx, "project", projectID, "async")
	if err != nil {
		if errors.Is(err, repo.ErrNotFound) {
			return nil
		}
		return err
	}
	if !strings.EqualFold(strings.TrimSpace(session.Status), "active") {
		return nil
	}

	state := projectBootstrapStateFromMetadata(session.Metadata)
	switch strings.TrimSpace(state.Status) {
	case projectBootstrapStatusActive, projectBootstrapStatusFailed:
		return nil
	}

	if session.CurrentTurnID != nil {
		cleared, err := e.cancelSupersededProjectContinuationTurn(ctx, session, completedTask.ID)
		if err != nil {
			return err
		}
		if !cleared {
			return nil
		}
	}
	if queued, err := e.hasQueuedAgentTurnForSession(ctx, session.ID, nil); err != nil {
		return err
	} else if queued {
		return nil
	}

	remainingDraftTasks, err := e.countProjectDraftTasks(ctx, projectID)
	if err != nil {
		return err
	}

	var activeTaskWork int
	if err := e.pool.QueryRow(ctx, `
		SELECT COUNT(*)
		FROM project_task
		WHERE project_id = $1
		  AND work_status IN ('queued', 'in_progress', 'review')
	`, projectID).Scan(&activeTaskWork); err != nil {
		return err
	}
	if activeTaskWork > 0 {
		return nil
	}

	var activeTaskExecutions int
	if err := e.pool.QueryRow(ctx, `
		SELECT COUNT(*)
		FROM flow_node_execution e
		JOIN project_task t ON t.id = e.task_id
		WHERE t.project_id = $1
		  AND lower(trim(t.work_status)) NOT IN ('done', 'cancelled')
		  AND e.status = 'active'
	`, projectID).Scan(&activeTaskExecutions); err != nil {
		return err
	}
	if activeTaskExecutions > 0 {
		return nil
	}

	var activeTaskSessions int
	if err := e.pool.QueryRow(ctx, `
		SELECT COUNT(*)
		FROM chat_session cs
		JOIN project_task t ON t.id = cs.scope_id
		WHERE cs.scope_type = 'project_task'
		  AND cs.mode = 'async'
		  AND cs.status = 'active'
		  AND t.project_id = $1
		  AND lower(trim(t.work_status)) NOT IN ('done', 'cancelled')
	`, projectID).Scan(&activeTaskSessions); err != nil {
		return err
	}
	if activeTaskSessions > 0 {
		return nil
	}

	pendingContinuationMessages, err := e.countPendingProjectContinuationMessages(ctx, session.ID)
	if err != nil {
		return err
	}
	if remainingDraftTasks == 0 {
		if pendingContinuationMessages > 0 {
			if err := e.failPendingProjectContinuationMessages(ctx, session.ID, "project execution already settled"); err != nil {
				return err
			}
		}
		_, err := repo.NewChatSessionRepo(e.pool).Close(ctx, session.ID)
		return err
	}
	if pendingContinuationMessages > 0 {
		return nil
	}

	agentID, err := e.resolveSessionAgentForSession(ctx, session)
	if err != nil && !errors.Is(err, repo.ErrNotFound) {
		return err
	}
	snapshot, err := e.projectExecutionContinuationSnapshot(ctx, session.ScopeID)
	if err != nil {
		return err
	}

	message, err := e.appendProjectExecutionContinuationMessage(
		ctx,
		session.ID,
		agentID,
		completedTask.ID,
		buildProjectExecutionContinuationPrompt(completedTask, remainingDraftTasks, snapshot),
	)
	if err != nil {
		return err
	}
	if message == nil {
		return nil
	}

	payload := AgentTurnPayload{
		SessionID: session.ID,
		MessageID: message.ID,
	}
	if agentID != uuid.Nil {
		payload.AgentID = &agentID
	}
	_, err = e.enqueueAgentTurnIfActive(ctx, session, payload, nil)
	return err
}

func (e *TurnEngine) countPendingProjectContinuationMessages(ctx context.Context, sessionID uuid.UUID) (int, error) {
	if e == nil || e.pool == nil || sessionID == uuid.Nil {
		return 0, nil
	}
	var pendingContinuationMessages int
	if err := e.pool.QueryRow(ctx, `
		SELECT COUNT(*)
		FROM chat_message m
		WHERE m.session_id = $1
		  AND m.role = 'user'
		  AND COALESCE(NULLIF(m.metadata->>'source', ''), '') = $2
		  AND (
			NOT EXISTS (
				SELECT 1
				FROM chat_turn ct
				WHERE ct.trigger_message_id = m.id
			)
			OR EXISTS (
				SELECT 1
				FROM chat_turn ct
				WHERE ct.trigger_message_id = m.id
				  AND ct.status IN ('pending', 'in_progress')
			)
		  )
	`, sessionID, projectExecutionContinuationSource).Scan(&pendingContinuationMessages); err != nil {
		return 0, err
	}
	return pendingContinuationMessages, nil
}

func (e *TurnEngine) failPendingProjectContinuationMessages(ctx context.Context, sessionID uuid.UUID, reason string) error {
	if e == nil || e.pool == nil || sessionID == uuid.Nil {
		return nil
	}
	if strings.TrimSpace(reason) == "" {
		reason = "project continuation superseded"
	}
	_, err := e.pool.Exec(ctx, `
		UPDATE chat_message
		SET status = 'failed',
		    error_message = $2
		WHERE session_id = $1
		  AND role = 'user'
		  AND status = 'pending'
		  AND COALESCE(metadata->>'source', '') = $3
	`, sessionID, reason, projectExecutionContinuationSource)
	return err
}

func (e *TurnEngine) cancelSupersededProjectContinuationTurn(ctx context.Context, session *chat.ChatSession, completedTaskID uuid.UUID) (bool, error) {
	if e == nil || e.chat == nil || e.messages == nil || session == nil || session.CurrentTurnID == nil || completedTaskID == uuid.Nil {
		return false, nil
	}

	currentTurn, err := e.chat.GetTurn(ctx, *session.CurrentTurnID)
	if err != nil {
		if errors.Is(err, repo.ErrNotFound) {
			return false, nil
		}
		return false, err
	}
	if currentTurn.TriggerMessageID == nil || *currentTurn.TriggerMessageID == uuid.Nil {
		return false, nil
	}
	trigger, err := e.messages.GetByID(ctx, *currentTurn.TriggerMessageID)
	if err != nil {
		if errors.Is(err, repo.ErrNotFound) {
			return false, nil
		}
		return false, err
	}
	triggerMetadata := messageMetadataMap(trigger.Metadata)
	if !strings.EqualFold(strings.TrimSpace(stringValue(triggerMetadata["source"])), projectExecutionContinuationSource) {
		return false, nil
	}
	priorCompletedTaskID, ok := parseUUIDAny(triggerMetadata["completed_task_id"])
	if !ok || priorCompletedTaskID == uuid.Nil || priorCompletedTaskID == completedTaskID {
		return false, nil
	}
	if !strings.EqualFold(strings.TrimSpace(currentTurn.Status), "pending") &&
		!strings.EqualFold(strings.TrimSpace(currentTurn.Status), "in_progress") {
		return false, nil
	}
	if err := e.chat.CancelTurn(ctx, currentTurn.ID, "superseded by newer completed project task"); err != nil {
		if !errors.Is(err, chat.ErrInvalidStatusTransition) {
			return false, err
		}
		return false, nil
	}
	if e.pool != nil {
		if _, err := repo.NewChatSessionRepo(e.pool).UpdateCurrentTurn(ctx, session.ID, nil); err != nil && !errors.Is(err, repo.ErrNotFound) {
			return false, err
		}
	}
	if e.sessions != nil {
		if _, err := e.sessions.UpdateCurrentTurn(ctx, session.ID, nil); err != nil && !errors.Is(err, repo.ErrNotFound) {
			return false, err
		}
	}
	session.CurrentTurnID = nil
	return true, nil
}

func (e *TurnEngine) HandleProjectResumedEvent(ctx context.Context, event eventbus.DomainEvent) error {
	if event.EventType != "project.resumed" || e == nil || e.pool == nil || e.enqueuer == nil || e.chat == nil {
		return nil
	}

	var payload struct {
		ProjectID uuid.UUID `json:"project_id"`
	}
	if err := json.Unmarshal(event.Payload, &payload); err != nil {
		return nil
	}
	if payload.ProjectID == uuid.Nil {
		return nil
	}
	if err := e.clearProjectPauseAfterResume(ctx, payload.ProjectID); err != nil {
		return err
	}

	rows, err := e.pool.Query(ctx, `
		SELECT DISTINCT cs.id, ct.trigger_message_id
		FROM chat_session cs
		LEFT JOIN project_task pt
		  ON cs.scope_type = 'project_task'
		 AND pt.id = cs.scope_id
		JOIN chat_turn ct ON ct.id = cs.current_turn_id
		WHERE cs.mode = 'async'
		  AND cs.status = 'active'
		  AND ct.status = 'pending'
		  AND ct.trigger_message_id IS NOT NULL
		  AND (
		    (cs.scope_type = 'project' AND cs.scope_id = $1)
		    OR
		    (cs.scope_type = 'project_task' AND pt.project_id = $1)
		  )
		  AND NOT EXISTS (
		    SELECT 1
		    FROM job_queue jq
		    WHERE jq.job_type = $2
		      AND jq.status IN ('pending', 'claimed')
		      AND (jq.payload->>'session_id')::uuid = cs.id
		  )
	`, payload.ProjectID, AgentTurnJobType)
	if err != nil {
		return err
	}
	defer rows.Close()

	for rows.Next() {
		var sessionID uuid.UUID
		var messageID uuid.UUID
		if err := rows.Scan(&sessionID, &messageID); err != nil {
			return err
		}
		session, err := e.chat.GetSession(ctx, sessionID)
		if err != nil {
			if errors.Is(err, repo.ErrNotFound) {
				continue
			}
			return err
		}
		if _, err := e.enqueueAgentTurnForProjectResume(ctx, session, AgentTurnPayload{
			SessionID: sessionID,
			MessageID: messageID,
		}, nil); err != nil {
			return err
		}
	}
	if err := rows.Err(); err != nil {
		return err
	}

	pendingMessageRows, err := e.pool.Query(ctx, `
		SELECT DISTINCT cs.id, cm.id
		FROM chat_session cs
		LEFT JOIN project_task pt
		  ON cs.scope_type = 'project_task'
		 AND pt.id = cs.scope_id
		JOIN chat_message cm
		  ON cm.session_id = cs.id
		 AND cm.role = 'user'
		 AND cm.status = 'pending'
		LEFT JOIN chat_turn current_ct
		  ON current_ct.id = cs.current_turn_id
		WHERE cs.mode = 'async'
		  AND cs.status = 'active'
		  AND (
		    (cs.scope_type = 'project' AND cs.scope_id = $1)
		    OR
		    (cs.scope_type = 'project_task' AND pt.project_id = $1)
		  )
		  AND NOT (
		    cs.scope_type = 'project'
		    AND cs.scope_id = $1
		    AND COALESCE(cs.metadata->'project_bootstrap'->>'status', '') = $3
		  )
		  AND (
		    cs.current_turn_id IS NULL
		    OR current_ct.id IS NULL
		    OR current_ct.status IN ('completed', 'cancelled', 'failed')
		  )
		  AND NOT EXISTS (
		    SELECT 1
		    FROM chat_turn ct
		    WHERE ct.session_id = cs.id
		      AND ct.trigger_message_id = cm.id
		      AND ct.status IN ('pending', 'in_progress')
		  )
		  AND NOT EXISTS (
		    SELECT 1
		    FROM job_queue jq
		    WHERE jq.job_type = $2
		      AND jq.status IN ('pending', 'claimed')
		      AND (jq.payload->>'session_id')::uuid = cs.id
		      AND (jq.payload->>'message_id')::uuid = cm.id
		  )
	`, payload.ProjectID, AgentTurnJobType, projectBootstrapStatusFailed)
	if err != nil {
		return err
	}
	defer pendingMessageRows.Close()

	for pendingMessageRows.Next() {
		var sessionID uuid.UUID
		var messageID uuid.UUID
		if err := pendingMessageRows.Scan(&sessionID, &messageID); err != nil {
			return err
		}
		session, err := e.chat.GetSession(ctx, sessionID)
		if err != nil {
			if errors.Is(err, repo.ErrNotFound) {
				continue
			}
			return err
		}
		if _, err := e.enqueueAgentTurnForProjectResume(ctx, session, AgentTurnPayload{
			SessionID: sessionID,
			MessageID: messageID,
		}, nil); err != nil {
			return err
		}
	}
	if err := pendingMessageRows.Err(); err != nil {
		return err
	}

	failedBootstrapRows, err := e.pool.Query(ctx, `
		SELECT cs.id
		FROM chat_session cs
		WHERE cs.mode = 'async'
		  AND cs.status = 'active'
		  AND cs.scope_type = 'project'
		  AND cs.scope_id = $1
		  AND cs.current_turn_id IS NULL
		  AND COALESCE(cs.metadata->'project_bootstrap'->>'status', '') = $2
	`, payload.ProjectID, projectBootstrapStatusFailed)
	if err != nil {
		return err
	}
	defer failedBootstrapRows.Close()

	for failedBootstrapRows.Next() {
		var sessionID uuid.UUID
		if err := failedBootstrapRows.Scan(&sessionID); err != nil {
			return err
		}
		session, err := e.chat.GetSession(ctx, sessionID)
		if err != nil {
			if errors.Is(err, repo.ErrNotFound) {
				continue
			}
			return err
		}
		state := projectBootstrapStateFromMetadata(session.Metadata)
		if !strings.EqualFold(strings.TrimSpace(state.Status), projectBootstrapStatusFailed) {
			continue
		}
		progress, err := e.loadProjectBootstrapProgress(ctx, session.ScopeID)
		if err != nil {
			return err
		}
		if !progress.ValidationFailed() {
			continue
		}
		agentID, err := e.resolveSessionAgentForSession(ctx, session)
		if err != nil {
			return err
		}
		if agentID == uuid.Nil {
			continue
		}
		message, err := e.appendProjectBootstrapRecoveryContinuationMessage(ctx, session.ID, agentID, strings.TrimSpace(state.InitialMessageID), state.AutoTurnCount, progress)
		if err != nil {
			return err
		}
		if _, err := e.enqueueAgentTurnForProjectResume(ctx, session, AgentTurnPayload{
			SessionID: session.ID,
			MessageID: message.ID,
			AgentID:   &agentID,
		}, nil); err != nil {
			return err
		}
	}
	return failedBootstrapRows.Err()
}

func (e *TurnEngine) clearProjectPauseAfterResume(ctx context.Context, projectID uuid.UUID) error {
	if e == nil || e.pool == nil || projectID == uuid.Nil {
		return nil
	}
	projectRepo := repo.NewProjectRepo(e.pool)
	projectRecord, err := projectRepo.GetByID(ctx, projectID)
	if errors.Is(err, repo.ErrNotFound) {
		return nil
	}
	if err != nil {
		return err
	}
	pauseState := projectpause.Parse(projectRecord.Settings)
	if !pauseState.IsPaused {
		return nil
	}
	updated := projectRecord
	updated.Settings, err = projectpause.ClearPause(updated.Settings)
	if err != nil {
		return err
	}
	_, err = projectRepo.Update(ctx, updated)
	return err
}

func (e *TurnEngine) handleProjectBootstrapCompletedTurn(ctx context.Context, session *chat.ChatSession, turnID uuid.UUID) error {
	if e == nil || session == nil || turnID == uuid.Nil {
		return nil
	}
	if !strings.EqualFold(strings.TrimSpace(session.Status), "active") {
		return nil
	}
	if session.ScopeID == uuid.Nil || !strings.EqualFold(strings.TrimSpace(session.Mode), "async") {
		return nil
	}
	if paused, reason, pauseErr := e.projectPausedForSession(ctx, session); pauseErr != nil {
		return pauseErr
	} else if paused {
		e.logPausedTurnSkip("skipping bootstrap auto continuation for paused project", session, reason, turnID)
		return nil
	}

	progress, err := e.loadProjectBootstrapProgress(ctx, session.ScopeID)
	if err != nil {
		return err
	}

	turns, err := e.turns.ListBySession(ctx, session.ID)
	if err != nil {
		return err
	}
	latestCompleted := latestCompletedTurn(turns)
	if latestCompleted == nil || latestCompleted.ID != turnID {
		return nil
	}
	if shouldSuppressAutoContinuationForStopReason(latestCompleted.StopReason) {
		return nil
	}

	messages, err := e.messages.ListBySession(ctx, session.ID)
	if err != nil {
		return err
	}
	latestUser := latestUserMessage(messages)
	if latestUser == nil {
		return nil
	}
	assistant := latestAssistantFinalForTurn(messages, turnID)
	if assistant == nil || latestUser.SequenceNumber > assistant.SequenceNumber {
		return nil
	}
	if handled, handleErr := e.handleCompletedProjectExecutionContinuationTurn(ctx, session, latestCompleted, latestUser, assistant, messages); handleErr != nil {
		return handleErr
	} else if handled {
		return nil
	}

	state := projectBootstrapStateFromMetadata(session.Metadata)
	if !projectBootstrapCompletedTurnManaged(messages, latestUser, state, progress) {
		return nil
	}
	if strings.TrimSpace(state.LastTurnID) == turnID.String() {
		return nil
	}
	now := e.now().UTC()
	initialMessageID := projectBootstrapWorkflowMessageID(latestUser)
	if strings.TrimSpace(state.InitialMessageID) != initialMessageID.String() {
		state = projectBootstrapState{
			InitialMessageID: initialMessageID.String(),
			StartedAt:        &now,
		}
	}
	if progress.BootstrapTaskOutstanding && progress.BootstrapSetupTaskCount > 0 && !projectBootstrapStateActive(state) {
		state.Status = projectBootstrapStatusActive
	}
	if persisted, persistErr := e.syncProjectBootstrapSetupFromWorkspace(ctx, session, turnID); persistErr != nil {
		return persistErr
	} else if persisted {
		progress, err = e.loadProjectBootstrapProgress(ctx, session.ScopeID)
		if err != nil {
			return err
		}
	}
	progress, err = e.ensureProjectBootstrapFirstWaveExecution(ctx, progress)
	if err != nil {
		return err
	}
	if handled, handleErr := e.handleCompletedProjectBootstrapEmptyAssistantTurn(ctx, session, latestCompleted, latestUser, assistant, messages, state, progress, now); handleErr != nil {
		return handleErr
	} else if handled {
		return nil
	}
	narrativeClaimedCompletion := projectBootstrapNarrativeClaimsCompletion(assistant)
	normalizeProjectBootstrapValidationFailure(&progress, narrativeClaimedCompletion)
	blockedReason, blockedClass := projectBootstrapBlockedRecoveryFailure(messages, state)
	blockedByRereadGuard := projectBootstrapRecoveryEndedByRereadGuard(messages)
	if !progress.ValidationFailed() && latestCompleted.StopReason != nil && strings.TrimSpace(*latestCompleted.StopReason) == stopReasonValidationBlocked {
		if strings.TrimSpace(blockedReason) != "" {
			progress.ValidationStatus = projectBootstrapValidationFailed
			progress.ValidationFailureReason = blockedReason
			progress.ValidationFailureClass = blockedClass
		}
	}
	if strings.TrimSpace(blockedReason) != "" && projectBootstrapNarrativeOnlyReply(messages, assistant) && !blockedByRereadGuard {
		progress.ValidationStatus = projectBootstrapValidationFailed
		progress.ValidationFailureReason = buildProjectBootstrapNarrativeOnlyRecoveryFailureReason(blockedReason, assistant)
		progress.ValidationFailureClass = projectBootstrapFailureStalled
	}
	if !progress.ValidationFailed() && projectBootstrapRestartSession(session) && projectBootstrapRestartScaffoldOnly(progress) && projectBootstrapNarrativeOnlyReply(messages, assistant) && !blockedByRereadGuard {
		progress.ValidationStatus = projectBootstrapValidationFailed
		progress.ValidationFailureReason = buildProjectBootstrapNarrativeOnlyRestartFailureReason(assistant)
		progress.ValidationFailureClass = projectBootstrapFailureStalled
	}
	if narrativeClaimedCompletion && !progress.Materialized() {
		rt := &turnRuntime{session: session, turn: &chat.ChatTurn{ID: turnID}}
		if latestCompleted.RespondingID != uuid.Nil {
			rt.agent.ID = latestCompleted.RespondingID
		}
		if progress.ValidationFailed() {
			if handled, recoverErr := e.continueRecoverableProjectBootstrapValidation(ctx, rt, state, progress, now, false); recoverErr != nil {
				return recoverErr
			} else if handled {
				return nil
			}
		}
		return e.failProjectBootstrapValidation(ctx, rt, progress, now)
	}

	madeProgress := progress.AssignmentCount > state.AssignmentCount ||
		progress.StaffingDraftCount > state.StaffingDraftCount ||
		progress.PlannedTaskCount > state.PlannedTaskCount ||
		progress.PlannedFlowTemplateCount > state.PlannedFlowTemplateCount ||
		progress.FirstWaveTaskCount > state.FirstWaveTaskCount ||
		progress.FirstWavePromotedCount > state.FirstWavePromotedCount ||
		progress.FirstWaveExecutionCount > state.FirstWaveExecutionCount ||
		progress.FirstWaveJobCount > state.FirstWaveJobCount
	if !progress.ValidationFailed() &&
		projectBootstrapRestartSession(session) &&
		!madeProgress &&
		latestCompleted.StopReason != nil &&
		strings.TrimSpace(*latestCompleted.StopReason) == stopReasonValidationBlocked &&
		!blockedByRereadGuard {
		progress.ValidationStatus = projectBootstrapValidationFailed
		if strings.TrimSpace(blockedReason) != "" {
			progress.ValidationFailureReason = buildProjectBootstrapNarrativeOnlyRecoveryFailureReason(blockedReason, assistant)
		} else {
			progress.ValidationFailureReason = buildProjectBootstrapNarrativeOnlyRestartFailureReason(assistant)
		}
		progress.ValidationFailureClass = projectBootstrapFailureStalled
	}
	if !progress.ValidationFailed() && projectBootstrapRestartSession(session) && !madeProgress && projectBootstrapNarrativeOnlyReply(messages, assistant) && !blockedByRereadGuard {
		progress.ValidationStatus = projectBootstrapValidationFailed
		progress.ValidationFailureReason = buildProjectBootstrapNarrativeOnlyRestartFailureReason(assistant)
		progress.ValidationFailureClass = projectBootstrapFailureStalled
	}
	state.Status = projectBootstrapStatusActive
	state.LastTurnID = turnID.String()
	state.BootstrapTaskID = progress.BootstrapTaskID.String()
	state.BootstrapTaskOutstanding = progress.BootstrapTaskOutstanding
	applyProjectBootstrapProgressState(&state, progress)
	state.UpdatedAt = &now
	state.CompletedAt = nil
	state.FailedAt = nil
	state.FailureCategory = ""
	state.FailureClass = ""
	state.FailurePhase = ""
	state.FailureReason = ""
	state.ProviderFailureClass = ""
	state.ProviderFailureReason = ""
	if latestCompleted.RespondingID != uuid.Nil {
		state.LastResponderID = latestCompleted.RespondingID.String()
	}
	if madeProgress {
		state.LastProgressAt = &now
		state.AutoTurnCount = 0
	} else {
		state.AutoTurnCount++
	}

	if progress.Materialized() {
		state.Status = projectBootstrapStatusCompleted
		state.AutoTurnCount = 0
		state.CompletedAt = &now
		state.BootstrapTaskOutstanding = progress.BootstrapTaskOutstanding
		if err := e.finalizePendingProjectBootstrapMessages(ctx, session.ID); err != nil {
			return err
		}
		return e.updateProjectBootstrapState(ctx, session, state)
	}

	if !progress.ValidationFailed() && projectBootstrapRestartSession(session) && projectBootstrapRestartScaffoldOnly(progress) {
		progress.ValidationStatus = projectBootstrapValidationFailed
		progress.ValidationFailureClass = projectBootstrapFailureRuntime
		progress.ValidationFailureReason = buildProjectBootstrapRestartScaffoldFailureReason()
	}

	if progress.ValidationFailed() {
		if projectBootstrapRecoverableMaxToolCallFailure(progress) && projectBootstrapHasNewerLiveContinuationTurn(turns, *latestCompleted) {
			state.ValidationStatus = ""
			state.ValidationFailureClass = ""
			state.ValidationFailureReason = ""
			return e.updateProjectBootstrapState(ctx, session, state)
		}
		rt := &turnRuntime{session: session, turn: &chat.ChatTurn{ID: turnID}}
		if latestCompleted.RespondingID != uuid.Nil {
			rt.agent.ID = latestCompleted.RespondingID
		}
		recoveryState := state
		if !madeProgress && recoveryState.AutoTurnCount > 0 {
			// Consecutive recoverable validation retries should consume one
			// continuation budget increment, not both the generic no-progress
			// increment and the recovery-continuation increment.
			recoveryState.AutoTurnCount--
		}
		if handled, recoverErr := e.continueRecoverableProjectBootstrapValidation(ctx, rt, recoveryState, progress, now, false); recoverErr != nil {
			return recoverErr
		} else if handled {
			return nil
		}
		return e.failProjectBootstrapValidation(ctx, rt, progress, now)
	}

	if progress.WaitingForBootstrapGate() {
		state.AutoTurnCount = 0
	}

	if state.AutoTurnCount >= maxProjectBootstrapAutoTurns {
		record := buildProjectBootstrapAutomaticFailureRecord(
			progress,
			projectFailureCategoryBootstrap,
			projectBootstrapFailureStalled,
			buildProjectBootstrapFailureReason(state.AutoTurnCount),
			now,
		)
		state.Status = projectBootstrapStatusFailed
		state.FailedAt = &now
		state.FailureCategory = record.FailureCategory
		state.FailureClass = record.FailureClass
		state.FailurePhase = record.FailurePhase
		state.FailureReason = record.FailureReason
		if err := e.updateProjectBootstrapState(ctx, session, state); err != nil {
			return err
		}
		_, _ = e.appendSystemMessage(ctx, turnID, session.ID, buildProjectBootstrapAutomaticFailureMessage(record))
		if err := e.applyProjectAutomaticFailure(ctx, session.ScopeID, record); err != nil {
			return err
		}
		return nil
	}

	if err := e.updateProjectBootstrapState(ctx, session, state); err != nil {
		return err
	}
	if queued, err := e.hasQueuedAgentTurnForSession(ctx, session.ID, nil); err != nil {
		return err
	} else if queued {
		return nil
	}

	continuationAgentID := e.projectBootstrapContinuationAgent(ctx, session, latestCompleted.RespondingID)
	continuationMessage, err := e.appendProjectBootstrapContinuationMessage(ctx, session.ID, continuationAgentID, state.InitialMessageID, state.AutoTurnCount)
	if err != nil {
		return err
	}

	nextPayload := AgentTurnPayload{
		SessionID: session.ID,
		MessageID: continuationMessage.ID,
	}
	if continuationAgentID != uuid.Nil {
		nextAgentID := continuationAgentID
		nextPayload.AgentID = &nextAgentID
	}
	runAfter := now.Add(defaultAutoContinueDelay)
	_, err = e.enqueueAgentTurnIfActive(ctx, session, nextPayload, &runAfter)
	return err
}

func (e *TurnEngine) handleProjectBootstrapCancelledTurn(ctx context.Context, session *chat.ChatSession, turnID uuid.UUID) error {
	if e == nil || session == nil || turnID == uuid.Nil {
		return nil
	}
	if !strings.EqualFold(strings.TrimSpace(session.Status), "active") {
		return nil
	}
	if session.ScopeID == uuid.Nil || !strings.EqualFold(strings.TrimSpace(session.Mode), "async") {
		return nil
	}
	if session.CurrentTurnID != nil {
		return nil
	}
	if paused, reason, pauseErr := e.projectPausedForSession(ctx, session); pauseErr != nil {
		return pauseErr
	} else if paused {
		e.logPausedTurnSkip("skipping bootstrap cancellation recovery for paused project", session, reason, turnID)
		return nil
	}

	state := projectBootstrapStateFromMetadata(session.Metadata)
	if !strings.EqualFold(strings.TrimSpace(state.Status), projectBootstrapStatusActive) {
		return nil
	}
	if strings.EqualFold(strings.TrimSpace(state.Status), projectBootstrapStatusFailed) {
		return nil
	}

	progress, err := e.loadProjectBootstrapProgress(ctx, session.ScopeID)
	if err != nil {
		return err
	}
	normalizeProjectBootstrapValidationFailure(&progress, false)
	if progress.Materialized() {
		return nil
	}
	recoveryProgress, recoverableValidation := projectBootstrapCancelledRecoveryProgress(state, progress)
	if recoveryProgress.ValidationFailed() && !recoverableValidation {
		return nil
	}

	turns, err := e.turns.ListBySession(ctx, session.ID)
	if err != nil {
		return err
	}
	var cancelled *repo.ChatTurn
	for i := range turns {
		turn := turns[i]
		if turn.ID != turnID {
			continue
		}
		copyTurn := turn
		cancelled = &copyTurn
		break
	}
	if cancelled == nil || !strings.EqualFold(strings.TrimSpace(cancelled.Status), "cancelled") {
		return nil
	}
	for i := range turns {
		turn := turns[i]
		if turn.TurnNumber <= cancelled.TurnNumber {
			continue
		}
		return nil
	}

	messages, err := e.messages.ListBySession(ctx, session.ID)
	if err != nil {
		return err
	}
	if latestUser := latestUserMessage(messages); latestUser != nil && latestUser.SequenceNumber > latestMessageSequenceForTurn(messages, turnID) {
		metadata := messageMetadataMap(latestUser.Metadata)
		if strings.EqualFold(strings.TrimSpace(fmt.Sprintf("%v", metadata["source"])), projectBootstrapSource) {
			if e.pool == nil {
				return nil
			}
			queued, err := e.hasQueuedAgentTurnForSession(ctx, session.ID, nil)
			if err != nil {
				return err
			}
			if queued {
				return nil
			}
		}
	}

	initialMessageID := strings.TrimSpace(state.InitialMessageID)
	if initialMessageID == "" {
		if latestUser := latestUserMessage(messages); latestUser != nil {
			initialMessageID = projectBootstrapWorkflowMessageID(latestUser).String()
		}
	}
	if initialMessageID == "" {
		return nil
	}

	now := e.now().UTC()
	state.Status = projectBootstrapStatusActive
	state.LastTurnID = turnID.String()
	state.BootstrapTaskID = progress.BootstrapTaskID.String()
	state.BootstrapTaskOutstanding = progress.BootstrapTaskOutstanding
	applyProjectBootstrapProgressState(&state, progress)
	if recoverableValidation {
		state.ValidationStatus = ""
		state.ValidationFailureClass = ""
		state.ValidationFailureReason = ""
	}
	state.UpdatedAt = &now
	if cancelled.RespondingID != uuid.Nil {
		state.LastResponderID = cancelled.RespondingID.String()
	}
	if err := e.updateProjectBootstrapState(ctx, session, state); err != nil {
		return err
	}

	_, _ = e.appendSystemMessage(ctx, turnID, session.ID, "[Recovered cancelled bootstrap turn - retrying in a fresh turn.]")
	continuationAgentID := e.projectBootstrapContinuationAgent(ctx, session, cancelled.RespondingID)
	var continuationMessage *chat.ChatMessage
	if recoverableValidation {
		continuationMessage, err = e.appendProjectBootstrapRecoveryContinuationMessage(ctx, session.ID, continuationAgentID, initialMessageID, state.AutoTurnCount, recoveryProgress)
	} else {
		continuationMessage, err = e.appendProjectBootstrapContinuationMessage(ctx, session.ID, continuationAgentID, initialMessageID, state.AutoTurnCount)
	}
	if err != nil {
		return err
	}

	nextPayload := AgentTurnPayload{
		SessionID: session.ID,
		MessageID: continuationMessage.ID,
	}
	if continuationAgentID != uuid.Nil {
		nextAgentID := continuationAgentID
		nextPayload.AgentID = &nextAgentID
	}
	runAfter := now.Add(defaultAutoContinueDelay)
	_, err = e.enqueueAgentTurnIfActive(ctx, session, nextPayload, &runAfter)
	return err
}

func (e *TurnEngine) continueRecoverableProjectBootstrapValidation(
	ctx context.Context,
	rt *turnRuntime,
	state projectBootstrapState,
	progress projectBootstrapProgress,
	now time.Time,
	failCurrentTurn bool,
) (bool, error) {
	if e == nil || rt == nil || rt.session == nil || rt.turn == nil {
		return false, nil
	}
	normalizeProjectBootstrapValidationFailure(&progress, false)
	if !projectBootstrapRecoverableMaxToolCallFailure(progress) {
		return false, nil
	}

	if state.StartedAt == nil {
		state.StartedAt = &now
	}
	if projectBootstrapProgressAdvancedBeyondState(state, progress) {
		state.AutoTurnCount = 0
	}
	state.Status = projectBootstrapStatusActive
	state.BootstrapTaskID = progress.BootstrapTaskID.String()
	state.BootstrapTaskOutstanding = progress.BootstrapTaskOutstanding
	state.LastTurnID = rt.turn.ID.String()
	if rt.agent.ID != uuid.Nil {
		state.LastResponderID = rt.agent.ID.String()
	}
	state.AutoTurnCount++
	applyProjectBootstrapProgressState(&state, progress)
	state.ValidationStatus = ""
	state.ValidationFailureClass = ""
	state.ValidationFailureReason = ""
	state.UpdatedAt = &now
	state.CompletedAt = nil
	state.FailedAt = nil
	state.FailureCategory = ""
	state.FailureClass = ""
	state.FailurePhase = ""
	state.FailureReason = ""
	state.ProviderFailureClass = ""
	state.ProviderFailureReason = ""
	if state.AutoTurnCount > maxProjectBootstrapAutoTurns {
		return false, nil
	}

	if err := e.updateProjectBootstrapState(ctx, rt.session, state); err != nil {
		return true, err
	}
	if failCurrentTurn {
		if failErr := e.chat.FailTurn(ctx, rt.turn.ID, progress.ValidationFailureReason); failErr != nil && !errors.Is(failErr, chat.ErrInvalidStatusTransition) {
			return true, failErr
		}
	}

	if failCurrentTurn {
		queued, err := e.hasQueuedAgentTurnForSession(ctx, rt.session.ID, rt.currentJobID)
		if err != nil {
			return true, err
		}
		if queued {
			return true, nil
		}
	}

	continuationAgentID := e.projectBootstrapContinuationAgent(ctx, rt.session, rt.agent.ID)
	continuationMessage, err := e.appendProjectBootstrapRecoveryContinuationMessage(ctx, rt.session.ID, continuationAgentID, state.InitialMessageID, state.AutoTurnCount, progress)
	if err != nil {
		return true, err
	}

	nextPayload := AgentTurnPayload{
		SessionID: rt.session.ID,
		MessageID: continuationMessage.ID,
	}
	if continuationAgentID != uuid.Nil {
		nextAgentID := continuationAgentID
		nextPayload.AgentID = &nextAgentID
	}
	runAfter := now.Add(defaultAutoContinueDelay)
	if _, err := e.enqueueAgentTurnIfActive(ctx, rt.session, nextPayload, &runAfter); err != nil {
		return true, err
	}
	return true, nil
}

func (e *TurnEngine) continueRecoverableProjectBootstrapValidationForSession(
	ctx context.Context,
	session *chat.ChatSession,
	state projectBootstrapState,
	progress projectBootstrapProgress,
	now time.Time,
) (bool, error) {
	if e == nil || session == nil {
		return false, nil
	}
	normalizeProjectBootstrapValidationFailure(&progress, false)
	if !projectBootstrapRecoverableMaxToolCallFailure(progress) {
		return false, nil
	}
	if session.CurrentTurnID != nil {
		return false, nil
	}

	if state.StartedAt == nil {
		state.StartedAt = &now
	}
	if projectBootstrapProgressAdvancedBeyondState(state, progress) {
		state.AutoTurnCount = 0
	}
	state.Status = projectBootstrapStatusActive
	state.BootstrapTaskID = progress.BootstrapTaskID.String()
	state.BootstrapTaskOutstanding = progress.BootstrapTaskOutstanding
	state.AutoTurnCount++
	applyProjectBootstrapProgressState(&state, progress)
	state.ValidationStatus = ""
	state.ValidationFailureClass = ""
	state.ValidationFailureReason = ""
	state.UpdatedAt = &now
	state.CompletedAt = nil
	state.FailedAt = nil
	state.FailureCategory = ""
	state.FailureClass = ""
	state.FailurePhase = ""
	state.FailureReason = ""
	state.ProviderFailureClass = ""
	state.ProviderFailureReason = ""
	if state.AutoTurnCount > maxProjectBootstrapAutoTurns {
		return false, nil
	}

	if err := e.updateProjectBootstrapState(ctx, session, state); err != nil {
		return true, err
	}
	queued, err := e.hasQueuedAgentTurnForSession(ctx, session.ID, nil)
	if err != nil {
		return true, err
	}
	if queued {
		return true, nil
	}

	initialMessageID := strings.TrimSpace(state.InitialMessageID)
	if initialMessageID == "" && e.messages != nil {
		messages, err := e.messages.ListBySession(ctx, session.ID)
		if err != nil {
			return true, err
		}
		if latestUser := latestUserMessage(messages); latestUser != nil {
			initialMessageID = projectBootstrapWorkflowMessageID(latestUser).String()
		}
	}
	if initialMessageID == "" {
		return false, nil
	}

	latestResponderID, _ := uuid.Parse(strings.TrimSpace(state.LastResponderID))
	continuationAgentID := e.projectBootstrapContinuationAgent(ctx, session, latestResponderID)
	if continuationAgentID == uuid.Nil {
		return false, nil
	}
	continuationMessage, err := e.appendProjectBootstrapRecoveryContinuationMessage(ctx, session.ID, continuationAgentID, initialMessageID, state.AutoTurnCount, progress)
	if err != nil {
		return true, err
	}

	nextPayload := AgentTurnPayload{
		SessionID: session.ID,
		MessageID: continuationMessage.ID,
	}
	if continuationAgentID != uuid.Nil {
		nextAgentID := continuationAgentID
		nextPayload.AgentID = &nextAgentID
	}
	runAfter := now.Add(defaultAutoContinueDelay)
	if _, err := e.enqueueAgentTurnIfActive(ctx, session, nextPayload, &runAfter); err != nil {
		return true, err
	}
	return true, nil
}

func (e *TurnEngine) failProjectBootstrapValidation(ctx context.Context, rt *turnRuntime, progress projectBootstrapProgress, now time.Time) error {
	if rt == nil || rt.session == nil || rt.turn == nil {
		return nil
	}
	normalizeProjectBootstrapValidationFailure(&progress, false)

	state := projectBootstrapStateFromMetadata(rt.session.Metadata)
	if state.StartedAt == nil {
		state.StartedAt = &now
	}
	state.Status = projectBootstrapStatusFailed
	state.BootstrapTaskID = progress.BootstrapTaskID.String()
	state.BootstrapTaskOutstanding = progress.BootstrapTaskOutstanding
	state.LastTurnID = rt.turn.ID.String()
	if rt.agent.ID != uuid.Nil {
		state.LastResponderID = rt.agent.ID.String()
	}
	applyProjectBootstrapProgressState(&state, progress)

	record := buildProjectBootstrapAutomaticFailureRecord(
		progress,
		projectFailureCategoryBootstrap,
		progress.ValidationFailureClass,
		progress.ValidationFailureReason,
		now,
	)
	state.FailedAt = &now
	state.UpdatedAt = &now
	state.CompletedAt = nil
	state.FailureCategory = record.FailureCategory
	state.FailureClass = record.FailureClass
	state.FailurePhase = record.FailurePhase
	state.FailureReason = record.FailureReason
	if err := e.updateProjectBootstrapState(ctx, rt.session, state); err != nil {
		return err
	}
	if failErr := e.chat.FailTurn(ctx, rt.turn.ID, state.FailureReason); failErr != nil && !errors.Is(failErr, chat.ErrInvalidStatusTransition) {
		return failErr
	}
	if _, err := e.appendSystemMessage(ctx, rt.turn.ID, rt.session.ID, buildProjectBootstrapAutomaticFailureMessage(record)); err != nil {
		return err
	}
	return e.applyProjectAutomaticFailure(ctx, rt.session.ScopeID, record)
}

func (e *TurnEngine) ensureProjectBootstrapFirstWaveExecution(ctx context.Context, progress projectBootstrapProgress) (projectBootstrapProgress, error) {
	if e == nil || e.taskTransitions == nil || progress.ValidationStatus != projectBootstrapValidationPassed || progress.FirstWaveMaterialized() {
		return progress, nil
	}
	if progress.FirstWaveTaskCount == 0 || len(progress.FirstWaveTasks) == 0 {
		return progress, nil
	}

	projectID := progress.FirstWaveTasks[0].ProjectID
	if progress.BootstrapTaskOutstanding && progress.BootstrapTaskID != uuid.Nil {
		if !progress.BootstrapGateReady() {
			return progress, nil
		}
		if err := e.completeProjectBootstrapGateTask(ctx, progress.BootstrapTaskID); err != nil {
			return progress, err
		}
		updated, err := e.loadProjectBootstrapProgress(ctx, projectID)
		if err != nil {
			return progress, err
		}
		progress = updated
	}

	queuedAny := false
	for _, task := range progress.FirstWaveTasks {
		if !strings.EqualFold(strings.TrimSpace(task.WorkStatus), "draft") {
			continue
		}
		if _, err := e.taskTransitions.TransitionStatus(ctx, task.ID, "queued", tasksvc.Actor{Type: "system", AllowGateBypass: true}); err != nil {
			if isAlreadyQueuedTaskTransition(err) {
				queuedAny = true
				continue
			}
			if errors.Is(err, taskdecomp.ErrBoundedTaskTooLarge) {
				progress.ValidationStatus = projectBootstrapValidationFailed
				progress.ValidationFailureClass = projectBootstrapFailureFirstWaveExecution
				progress.ValidationFailureReason = err.Error()
				return progress, nil
			}
			return progress, err
		}
		queuedAny = true
	}
	if !queuedAny && progress.FirstWavePromotedCount == 0 && progress.FirstWaveExecutionCount == 0 && progress.FirstWaveJobCount == 0 {
		progress.ValidationStatus = projectBootstrapValidationFailed
		progress.ValidationFailureClass = projectBootstrapFailureFirstWaveExecution
		progress.ValidationFailureReason = buildProjectBootstrapFirstWaveExecutionFailureReason(progress)
		return progress, nil
	}

	updated, err := e.loadProjectBootstrapProgress(ctx, projectID)
	if err != nil {
		return progress, err
	}
	if err := e.ensureProjectBootstrapFirstWaveExecutionsStarted(ctx, updated.FirstWaveTasks); err != nil {
		return progress, err
	}
	if e.flowAdvancer != nil {
		updated, err = e.loadProjectBootstrapProgress(ctx, projectID)
		if err != nil {
			return progress, err
		}
	}
	if updated.FirstWavePromotedCount == 0 && updated.FirstWaveExecutionCount == 0 && updated.FirstWaveJobCount == 0 {
		updated.ValidationStatus = projectBootstrapValidationFailed
		updated.ValidationFailureClass = projectBootstrapFailureFirstWaveExecution
		updated.ValidationFailureReason = buildProjectBootstrapFirstWaveExecutionFailureReason(updated)
		return updated, nil
	}
	if !updated.BootstrapGateReady() {
		return updated, nil
	}

	deadline := e.now().Add(defaultProjectBootstrapPromotionTimeout)
	for {
		updated, err = e.loadProjectBootstrapProgress(ctx, projectID)
		if err != nil {
			return progress, err
		}
		if updated.FirstWaveMaterialized() || updated.ValidationFailed() {
			return updated, nil
		}
		if e.now().After(deadline) {
			updated.ValidationStatus = projectBootstrapValidationFailed
			updated.ValidationFailureClass = projectBootstrapFailureFirstWaveExecution
			updated.ValidationFailureReason = buildProjectBootstrapFirstWaveExecutionFailureReason(updated)
			return updated, nil
		}
		if ctx.Err() != nil {
			return progress, ctx.Err()
		}
		if err := e.sleep(ctx, defaultProjectBootstrapPromotionPollDelay); err != nil {
			return progress, err
		}
	}
}

func (e *TurnEngine) ensureProjectBootstrapFirstWaveExecutionsStarted(ctx context.Context, tasks []repo.ProjectTask) error {
	if e == nil || e.flowAdvancer == nil || len(tasks) == 0 {
		return nil
	}
	for _, task := range tasks {
		if task.ID == uuid.Nil || !bootstrapTaskNeedsActiveExecution(task.WorkStatus) {
			continue
		}
		if _, err := e.flowAdvancer.EnsureActiveExecution(ctx, task.ID); err != nil {
			return err
		}
	}
	return nil
}

func (e *TurnEngine) handleCompletedProjectExecutionContinuationTurn(
	ctx context.Context,
	session *chat.ChatSession,
	completedTurn *repo.ChatTurn,
	latestUser *repo.ChatMessage,
	assistant *repo.ChatMessage,
	messages []repo.ChatMessage,
) (bool, error) {
	if e == nil || session == nil || completedTurn == nil || latestUser == nil || assistant == nil || e.tasks == nil || e.taskTransitions == nil {
		return false, nil
	}
	if !projectContinuationMessageRootsHistory(*latestUser) {
		return false, nil
	}
	assistantContent := strings.TrimSpace(assistant.Content)
	genericAssistant := assistantContent == "" || looksLikeGenericTaskRecoveryReply(assistantContent)
	if missingPath, found := projectContinuationMissingDependencyStopPath(messages, completedTurn.ID); found {
		return e.retryProjectExecutionContinuationForMissingDependency(ctx, session, completedTurn, latestUser, missingPath)
	}
	if projectContinuationTurnEndedWithBoundedSizeStop(messages, completedTurn.ID) {
		if retried, retryErr := e.retryProjectExecutionContinuationForBoundedSizeStop(ctx, session, completedTurn, latestUser, messages); retryErr != nil {
			return false, retryErr
		} else if retried {
			return true, nil
		}
	}
	if turnHasSuccessfulMutatingToolResult(messages, completedTurn.ID) {
		return false, nil
	}
	preferredResumeTaskIDs := projectContinuationPromptNamedTaskIDs(strings.TrimSpace(latestUser.Content))
	if handled, shouldStop, err := e.resumeBlockedProjectContinuationReviewLane(ctx, completedTurn.ID, session.ID, session.ScopeID, preferredResumeTaskIDs); err != nil {
		return false, err
	} else if handled && shouldStop {
		return true, nil
	}
	nextTask, ok, err := e.nextRunnableDraftProjectTask(ctx, session.ScopeID)
	if err != nil {
		return false, err
	}
	if !ok {
		if projectContinuationTurnEndedWithTaskLaneBoundaryStop(messages, completedTurn.ID) {
			return true, nil
		}
		if projectContinuationTurnEndedWithRediscoveryOnlyStop(messages, completedTurn.ID) {
			if retried, retryErr := e.retryProjectExecutionContinuationForReplacementChildWork(ctx, session, completedTurn, latestUser); retryErr != nil {
				return false, retryErr
			} else if retried {
				return true, nil
			}
			if retried, retryErr := e.retryProjectExecutionContinuationForRediscoveryStop(ctx, session, completedTurn, latestUser); retryErr != nil {
				return false, retryErr
			} else if retried {
				return true, nil
			}
		}
		if genericAssistant {
			return e.retryGenericProjectExecutionContinuation(ctx, session, completedTurn, latestUser)
		}
		return false, nil
	}
	updated, err := e.taskTransitions.TransitionStatus(ctx, nextTask.ID, "queued", tasksvc.Actor{Type: "system"})
	if err != nil {
		if errors.Is(err, taskdecomp.ErrBoundedTaskTooLarge) {
			_, _ = e.appendSystemMessage(
				ctx,
				completedTurn.ID,
				session.ID,
				fmt.Sprintf(
					"[Project continuation found remaining draft %s but could not auto-queue it because it violates the bounded size policy: %s]",
					projectBootstrapTaskLabel(nextTask),
					strings.TrimSpace(err.Error()),
				),
			)
			return true, nil
		}
		return false, err
	}
	queuedTask := repo.ProjectTask(*updated)
	_, _ = e.appendSystemMessage(
		ctx,
		completedTurn.ID,
		session.ID,
		fmt.Sprintf("[Project continuation auto-queued %s after a non-mutating continuation left runnable draft work untouched.]", projectBootstrapTaskLabel(queuedTask)),
	)
	return true, nil
}

func (e *TurnEngine) resumeBlockedProjectContinuationReviewLane(ctx context.Context, turnID, sessionID, projectID uuid.UUID, preferredTaskIDs map[uuid.UUID]struct{}) (bool, bool, error) {
	if e == nil || e.tasks == nil || e.taskTransitions == nil || turnID == uuid.Nil || sessionID == uuid.Nil || projectID == uuid.Nil {
		return false, false, nil
	}
	blockedReviewTask, ok, err := e.nextResumableBlockedProjectTask(ctx, projectID, preferredTaskIDs)
	if err != nil {
		return false, false, err
	}
	if !ok {
		return false, false, nil
	}
	resumed, resumeErr := e.taskTransitions.ResumeValidationBlockedTask(ctx, blockedReviewTask.ID, tasksvc.Actor{Type: "system"})
	if resumeErr != nil {
		var stateErr tasksvc.TaskResumeBlockedStateError
		if !errors.As(resumeErr, &stateErr) {
			return false, false, resumeErr
		}
		blockerClass := strings.TrimSpace(stateErr.BlockerClass)
		if blockerClass == "" {
			blockerClass = tasksvc.RecoveryBlockerClassBlockedWithoutResumableState
		}
		blockerReason := strings.TrimSpace(stateErr.BlockerReason)
		if blockerReason != "" {
			_, _ = e.appendSystemMessage(
				ctx,
				turnID,
				sessionID,
				fmt.Sprintf("[Project continuation found blocked review lane %s but runtime resume is still blocked by %s: %s. Leave that lane blocked and continue with the next bounded task instead.]", projectBootstrapTaskLabel(blockedReviewTask), blockerClass, blockerReason),
			)
		} else {
			_, _ = e.appendSystemMessage(
				ctx,
				turnID,
				sessionID,
				fmt.Sprintf("[Project continuation found blocked review lane %s but runtime resume is still blocked by %s. Leave that lane blocked and continue with the next bounded task instead.]", projectBootstrapTaskLabel(blockedReviewTask), blockerClass),
			)
		}
		return true, false, nil
	}
	resumedLabel := projectBootstrapTaskLabel(blockedReviewTask)
	if resumed != nil && resumed.ID != uuid.Nil {
		if resumed.TaskNumber > 0 || strings.TrimSpace(resumed.Title) != "" {
			resumedLabel = projectBootstrapTaskLabel(repo.ProjectTask(*resumed))
		}
	}
	_, _ = e.appendSystemMessage(
		ctx,
		turnID,
		sessionID,
		fmt.Sprintf("[Project continuation resumed blocked review lane %s so it can complete flow.review_decision instead of creating replacement work.]", resumedLabel),
	)
	return true, true, nil
}

func (e *TurnEngine) retryGenericProjectExecutionContinuation(
	ctx context.Context,
	session *chat.ChatSession,
	latestCompleted *repo.ChatTurn,
	latestUser *repo.ChatMessage,
) (bool, error) {
	if e == nil || session == nil || latestCompleted == nil || latestUser == nil {
		return false, nil
	}
	if latestCompleted.RetryCount >= maxGenericRecoveryReplyRetries {
		return false, nil
	}
	completedTaskID, _ := parseUUIDAny(messageMetadataMap(latestUser.Metadata)["completed_task_id"])
	var completedTask repo.ProjectTask
	if completedTaskID != uuid.Nil && e.tasks != nil {
		if taskRecord, err := e.tasks.GetByID(ctx, completedTaskID); err == nil {
			completedTask = taskRecord
		}
	}
	remainingDraftTasks, err := e.countProjectDraftTasks(ctx, session.ScopeID)
	if err != nil {
		return false, err
	}
	snapshot, err := e.projectExecutionContinuationSnapshot(ctx, session.ScopeID)
	if err != nil {
		return false, err
	}
	agentID := latestCompleted.RespondingID
	retryPrompt := buildProjectExecutionContinuationPrompt(completedTask, remainingDraftTasks, snapshot) +
		" Your last continuation turn returned a generic non-action reply instead of advancing the project." +
		" Do not ask which function to call, do not offer to format JSON or tool calls, and do not ask the user for more parameters." +
		" Your next assistant action must either emit the concrete tool calls that advance the project or report one concrete blocker sentence."
	retryMessage, err := e.appendProjectExecutionContinuationMessage(ctx, session.ID, agentID, completedTaskID, retryPrompt)
	if err != nil {
		return false, err
	}
	if retryMessage == nil {
		return true, nil
	}
	nextPayload := AgentTurnPayload{
		SessionID:  session.ID,
		MessageID:  retryMessage.ID,
		RetryCount: latestCompleted.RetryCount + 1,
	}
	if agentID != uuid.Nil {
		nextPayload.AgentID = &agentID
	}
	runAfter := e.now().Add(defaultAutoContinueDelay).UTC()
	enqueued, err := e.enqueueAgentTurnIfActive(ctx, session, nextPayload, &runAfter)
	if err != nil {
		return false, err
	}
	return enqueued, nil
}

func (e *TurnEngine) retryProjectExecutionContinuationForMissingDependency(
	ctx context.Context,
	session *chat.ChatSession,
	latestCompleted *repo.ChatTurn,
	latestUser *repo.ChatMessage,
	missingPath string,
) (bool, error) {
	if e == nil || session == nil || latestCompleted == nil || latestUser == nil {
		return false, nil
	}
	if latestCompleted.RetryCount >= maxGenericRecoveryReplyRetries {
		return false, nil
	}
	missingPath = strings.TrimSpace(missingPath)
	if missingPath == "" {
		return false, nil
	}
	completedTaskID, _ := parseUUIDAny(messageMetadataMap(latestUser.Metadata)["completed_task_id"])
	var completedTask repo.ProjectTask
	if completedTaskID != uuid.Nil && e.tasks != nil {
		if taskRecord, err := e.tasks.GetByID(ctx, completedTaskID); err == nil {
			completedTask = taskRecord
		}
	}
	projectTasks, err := e.tasks.ListByProject(ctx, session.ScopeID)
	if err != nil {
		return false, err
	}
	taskHintsByTask, err := e.projectContinuationTaskHintsByTask(ctx, projectTasks)
	if err != nil {
		return false, err
	}
	if activeProducerRefs := projectContinuationProducerTaskRefsForPath(projectTasks, taskHintsByTask, missingPath); len(activeProducerRefs) > 0 {
		_, _ = e.appendSystemMessage(
			ctx,
			latestCompleted.ID,
			session.ID,
			fmt.Sprintf(
				"[Project continuation found that prerequisite artifact `%s` already has active replacement work in the tree: %s. Let those active task lanes continue instead of reopening duplicate PM follow-up work.]",
				missingPath,
				strings.Join(activeProducerRefs, "; "),
			),
		)
		return true, nil
	}
	if focusTask, focusActivity, focusHints, ok := projectContinuationBoundedSizeMissingDeliverableFocusTask(projectTasks, taskHintsByTask, strings.TrimSpace(latestUser.Content), missingPath); ok {
		remainingDraftTasks, err := e.countProjectDraftTasks(ctx, session.ScopeID)
		if err != nil {
			return false, err
		}
		snapshot, err := e.projectExecutionContinuationSnapshotForSummary(ctx, session.ScopeID, strings.TrimSpace(latestUser.Content))
		if err != nil {
			return false, err
		}
		agentID := latestCompleted.RespondingID
		retryPrompt := buildProjectExecutionContinuationBoundedSizeMissingDeliverableRetryPrompt(
			completedTask,
			remainingDraftTasks,
			snapshot,
			focusTask,
			focusActivity,
			focusHints,
			missingPath,
		)
		retryMessage, err := e.appendProjectExecutionContinuationMessage(ctx, session.ID, agentID, completedTaskID, retryPrompt)
		if err != nil {
			return false, err
		}
		if retryMessage == nil {
			return true, nil
		}
		nextPayload := AgentTurnPayload{
			SessionID:  session.ID,
			MessageID:  retryMessage.ID,
			RetryCount: latestCompleted.RetryCount + 1,
		}
		if agentID != uuid.Nil {
			nextPayload.AgentID = &agentID
		}
		runAfter := e.now().Add(defaultAutoContinueDelay).UTC()
		enqueued, err := e.enqueueAgentTurnIfActive(ctx, session, nextPayload, &runAfter)
		if err != nil {
			return false, err
		}
		return enqueued, nil
	}
	if nextTask, ok, err := e.nextRunnableDraftProjectTaskForPriorityPaths(ctx, session.ScopeID, singleProjectContinuationPriorityPath(missingPath)); err != nil {
		return false, err
	} else if ok {
		updated, transitionErr := e.taskTransitions.TransitionStatus(ctx, nextTask.ID, "queued", tasksvc.Actor{Type: "system"})
		if transitionErr != nil {
			if errors.Is(transitionErr, taskdecomp.ErrBoundedTaskTooLarge) {
				_, _ = e.appendSystemMessage(
					ctx,
					latestCompleted.ID,
					session.ID,
					fmt.Sprintf(
						"[Project continuation found matching draft %s for prerequisite artifact `%s`, but could not auto-queue it because it violates the bounded size policy: %s]",
						projectBootstrapTaskLabel(nextTask),
						missingPath,
						strings.TrimSpace(transitionErr.Error()),
					),
				)
				return true, nil
			}
			return false, transitionErr
		}
		queuedTask := repo.ProjectTask(*updated)
		_, _ = e.appendSystemMessage(
			ctx,
			latestCompleted.ID,
			session.ID,
			fmt.Sprintf(
				"[Project continuation auto-queued %s because it is the smallest runnable draft that restores prerequisite artifact `%s`.]",
				projectBootstrapTaskLabel(queuedTask),
				missingPath,
			),
		)
		return true, nil
	}
	remainingDraftTasks, err := e.countProjectDraftTasks(ctx, session.ScopeID)
	if err != nil {
		return false, err
	}
	snapshot, err := e.projectExecutionContinuationSnapshotForSummary(ctx, session.ScopeID, missingPath)
	if err != nil {
		return false, err
	}
	agentID := latestCompleted.RespondingID
	retryPrompt := buildProjectExecutionContinuationMissingDependencyRetryPrompt(completedTask, remainingDraftTasks, snapshot, missingPath)
	retryMessage, err := e.appendProjectExecutionContinuationMessage(ctx, session.ID, agentID, completedTaskID, retryPrompt)
	if err != nil {
		return false, err
	}
	if retryMessage == nil {
		return true, nil
	}
	nextPayload := AgentTurnPayload{
		SessionID:  session.ID,
		MessageID:  retryMessage.ID,
		RetryCount: latestCompleted.RetryCount + 1,
	}
	if agentID != uuid.Nil {
		nextPayload.AgentID = &agentID
	}
	runAfter := e.now().Add(defaultAutoContinueDelay).UTC()
	enqueued, err := e.enqueueAgentTurnIfActive(ctx, session, nextPayload, &runAfter)
	if err != nil {
		return false, err
	}
	return enqueued, nil
}

