func shouldStopAfterBlockedProjectKickoffSessionCreate(rt *turnRuntime, results []ToolResult) bool {
	if rt == nil || rt.projectIdentity == nil || rt.session == nil {
		return false
	}
	if !strings.EqualFold(strings.TrimSpace(rt.session.ScopeType), "organization") {
		return false
	}
	for _, result := range results {
		switch strings.ToLower(strings.TrimSpace(result.Name)) {
		case "session.create":
			if !strings.Contains(strings.ToLower(strings.TrimSpace(result.Error)), "handoff-only") {
				continue
			}
			return true
		case "project.create":
			if !strings.Contains(strings.ToLower(strings.TrimSpace(result.Error)), "project already created in this flow") {
				continue
			}
			return true
		}
	}
	return false
}

func shouldStopAfterBlockedProjectExecutionBlockedMutation(rt *turnRuntime, results []ToolResult) bool {
	if rt == nil || rt.session == nil {
		return false
	}
	if !strings.EqualFold(strings.TrimSpace(rt.session.ScopeType), "project") || !strings.EqualFold(strings.TrimSpace(rt.session.Mode), "async") {
		return false
	}
	for _, result := range results {
		name := strings.ToLower(strings.TrimSpace(result.Name))
		errText := strings.ToLower(strings.TrimSpace(toolResultErrorCode(result)))
		if containsAny(errText,
			"task_lane_owned_by_project_task_session",
			"task_execution_required",
			"flow_owned_status_blocked",
			"flow_owned_done_blocked",
			"flow_owned_review_status_blocked",
			"review_action_required",
			"deliverable_path_required",
			"parent task requires child verification and passed integration before completion",
			"project continuation already has focused draft task",
			"task must remain orchestration-only while executable child tasks exist",
		) {
			return true
		}
		switch name {
		case "project.create":
			if rt.projectIdentity == nil {
				continue
			}
			if strings.Contains(errText, "project already created in this flow") {
				return true
			}
		case "subtask.create":
			if strings.Contains(errText, "flow_node_execution_id_required") {
				return true
			}
		case "task.create":
			if strings.Contains(errText, "non-bootstrap tasks with blocks_scope=all must include an assigned agent") {
				return true
			}
			if strings.Contains(errText, "project_session_meta_task_disallowed") ||
				strings.Contains(errText, "project session already has remaining draft tasks to advance") {
				return true
			}
			if strings.Contains(errText, "bounded size policy") || strings.Contains(errText, "bounded task-size policy") {
				return true
			}
		case "task.update":
			if strings.Contains(errText, "bounded size policy") || strings.Contains(errText, "bounded task-size policy") {
				return true
			}
		}
	}
	return false
}

func shouldStopAfterSuccessfulProjectExecutionHandoffMutation(rt *turnRuntime, calls []ToolCall, results []ToolResult) bool {
	if !projectContinuationReplacementChildHandoffActive(rt) {
		return false
	}
	for idx, call := range calls {
		if idx >= len(results) {
			break
		}
		if projectExecutionHandoffMutationSucceeded(call, results[idx]) {
			return true
		}
	}
	return false
}

func projectContinuationReplacementChildHandoffActive(rt *turnRuntime) bool {
	if rt == nil || rt.session == nil {
		return false
	}
	if !strings.EqualFold(strings.TrimSpace(rt.session.ScopeType), "project") ||
		!strings.EqualFold(strings.TrimSpace(rt.session.Mode), "async") {
		return false
	}
	switch strings.TrimSpace(rt.initialMessageSource) {
	case projectExecutionContinuationSource, "project_continuation_resume":
	default:
		return false
	}
	initial := strings.TrimSpace(rt.initialMessageText)
	return strings.Contains(initial, "Current focus parent:") &&
		strings.Contains(initial, "fresh replacement child task beneath")
}

func projectExecutionHandoffMutationSucceeded(call ToolCall, result ToolResult) bool {
	if strings.TrimSpace(toolResultErrorCode(result)) != "" {
		return false
	}
	switch strings.ToLower(strings.TrimSpace(call.Name)) {
	case "task.update":
		switch projectExecutionResultWorkStatus(call.Arguments, result) {
		case "queued", "in_progress", "review":
			return true
		}
	case "task.create":
		switch projectExecutionResultWorkStatus(call.Arguments, result) {
		case "queued", "in_progress", "review":
			return true
		}
	}
	return false
}

func projectExecutionResultWorkStatus(arguments map[string]any, result ToolResult) string {
	if status := strings.ToLower(strings.TrimSpace(stringValue(arguments["work_status"]))); status != "" {
		return status
	}
	if status := strings.ToLower(strings.TrimSpace(stringValue(result.Output["work_status"]))); status != "" {
		return status
	}
	taskOutput, ok := result.Output["task"].(map[string]any)
	if !ok {
		return ""
	}
	return strings.ToLower(strings.TrimSpace(stringValue(taskOutput["work_status"])))
}

func projectExecutionBlockedMutationStopMessage(results []ToolResult) string {
	for _, result := range results {
		errText := strings.ToLower(strings.TrimSpace(toolResultErrorCode(result)))
		if strings.Contains(errText, "completed closeout child proof") {
			return "[Project continuation focus parent already has completed closeout child proof. Advance or close the parent directly instead of creating another replacement child for the same batch.]"
		}
		if strings.Contains(errText, "bounded size policy") || strings.Contains(errText, "bounded task-size policy") {
			return "[Project continuation found that the remaining draft work still violates the bounded size policy. Split it into smaller reviewable child tasks instead of trying to queue the broad parent again.]"
		}
		if strings.Contains(errText, "project continuation already has focused draft task") {
			return "[Project continuation already has a narrower focused draft task. Create or advance the smallest fresh child work beneath that focus task instead of re-queueing it or promoting its ancestors from the project lane.]"
		}
		if strings.Contains(errText, "parent task requires child verification and passed integration before completion") {
			return "[Project continuation found that the closeout-ready parent still needs parent_orchestration evidence before it can finish. Record parent_orchestration.child_verifications for the completed child tasks, set parent_orchestration.integration_check.status=passed, and set parent_orchestration.outcome_assessment.satisfied=true on the parent task itself. Do not cancel blocked stale child lanes from the project session first.]"
		}
		if strings.Contains(errText, "task_execution_required") {
			detail := strings.TrimSpace(anyString(result.Output["message"]))
			if detail == "" {
				return "[Project continuation found that executable task work already owns the deliverable write. Queue or advance the specific task instead of writing the file from the project session.]"
			}
			return fmt.Sprintf("[Project continuation write blocked: %s]", detail)
		}
		if containsAny(errText,
			"task_lane_owned_by_project_task_session",
			"flow_owned_status_blocked",
			"flow_owned_done_blocked",
			"flow_owned_review_status_blocked",
			"review_action_required",
		) {
			detail := strings.TrimSpace(anyString(result.Output["message"]))
			if detail != "" {
				return fmt.Sprintf("%s %s Leave that task lane alone from the project session. Do not retry task.update on it from the PM lane; let the bound task lane continue or let its own review lane issue flow.review_decision if that review lane becomes active.]", projectContinuationTaskLaneBoundaryGuardPrefix, detail)
			}
			return projectContinuationTaskLaneBoundaryGuardPrefix + " Leave that task lane alone from the project session. Do not retry task.update on it from the PM lane; let the bound task lane continue or let its own review lane issue flow.review_decision if that review lane becomes active.]"
		}
	}
	return ""
}

func projectContinuationDependencyPathsFromPrompt(content string) map[string]struct{} {
	matches := projectContinuationPromptDependencyPathPattern.FindAllStringSubmatch(content, -1)
	if len(matches) == 0 {
		return nil
	}
	paths := make(map[string]struct{}, len(matches))
	for _, match := range matches {
		if len(match) < 2 {
			continue
		}
		path := normalizeWorkspaceRelativePath(match[1])
		if path == "" {
			continue
		}
		paths[path] = struct{}{}
	}
	if len(paths) == 0 {
		return nil
	}
	return paths
}

func missingProjectContinuationDependencyArtifactPath(rt *turnRuntime, calls []ToolCall, results []ToolResult) (string, bool) {
	if rt == nil || rt.session == nil {
		return "", false
	}
	if !strings.EqualFold(strings.TrimSpace(rt.session.ScopeType), "project") || !strings.EqualFold(strings.TrimSpace(rt.session.Mode), "async") {
		return "", false
	}
	dependencyPaths := projectContinuationDependencyPathsFromPrompt(rt.initialMessageText)
	if len(dependencyPaths) == 0 {
		return "", false
	}
	for idx, call := range calls {
		if idx >= len(results) {
			break
		}
		if !strings.EqualFold(strings.TrimSpace(call.Name), "file.read") {
			continue
		}
		if !strings.Contains(strings.ToLower(strings.TrimSpace(toolResultErrorCode(results[idx]))), "not_found") {
			continue
		}
		callPath := normalizeWorkspaceRelativePath(stringValue(call.Arguments["path"]))
		if _, ok := dependencyPaths[callPath]; ok {
			return callPath, true
		}
	}
	return "", false
}

func projectContinuationMissingDependencyStopMessage(path string) string {
	path = normalizeWorkspaceRelativePath(path)
	if path == "" {
		return "[Project continuation found that a named prerequisite artifact is still missing. Queue or advance the smallest replacement task that produces it instead of browsing external sources or writing the file from the project session.]"
	}
	return fmt.Sprintf("[Project continuation found that prerequisite artifact `%s` is still missing. Queue or advance the smallest replacement task that produces it instead of browsing external sources or writing the file from the project session.]", path)
}

