func shouldStopAfterBlockedProjectContinuationRediscovery(rt *turnRuntime, results []ToolResult) bool {
	if rt == nil || rt.session == nil {
		return false
	}
	if !strings.EqualFold(strings.TrimSpace(rt.session.ScopeType), "project") ||
		!strings.EqualFold(strings.TrimSpace(rt.session.Mode), "async") {
		return false
	}
	if len(results) < 2 {
		return false
	}
	for _, result := range results {
		errText := strings.ToLower(strings.TrimSpace(result.Error))
		if strings.HasPrefix(errText, "project continuation already ") {
			continue
		}
		if strings.HasPrefix(errText, "project continuation called flow.get_execution ") {
			continue
		}
		return false
	}
	return true
}

func (e *TurnEngine) handleBlockedProjectContinuationReviewResume(ctx context.Context, rt *turnRuntime, results []ToolResult) (bool, error) {
	if e == nil || rt == nil || rt.session == nil || rt.turn == nil {
		return false, nil
	}
	if !shouldStopAfterBlockedProjectContinuationRediscovery(rt, results) {
		return false, nil
	}
	preferredTaskIDs := projectContinuationPromptNamedTaskIDs(strings.TrimSpace(rt.initialMessageText))
	if len(preferredTaskIDs) == 0 {
		return false, nil
	}
	handled, _, err := e.resumeBlockedProjectContinuationReviewLane(ctx, rt.turn.ID, rt.session.ID, rt.session.ScopeID, preferredTaskIDs)
	if err != nil {
		return false, err
	}
	if handled {
		rt.stopReason = stopReasonValidationBlocked
		return true, nil
	}
	return false, nil
}

func maybeInjectTaskExecutionSubtaskCreateExecutionID(rt *turnRuntime, toolName string, arguments map[string]any) {
	if rt == nil || rt.session == nil || arguments == nil {
		return
	}
	if !strings.EqualFold(strings.TrimSpace(rt.session.ScopeType), "project_task") ||
		!strings.EqualFold(strings.TrimSpace(rt.session.Mode), "async") ||
		!strings.EqualFold(strings.TrimSpace(toolName), "subtask.create") {
		return
	}
	if strings.TrimSpace(stringValue(arguments["flow_node_execution_id"])) != "" {
		return
	}
	executionID := flowNodeExecutionIDFromSessionMetadata(rt.session)
	if executionID == nil || *executionID == uuid.Nil {
		return
	}
	arguments["flow_node_execution_id"] = executionID.String()
}

func (e *TurnEngine) maybeInjectOrchestrationParentReviewTaskListParentID(ctx context.Context, rt *turnRuntime, toolName string, rawArguments, arguments map[string]any) {
	if e == nil || e.tasks == nil || rt == nil || rt.session == nil || arguments == nil {
		return
	}
	if !strings.EqualFold(strings.TrimSpace(rt.session.ScopeType), "project_task") ||
		!strings.EqualFold(strings.TrimSpace(rt.session.Mode), "async") ||
		!strings.EqualFold(strings.TrimSpace(toolName), "task.list") {
		return
	}
	if strings.TrimSpace(stringValue(arguments["parent_task_id"])) != "" {
		return
	}
	taskID := resolveTaskID(rt.session)
	if taskID == nil || *taskID == uuid.Nil {
		return
	}
	taskRecord, err := e.tasks.GetByID(ctx, *taskID)
	if err != nil {
		return
	}
	if !strings.EqualFold(strings.TrimSpace(taskRecord.WorkStatus), "review") || !taskLooksLikeOrchestrationOnlyParent(taskRecord) {
		return
	}
	if rawProjectID, ok := parseUUIDAny(rawArguments["project_id"]); ok && rawProjectID != uuid.Nil && rawProjectID != taskRecord.ID {
		return
	}
	if rawTaskID, ok := parseUUIDAny(rawArguments["task_id"]); ok && rawTaskID != uuid.Nil {
		return
	}
	arguments["parent_task_id"] = taskRecord.ID.String()
}

