func shouldBlockTaskReviewDirtyWorkspaceRetryTool(rt *turnRuntime, toolName string, arguments map[string]any) (bool, string) {
	if !taskReviewDirtyWorkspaceRejectOnlyApplies(rt) {
		return false, ""
	}
	switch strings.ToLower(strings.TrimSpace(toolName)) {
	case "flow.review_decision", "flow_review_decision":
		return false, ""
	default:
		return true, buildTaskReviewDirtyWorkspaceRetryGuardError(toolName)
	}
}

func shouldBlockTaskReviewRepeatedCheckpointOutputTool(rt *turnRuntime, toolName string, arguments map[string]any) (bool, string) {
	if !taskReviewPromptActive(rt) {
		return false, ""
	}
	repeatedPaths := parseReviewPromptRepeatedCheckpointOutputPaths(strings.TrimSpace(rt.initialMessageText))
	if len(repeatedPaths) == 0 {
		return false, ""
	}
	rootPath := taskReviewPreferredDeliverableRoot(rt)
	switch strings.ToLower(strings.TrimSpace(toolName)) {
	case "file.read", "file_read":
		path := normalizeWorkspaceRelativePath(stringValue(arguments["path"]))
		if path == "" {
			return false, ""
		}
		if intValue(arguments["offset_bytes"]) > 0 {
			return false, ""
		}
		for _, repeated := range repeatedPaths {
			if sameWorkspaceRelativePath(path, repeated) {
				return true, buildTaskReviewRepeatedCheckpointOutputGuardError(rootPath, path, "file.read")
			}
		}
	case "file.list", "file_list":
		path := normalizeWorkspaceRelativePath(stringValue(arguments["path"]))
		if rootPath != "" && sameWorkspaceRelativePath(path, rootPath) {
			return true, buildTaskReviewRepeatedCheckpointOutputGuardError(rootPath, path, "file.list")
		}
	}
	return false, ""
}

func shouldBlockTaskReviewAuthoritativeCheckpointOutputTool(rt *turnRuntime, toolName string, arguments map[string]any) (bool, string) {
	rootPath := taskReviewPreferredDeliverableRoot(rt)
	if !taskReviewPromptTreatsCheckpointOutputSetAsAuthoritative(rt, rootPath) {
		return false, ""
	}
	switch strings.ToLower(strings.TrimSpace(toolName)) {
	case "git.status", "git_status", "git.diff", "git_diff", "git.log", "git_log":
		return true, buildTaskReviewCheckpointOutputSetAuthoritativeRepoStateGuardError(rootPath, toolName)
	default:
		return false, ""
	}
}

func (e *TurnEngine) maybeRewriteTaskReviewPreferredDeliverableReadToolCalls(ctx context.Context, rt *turnRuntime, toolCalls []ModelToolCall) ([]ModelToolCall, bool, error) {
	if !taskReviewPreferredDeliverableFirstApplies(rt) || len(toolCalls) == 0 {
		return toolCalls, false, nil
	}
	targetPath := taskReviewPreferredDeliverableTarget(rt)
	if targetPath == "" {
		return toolCalls, false, nil
	}
	tailOffset, hasTailOffset, err := e.taskReviewPreferredDeliverableTailReadOffset(ctx, rt, targetPath)
	if err != nil {
		return nil, false, err
	}

	rewritten := false
	out := make([]ModelToolCall, 0, len(toolCalls))
	for _, call := range toolCalls {
		switch strings.ToLower(strings.TrimSpace(call.Name)) {
		case "file.read", "file_read":
		default:
			out = append(out, call)
			continue
		}

		path := normalizeWorkspaceRelativePath(stringValue(call.Arguments["path"]))
		if path == "" {
			out = append(out, call)
			continue
		}
		if siblingMaxBytes, ok := taskReviewCheckpointOutputSiblingReadMaxBytesForBatch(rt, toolCalls, path, targetPath); ok {
			callCopy := call
			changedCall := false
			explicitMaxBytes := intValue(call.Arguments["max_bytes"])
			if explicitMaxBytes <= 0 || explicitMaxBytes > siblingMaxBytes {
				if callCopy.Arguments == nil {
					callCopy.Arguments = map[string]any{}
				} else {
					callCopy.Arguments = cloneMap(call.Arguments)
				}
				callCopy.Arguments["max_bytes"] = siblingMaxBytes
				changedCall = true
			}
			if changedCall {
				callCopy.Name = "file.read"
				out = append(out, callCopy)
				rewritten = true
				continue
			}
			out = append(out, call)
			continue
		}
		if !sameWorkspaceRelativePath(path, targetPath) {
			out = append(out, call)
			continue
		}

		callCopy := call
		changedCall := false
		explicitOffsetBytes := intValue(call.Arguments["offset_bytes"])
		if hasTailOffset && explicitOffsetBytes <= 0 {
			if callCopy.Arguments == nil {
				callCopy.Arguments = map[string]any{}
			} else {
				callCopy.Arguments = cloneMap(call.Arguments)
			}
			callCopy.Arguments["offset_bytes"] = tailOffset
			changedCall = true
		}

		explicitMaxBytes := intValue(call.Arguments["max_bytes"])
		if explicitMaxBytes <= 0 || explicitMaxBytes > taskReviewPreferredDeliverableReadMaxBytes {
			if !changedCall {
				if callCopy.Arguments == nil {
					callCopy.Arguments = map[string]any{}
				} else {
					callCopy.Arguments = cloneMap(call.Arguments)
				}
			}
			callCopy.Arguments["max_bytes"] = taskReviewPreferredDeliverableReadMaxBytes
			changedCall = true
		}

		if changedCall {
			callCopy.Name = "file.read"
			out = append(out, callCopy)
			rewritten = true
			continue
		}

		out = append(out, call)
	}
	if !rewritten {
		return toolCalls, false, nil
	}
	return out, true, nil
}

func (e *TurnEngine) taskReviewPreferredDeliverableTailReadOffset(ctx context.Context, rt *turnRuntime, targetPath string) (int, bool, error) {
	if rt == nil || rt.session == nil || rt.session.ID == uuid.Nil {
		return 0, false, nil
	}

	headReadTruncated := false
	tailReadSeen := false
	byteSize := 0
	if sameWorkspaceRelativePath(strings.TrimSpace(rt.reviewPreferredDeliverablePath), targetPath) {
		headReadTruncated = rt.reviewPreferredDeliverableHeadTruncated
		tailReadSeen = rt.reviewPreferredDeliverableTailReadSeen
		byteSize = rt.reviewPreferredDeliverableByteSize
	}
	if (e == nil || e.messages == nil) && headReadTruncated && !tailReadSeen && byteSize > taskReviewPreferredDeliverableReadMaxBytes {
		tailOffset := byteSize - taskReviewPreferredDeliverableReadMaxBytes
		if tailOffset > 0 {
			return tailOffset, true, nil
		}
	}
	if e == nil || e.messages == nil {
		return 0, false, nil
	}

	messages, err := e.messages.ListBySession(ctx, rt.session.ID)
	if err != nil {
		return 0, false, err
	}

	for _, message := range messages {
		if !strings.EqualFold(strings.TrimSpace(message.Role), "tool_result") {
			continue
		}
		toolName, output, errText, ok := parseToolResultMessage(message.Content)
		if !ok || strings.TrimSpace(errText) != "" || !strings.EqualFold(strings.TrimSpace(toolName), "file.read") {
			continue
		}
		path := normalizeWorkspaceRelativePath(anyString(output["path"]))
		if path == "" || !sameWorkspaceRelativePath(path, targetPath) {
			continue
		}
		if size := intValue(output["byte_size"]); size > byteSize {
			byteSize = size
		}
		offsetBytes := intValue(output["offset_bytes"])
		if offsetBytes < 0 {
			offsetBytes = 0
		}
		readBytes := intValue(output["bytes_read"])
		if readBytes <= 0 {
			readBytes = len([]byte(anyString(output["content"])))
		}
		truncated, _ := boolValue(output["truncated"])
		if offsetBytes == 0 && truncated && readBytes > 0 {
			headReadTruncated = true
		}
		if offsetBytes > 0 && readBytes > 0 {
			tailReadSeen = true
		}
	}
	if !headReadTruncated || tailReadSeen || byteSize <= taskReviewPreferredDeliverableReadMaxBytes {
		return 0, false, nil
	}
	tailOffset := byteSize - taskReviewPreferredDeliverableReadMaxBytes
	if tailOffset <= 0 {
		return 0, false, nil
	}
	return tailOffset, true, nil
}

func recordTaskReviewPreferredDeliverableReadResult(rt *turnRuntime, result ToolResult) {
	if rt == nil || !taskReviewPreferredDeliverableFirstApplies(rt) {
		return
	}
	rootPath := taskReviewPreferredDeliverableRoot(rt)
	targetPath := taskReviewPreferredDeliverableTarget(rt)
	switch strings.ToLower(strings.TrimSpace(result.Name)) {
	case "file.list":
		if targetPath == "" && rootPath != "" && len(result.Output) != 0 {
			if _, ok := result.Output["entries"]; ok {
				rt.reviewPreferredDeliverableRootListed = true
			}
		}
		return
	case "file.read":
	default:
		return
	}
	if len(result.Output) == 0 {
		return
	}
	path := normalizeWorkspaceRelativePath(anyString(result.Output["path"]))
	if path == "" {
		return
	}
	if targetPath == "" {
		if rootPath != "" &&
			(rt.reviewPreferredDeliverableRootListed || taskReviewPromptTreatsCheckpointOutputSetAsAuthoritative(rt, rootPath)) &&
			workspacePathWithinRoot(path, rootPath) &&
			intValue(result.Output["byte_size"]) > 0 {
			rt.reviewCheckpointOutputSiblingReads++
		}
		return
	}
	if !sameWorkspaceRelativePath(path, targetPath) {
		if rootPath == "" {
			rootPath = normalizeWorkspaceRelativePath(filepath.ToSlash(filepath.Dir(targetPath)))
		}
		if rootPath != "" &&
			taskReviewPromptTreatsCheckpointOutputSetAsAuthoritative(rt, rootPath) &&
			sameWorkspaceRelativePath(strings.TrimSpace(rt.reviewPreferredDeliverablePath), targetPath) &&
			workspacePathWithinRoot(path, rootPath) &&
			intValue(result.Output["byte_size"]) > 0 {
			rt.reviewCheckpointOutputSiblingReads++
		}
		return
	}
	if strings.TrimSpace(result.Error) != "" || strings.TrimSpace(anyString(result.Output["error"])) != "" {
		return
	}
	readBytes := intValue(result.Output["bytes_read"])
	if readBytes <= 0 {
		readBytes = len([]byte(anyString(result.Output["content"])))
	}
	if readBytes <= 0 && intValue(result.Output["byte_size"]) <= 0 {
		return
	}
	rt.reviewPreferredDeliverablePath = targetPath
	if size := intValue(result.Output["byte_size"]); size > rt.reviewPreferredDeliverableByteSize {
		rt.reviewPreferredDeliverableByteSize = size
	}
	offsetBytes := intValue(result.Output["offset_bytes"])
	if offsetBytes < 0 {
		offsetBytes = 0
	}
	truncated, _ := boolValue(result.Output["truncated"])
	if offsetBytes == 0 && truncated && readBytes > 0 {
		rt.reviewPreferredDeliverableHeadTruncated = true
	}
	if offsetBytes > 0 && readBytes > 0 {
		rt.reviewPreferredDeliverableTailReadSeen = true
	}
}

func rewriteTaskReviewPreferredDeliverableReadDispatchCall(rt *turnRuntime, toolName string, arguments map[string]any) (string, map[string]any) {
	if !taskReviewPreferredDeliverableFirstApplies(rt) {
		return toolName, arguments
	}
	switch strings.ToLower(strings.TrimSpace(toolName)) {
	case "file.read", "file_read":
	default:
		return toolName, arguments
	}
	targetPath := taskReviewPreferredDeliverableTarget(rt)
	path := normalizeWorkspaceRelativePath(stringValue(arguments["path"]))
	if targetPath == "" || path == "" {
		return toolName, arguments
	}
	if siblingMaxBytes, ok := taskReviewCheckpointOutputSiblingReadMaxBytesAfterTargetRead(rt, path, targetPath); ok {
		explicitMaxBytes := intValue(arguments["max_bytes"])
		if explicitMaxBytes > 0 && explicitMaxBytes <= siblingMaxBytes {
			return toolName, arguments
		}
		rewritten := cloneMap(arguments)
		rewritten["max_bytes"] = siblingMaxBytes
		return "file.read", rewritten
	}
	if !sameWorkspaceRelativePath(path, targetPath) {
		return toolName, arguments
	}
	if !rt.reviewPreferredDeliverableHeadTruncated || rt.reviewPreferredDeliverableTailReadSeen || rt.reviewPreferredDeliverableByteSize <= taskReviewPreferredDeliverableReadMaxBytes {
		return toolName, arguments
	}
	tailOffset := rt.reviewPreferredDeliverableByteSize - taskReviewPreferredDeliverableReadMaxBytes
	if tailOffset <= 0 {
		return toolName, arguments
	}
	explicitOffsetBytes := intValue(arguments["offset_bytes"])
	explicitMaxBytes := intValue(arguments["max_bytes"])
	if explicitOffsetBytes > 0 && explicitMaxBytes > 0 && explicitMaxBytes <= taskReviewPreferredDeliverableReadMaxBytes {
		return toolName, arguments
	}
	rewritten := cloneMap(arguments)
	if explicitOffsetBytes <= 0 {
		rewritten["offset_bytes"] = tailOffset
	}
	if explicitMaxBytes <= 0 || explicitMaxBytes > taskReviewPreferredDeliverableReadMaxBytes {
		rewritten["max_bytes"] = taskReviewPreferredDeliverableReadMaxBytes
	}
	return "file.read", rewritten
}

func taskReviewCheckpointOutputSiblingReadMaxBytesForBatch(rt *turnRuntime, calls []ModelToolCall, path, targetPath string) (int, bool) {
	if !taskReviewBatchIncludesPreferredDeliverableRead(calls, targetPath) {
		return 0, false
	}
	return taskReviewCheckpointOutputSiblingReadMaxBytes(rt, path, targetPath)
}

func taskReviewCheckpointOutputSiblingReadMaxBytesAfterTargetRead(rt *turnRuntime, path, targetPath string) (int, bool) {
	if !sameWorkspaceRelativePath(strings.TrimSpace(rt.reviewPreferredDeliverablePath), targetPath) {
		return 0, false
	}
	return taskReviewCheckpointOutputSiblingReadMaxBytes(rt, path, targetPath)
}

func taskReviewCheckpointOutputSiblingReadMaxBytes(rt *turnRuntime, path, targetPath string) (int, bool) {
	if rt == nil || path == "" || targetPath == "" || sameWorkspaceRelativePath(path, targetPath) {
		return 0, false
	}
	rootPath := taskReviewPreferredDeliverableRoot(rt)
	if rootPath == "" {
		rootPath = normalizeWorkspaceRelativePath(filepath.ToSlash(filepath.Dir(targetPath)))
	}
	if rootPath == "" || !taskReviewPromptTreatsCheckpointOutputSetAsAuthoritative(rt, rootPath) {
		return 0, false
	}
	if !workspacePathWithinRoot(path, rootPath) {
		return 0, false
	}
	return taskReviewCheckpointOutputReadMaxBytes, true
}

func shouldBlockTaskReviewPreferredDeliverableFirstTool(rt *turnRuntime, toolName string, arguments map[string]any) (bool, string) {
	if !taskReviewPreferredDeliverableFirstApplies(rt) {
		return false, ""
	}
	normalizedToolName := strings.ToLower(strings.TrimSpace(toolName))
	targetPath := taskReviewPreferredDeliverableTarget(rt)
	if targetPath == "" {
		return false, ""
	}
	switch normalizedToolName {
	case "file.read", "file_read":
		path := normalizeWorkspaceRelativePath(stringValue(arguments["path"]))
		if path == "" {
			return false, ""
		}
		if sameWorkspaceRelativePath(path, targetPath) {
			offsetBytes := intValue(arguments["offset_bytes"])
			if sameWorkspaceRelativePath(strings.TrimSpace(rt.reviewPreferredDeliverablePath), targetPath) &&
				!rt.reviewPreferredDeliverableHeadTruncated &&
				offsetBytes <= 0 {
				return true, buildTaskReviewRepeatedPreferredDeliverableReadGuardError(targetPath)
			}
			return false, ""
		}
		rootPath := taskReviewPreferredDeliverableRoot(rt)
		if rootPath == "" {
			rootPath = normalizeWorkspaceRelativePath(filepath.ToSlash(filepath.Dir(targetPath)))
		}
		if rootPath != "" &&
			taskReviewPromptTreatsCheckpointOutputSetAsAuthoritative(rt, rootPath) &&
			sameWorkspaceRelativePath(strings.TrimSpace(rt.reviewPreferredDeliverablePath), targetPath) &&
			workspacePathWithinRoot(path, rootPath) {
			if rt.reviewCheckpointOutputSiblingReads >= taskReviewCheckpointOutputSampleCap {
				return true, buildTaskReviewCheckpointOutputSampleCapGuardError(rootPath, taskReviewCheckpointOutputSampleCap)
			}
			return false, ""
		}
		return true, buildTaskReviewPreferredDeliverableFirstGuardError(targetPath, "file.read")
	case "file.list", "file_list", "file.search", "file_search":
		return true, buildTaskReviewPreferredDeliverableFirstGuardError(targetPath, normalizedToolName)
	case "task.get", "task_get", "task.list", "task_list":
		return true, buildTaskReviewPreferredDeliverableFirstGuardError(targetPath, normalizedToolName)
	case "git.diff", "git_diff", "git.status", "git_status", "git.log", "git_log":
		return true, buildTaskReviewPreferredDeliverableFirstGuardError(targetPath, normalizedToolName)
	default:
		return false, ""
	}
}

func shouldBlockTaskReviewPreferredDeliverableRootFirstTool(rt *turnRuntime, calls []ModelToolCall, toolCallID, toolName string, arguments map[string]any) (bool, string) {
	if !taskReviewPreferredDeliverableRootFirstApplies(rt) {
		return false, ""
	}
	normalizedToolName := strings.ToLower(strings.TrimSpace(toolName))
	rootPath := taskReviewPreferredDeliverableRoot(rt)
	if rootPath == "" {
		return false, ""
	}
	switch normalizedToolName {
	case "file.read", "file_read", "file.list", "file_list", "file.search", "file_search":
		path := normalizeWorkspaceRelativePath(stringValue(arguments["path"]))
		if taskReviewPromptTreatsCheckpointOutputSetAsAuthoritative(rt, rootPath) &&
			(normalizedToolName == "file.list" || normalizedToolName == "file_list" || normalizedToolName == "file.search" || normalizedToolName == "file_search") &&
			path != "" && sameWorkspaceRelativePath(path, rootPath) {
			return true, buildTaskReviewCheckpointOutputSetAuthoritativeGuardError(rootPath, normalizedToolName)
		}
		if path != "" && workspacePathWithinRoot(path, rootPath) {
			if (normalizedToolName == "file.read" || normalizedToolName == "file_read") &&
				(rt.reviewPreferredDeliverableRootListed ||
					taskReviewPromptTreatsCheckpointOutputSetAsAuthoritative(rt, rootPath)) {
				if ordinal := taskReviewCheckpointOutputSiblingReadOrdinal(rt, calls, toolCallID, "", rootPath); ordinal > taskReviewCheckpointOutputSampleCap {
					return true, buildTaskReviewCheckpointOutputSampleCapGuardError(rootPath, taskReviewCheckpointOutputSampleCap)
				}
			}
			if (normalizedToolName == "file.read" || normalizedToolName == "file_read") &&
				(rt.reviewPreferredDeliverableRootListed ||
					taskReviewPromptTreatsCheckpointOutputSetAsAuthoritative(rt, rootPath)) &&
				rt.reviewCheckpointOutputSiblingReads >= taskReviewCheckpointOutputSampleCap {
				return true, buildTaskReviewCheckpointOutputSampleCapGuardError(rootPath, taskReviewCheckpointOutputSampleCap)
			}
			return false, ""
		}
		if taskReviewPromptNamesCheckpointOutputSet(rt, rootPath) {
			return true, buildTaskReviewPreferredDeliverableRootCheckpointOutputGuardError(rootPath, path, normalizedToolName)
		}
		return true, buildTaskReviewPreferredDeliverableRootFirstGuardError(rootPath, normalizedToolName)
	case "task.get", "task_get", "task.list", "task_list":
		return true, buildTaskReviewPreferredDeliverableRootFirstGuardError(rootPath, normalizedToolName)
	case "git.diff", "git_diff", "git.status", "git_status", "git.log", "git_log":
		return true, buildTaskReviewPreferredDeliverableRootFirstGuardError(rootPath, normalizedToolName)
	default:
		return false, ""
	}
}

func parseReviewPromptRepeatedCheckpointOutputPaths(content string) []string {
	const marker = "Do not reread these already-inspected checkpoint outputs this turn:"
	for _, line := range strings.Split(content, "\n") {
		trimmed := strings.TrimSpace(line)
		if !strings.HasPrefix(trimmed, marker) {
			continue
		}
		matches := workspacePathInBackticksPattern.FindAllStringSubmatch(trimmed, -1)
		if len(matches) == 0 {
			return nil
		}
		seen := make(map[string]struct{}, len(matches))
		paths := make([]string, 0, len(matches))
		for _, match := range matches {
			if len(match) < 2 {
				continue
			}
			path := normalizeWorkspaceRelativePath(match[1])
			if path == "" {
				continue
			}
			if _, ok := seen[path]; ok {
				continue
			}
			seen[path] = struct{}{}
			paths = append(paths, path)
		}
		return paths
	}
	return nil
}

func shouldBlockTaskReviewCompanionPlanningArtifactTool(rt *turnRuntime, toolName string, arguments map[string]any) (bool, string) {
	if !taskReviewCompanionPlanningArtifactBlockApplies(rt) {
		return false, ""
	}
	normalizedToolName := strings.ToLower(strings.TrimSpace(toolName))
	switch normalizedToolName {
	case "file.read", "file_read", "file.list", "file_list", "file.search", "file_search":
	default:
		return false, ""
	}
	path := normalizeWorkspaceRelativePath(stringValue(arguments["path"]))
	if path == "" || !projectBootstrapRecoveryReadsPlanningPath(map[string]any{"path": path}) {
		return false, ""
	}
	targetPath := taskReviewPreferredDeliverableTarget(rt)
	if targetPath != "" && sameWorkspaceRelativePath(path, targetPath) {
		return false, ""
	}
	return true, buildTaskReviewCompanionPlanningArtifactGuardError(targetPath, normalizedToolName, path)
}

func taskReviewPromptActive(rt *turnRuntime) bool {
	if rt == nil || rt.session == nil {
		return false
	}
	if !strings.EqualFold(strings.TrimSpace(rt.session.ScopeType), "project_task") || !strings.EqualFold(strings.TrimSpace(rt.session.Mode), "async") {
		return false
	}
	content := strings.TrimSpace(rt.initialMessageText)
	return strings.HasPrefix(content, "Review only.") && strings.Contains(content, "flow.review_decision")
}

func taskReviewPreferredDeliverableFirstApplies(rt *turnRuntime) bool {
	if !taskReviewPromptActive(rt) {
		return false
	}
	return !strings.Contains(strings.TrimSpace(rt.initialMessageText), "This task is an orchestration-only parent.")
}

func taskReviewDirtyWorkspaceRejectOnlyApplies(rt *turnRuntime) bool {
	if !taskReviewPromptActive(rt) {
		return false
	}
	initial := strings.TrimSpace(rt.initialMessageText)
	return strings.Contains(initial, "workspace is still dirty") &&
		strings.Contains(initial, "reissue flow.review_decision immediately with decision=reject")
}

func taskReviewPromptNamesCheckpointOutputSet(rt *turnRuntime, rootPath string) bool {
	if rt == nil {
		return false
	}
	rootPath = normalizeWorkspaceRelativePath(rootPath)
	if rootPath == "" {
		return false
	}
	marker := fmt.Sprintf("The checkpoint already identifies the task-owned outputs under `%s`:", rootPath)
	return strings.Contains(strings.TrimSpace(rt.initialMessageText), marker)
}

func taskReviewPromptTreatsCheckpointOutputSetAsAuthoritative(rt *turnRuntime, rootPath string) bool {
	if !taskReviewPromptNamesCheckpointOutputSet(rt, rootPath) || rt == nil {
		return false
	}
	return strings.Contains(strings.TrimSpace(rt.initialMessageText), "Treat that output set as authoritative for this batch;")
}

func taskReviewPreferredDeliverableRootFirstApplies(rt *turnRuntime) bool {
	if !taskReviewPromptActive(rt) {
		return false
	}
	if strings.Contains(strings.TrimSpace(rt.initialMessageText), "This task is an orchestration-only parent.") {
		return false
	}
	return taskReviewPreferredDeliverableTarget(rt) == "" && taskReviewPreferredDeliverableRoot(rt) != ""
}

func taskReviewCompanionPlanningArtifactBlockApplies(rt *turnRuntime) bool {
	if !taskReviewPromptActive(rt) {
		return false
	}
	initial := strings.TrimSpace(rt.initialMessageText)
	if strings.Contains(initial, "This task is an orchestration-only parent.") {
		return false
	}
	return strings.Contains(initial, "Do not invent companion planning-artifact requirements")
}

func taskReviewPreferredDeliverableRoot(rt *turnRuntime) string {
	if !taskReviewPromptActive(rt) {
		return ""
	}
	return parsePromptDeliverableRoot(strings.TrimSpace(rt.initialMessageText))
}

func taskReviewPreferredDeliverableTarget(rt *turnRuntime) string {
	if !taskReviewPromptActive(rt) {
		return ""
	}
	return parsePromptDeliverableTarget(strings.TrimSpace(rt.initialMessageText))
}

func recoveryPromptHasDurableDraftInstruction(rt *turnRuntime) bool {
	if rt == nil {
		return false
	}
	initialMessage := strings.ToLower(strings.TrimSpace(rt.initialMessageText))
	if initialMessage == "" {
		return false
	}
	return strings.Contains(initialMessage, "a substantive durable draft is already available above") ||
		strings.Contains(initialMessage, "the substantive draft is already present above")
}

func recoveryPromptRequiresDirectWriteOnly(initialMessage string) bool {
	lower := strings.ToLower(strings.TrimSpace(initialMessage))
	if lower == "" {
		return false
	}
	return strings.Contains(lower, "your entire next assistant message must be either the concrete file body for the target deliverable or one concrete blocker sentence") &&
		strings.Contains(lower, "no recovered draft body is available above")
}

func recoveryCheckpointHistoryRequiresDirectWriteOnly(checkpoint taskcheckpoint.RecoveryFileWriteCheckpoint) bool {
	for _, reason := range taskcheckpoint.RecoveryFileWriteFailureHistory(&checkpoint) {
		if taskcheckpoint.RecoveryFileWriteFailureRejectsDraft(reason) ||
			taskcheckpoint.RecoveryFileWriteFailureIsMissingContent(reason) ||
			taskcheckpoint.RecoveryFileWriteFailureIsIntentOnly(reason) {
			return true
		}
	}
	return false
}

func taskReviewBatchIncludesPreferredDeliverableRead(calls []ModelToolCall, targetPath string) bool {
	targetPath = normalizeWorkspaceRelativePath(targetPath)
	if targetPath == "" {
		return false
	}
	for _, call := range calls {
		switch strings.ToLower(strings.TrimSpace(call.Name)) {
		case "file.read", "file_read":
		default:
			continue
		}
		callPath := normalizeWorkspaceRelativePath(stringValue(call.Arguments["path"]))
		if callPath != "" && sameWorkspaceRelativePath(callPath, targetPath) {
			return true
		}
	}
	return false
}

func taskRecoveryReadPathMatchesTask(path string, taskNumber int) bool {
	if taskNumber <= 0 {
		return false
	}
	normalized := normalizeWorkspaceRelativePath(path)
	if normalized == "" {
		return false
	}
	lower := strings.ToLower(normalized)
	if strings.HasPrefix(lower, "planning/") {
		if hinted, ok := recoveryCheckpointTaskNumberHint(lower); ok && hinted == taskNumber {
			return true
		}
	}
	if hinted, ok := recoveryCheckpointTaskNumberHint(lower); ok && hinted == taskNumber {
		return true
	}
	return false
}

func (e *TurnEngine) recoveryDirectWriteOnlyState(ctx context.Context, session *chat.ChatSession, targetPath, initialMessageText string) bool {
	if e == nil || e.tasks == nil || session == nil {
		return false
	}
	if !strings.EqualFold(strings.TrimSpace(session.ScopeType), "project_task") ||
		!strings.EqualFold(strings.TrimSpace(session.Mode), "async") {
		return false
	}
	targetPath = normalizeWorkspaceRelativePath(strings.TrimSpace(targetPath))
	if targetPath == "" {
		return false
	}
	if !recoveryPromptRequiresDirectWriteOnly(initialMessageText) {
		return false
	}
	lowerInitial := strings.ToLower(strings.TrimSpace(initialMessageText))
	if strings.HasPrefix(strings.ToLower(targetPath), "content/posts/") &&
		containsAny(lowerInitial,
			"fetch or source the real post body",
			"multi-output content/posts batch",
			"checkpoint-owned output root/artifact context",
			"technonymous-index.json",
			"use web_fetch",
			"via web_fetch",
		) {
		return false
	}
	taskID := resolveTaskID(session)
	if taskID == nil || *taskID == uuid.Nil {
		return false
	}
	taskRecord, err := e.tasks.GetByID(ctx, *taskID)
	if err != nil {
		return false
	}
	checkpoint, ok := taskcheckpoint.ParseRecoveryFileWriteCheckpoint(taskRecord.Metadata)
	if !ok {
		return false
	}
	checkpointTarget := normalizeWorkspaceRelativePath(strings.TrimSpace(checkpoint.TargetPath))
	if checkpointTarget != "" && !sameWorkspaceRelativePath(checkpointTarget, targetPath) {
		return false
	}
	return recoveryCheckpointHistoryRequiresDirectWriteOnly(checkpoint)
}

func taskToolTouchesRecoveryStatusPath(arguments map[string]any) bool {
	for _, key := range []string{"path", "file_path", "target_path", "artifact_path", "file_pattern", "pattern"} {
		if taskToolArgumentReferencesRecoveryStatusPath(anyString(arguments[key])) {
			return true
		}
	}
	return false
}

func taskToolArgumentReferencesRecoveryStatusPath(raw string) bool {
	normalized := strings.ToLower(filepath.ToSlash(strings.TrimSpace(raw)))
	if normalized == "" {
		return false
	}
	return normalized == ".ottercamp/recovery" ||
		strings.HasPrefix(normalized, ".ottercamp/recovery/") ||
		normalized == "planning/recovery-state" ||
		strings.HasPrefix(normalized, "planning/recovery-state/") ||
		normalized == "planning/checkpoint" ||
		strings.HasPrefix(normalized, "planning/checkpoint/")
}

func projectBootstrapRecoveryReadsPlanningPath(arguments map[string]any) bool {
	path := strings.TrimSpace(stringValue(arguments["path"]))
	if path == "" {
		return false
	}
	normalized := strings.ToLower(strings.ReplaceAll(path, "\\", "/"))
	return normalized == "planning" ||
		strings.HasPrefix(normalized, "planning/") ||
		strings.Contains(normalized, "/planning/")
}

func projectBootstrapFailureNeedsDirectRepair(failureClass string) bool {
	switch strings.TrimSpace(failureClass) {
	case projectBootstrapFailureCompoundParent,
		projectBootstrapFailureSetupTaskScope,
		projectBootstrapFailureSetupTaskChildren,
		projectBootstrapFailureFirstWaveSize,
		projectBootstrapFailureFirstWaveFlow,
		projectBootstrapFailureFirstWaveExecution:
		return true
	default:
		return false
	}
}

func projectBootstrapStateHasPersistedTaskTree(state projectBootstrapState) bool {
	if state.PlannedTaskCount > 0 || state.PlannedFlowTemplateCount > 0 || state.FirstWaveTaskCount > 0 || state.FirstWavePromotedCount > 0 || state.FirstWaveJobCount > 0 {
		return true
	}
	switch strings.TrimSpace(state.CurrentPhase) {
	case projectBootstrapCheckpointTaskTreePersisted,
		projectBootstrapCheckpointFlowTemplatesPersisted,
		projectBootstrapCheckpointFirstWaveSelected,
		projectBootstrapCheckpointFirstWaveExecutions,
		projectBootstrapCheckpointFirstWaveJobsClaimed:
		return true
	}
	switch strings.TrimSpace(state.LastSuccessfulCheckpoint) {
	case projectBootstrapCheckpointTaskTreePersisted,
		projectBootstrapCheckpointFlowTemplatesPersisted,
		projectBootstrapCheckpointFirstWaveSelected,
		projectBootstrapCheckpointFirstWaveExecutions,
		projectBootstrapCheckpointFirstWaveJobsClaimed:
		return true
	}
	return false
}

