func looksLikeGenericFunctionFormattingReply(normalized string) bool {
	if !strings.Contains(normalized, "function") && !strings.Contains(normalized, "json") && !strings.Contains(normalized, "tool") {
		return false
	}
	requestSignals := []string{
		"please specify",
		"please provide",
		"could you please specify",
		"could you please provide",
		"could you please tell me",
		"tell me which",
		"let me know which",
		"what do you need",
	}
	detailSignals := []string{
		"details",
		"context",
		"arguments",
		"parameters",
		"function call",
		"operation",
		"task or action",
		"construct",
	}
	if containsAny(normalized, requestSignals...) && containsAny(normalized, detailSignals...) {
		return true
	}
	if strings.Contains(normalized, "format") && strings.Contains(normalized, "json") && (strings.Contains(normalized, "function") || strings.Contains(normalized, "tool")) {
		return true
	}
	if strings.Contains(normalized, "json-rpc") && (strings.Contains(normalized, "function") || strings.Contains(normalized, "parameters")) {
		return true
	}
	return false
}

func looksLikeGenericExistingProjectProceedReply(normalized string) bool {
	if !strings.Contains(normalized, "existing project") && !strings.Contains(normalized, "project has already been created") && !strings.Contains(normalized, "project with the slug") {
		return false
	}
	if strings.Contains(normalized, "continue working") || strings.Contains(normalized, "start over") || strings.Contains(normalized, "how you would like to proceed") || strings.Contains(normalized, "let me know") || strings.Contains(normalized, "proceed with the existing project") || strings.Contains(normalized, "explicitly want to start a new one") {
		return true
	}
	return false
}

func buildGenericRecoveryReplyBlockedReason(reply string, attempts int) string {
	trimmed := strings.TrimSpace(reply)
	if trimmed == "" {
		return fmt.Sprintf("recovery halted after %d retries without a usable assistant response; re-queue only when the next attempt can continue the task directly", attempts)
	}
	return fmt.Sprintf("recovery halted after %d generic non-action replies; latest reply=%q", attempts, trimmed)
}

func completedWorkSignalFromMessages(taskRecord repo.ProjectTask, messages []repo.ChatMessage, turnID uuid.UUID) (workCompletionSignal, bool) {
	var latest workCompletionSignal
	found := false
	for _, message := range messages {
		if message.TurnID == nil || *message.TurnID != turnID {
			continue
		}
		if !strings.EqualFold(strings.TrimSpace(message.Role), "tool_result") {
			continue
		}
		toolName, output, errText, ok := parseToolResultMessage(message.Content)
		if !ok || strings.TrimSpace(errText) != "" {
			continue
		}
		if !strings.EqualFold(toolName, "git.commit") {
			if substantiveExecutionDeliverableReadCompleted(taskRecord, ToolResult{Name: toolName, Output: output}) {
				latest = workCompletionSignal{filesCommitted: 1}
				found = true
				continue
			}
			if !explicitExecutionDeliverableWriteCompleted(taskRecord, ToolResult{Name: toolName, Output: output}) {
				continue
			}
			latest = workCompletionSignal{filesCommitted: 1}
			found = true
			continue
		}
		commitSHA := strings.TrimSpace(anyString(output["sha"]))
		if commitSHA == "" {
			commitSHA = strings.TrimSpace(anyString(output["short_sha"]))
		}
		filesCommitted := anyInt(output["files_committed"])
		if commitSHA == "" || filesCommitted < 1 {
			continue
		}
		latest = workCompletionSignal{
			commitSHA:      commitSHA,
			filesCommitted: filesCommitted,
		}
		found = true
	}
	return latest, found
}

func substantiveExecutionDeliverableReadCompleted(taskRecord repo.ProjectTask, result ToolResult) bool {
	if !strings.EqualFold(strings.TrimSpace(result.Name), "file.read") || strings.TrimSpace(result.Error) != "" {
		return false
	}
	readPath := normalizeWorkspaceRelativePath(anyString(result.Output["path"]))
	content := strings.TrimSpace(anyString(result.Output["content"]))
	if readPath == "" || content == "" || len(content) < 400 {
		return false
	}
	if reason := recoveryFileWriteDraftRejectReason(content, readPath); reason != "" {
		return false
	}
	if preferredPath := normalizeWorkspaceRelativePath(preferredTaskDeliverablePath(taskRecord)); preferredPath != "" && sameWorkspaceRelativePath(readPath, preferredPath) {
		return true
	}
	if checkpoint, ok := taskcheckpoint.ParseRecoveryFileWriteCheckpoint(taskRecord.Metadata); ok {
		targetPath := normalizeWorkspaceRelativePath(checkpoint.TargetPath)
		if targetPath != "" && sameWorkspaceRelativePath(readPath, targetPath) {
			return true
		}
	}
	return false
}

func explicitDeliverablePath(taskRecord repo.ProjectTask) string {
	for _, description := range taskContractDescriptionCandidates(taskRecord) {
		for _, pattern := range explicitDeliverablePathPatterns {
			matches := pattern.FindStringSubmatch(description)
			if len(matches) < 2 {
				continue
			}
			rawCandidate := strings.TrimSpace(matches[1])
			candidate := normalizeExplicitDeliverablePathCandidate(rawCandidate)
			if !looksLikeExplicitDeliverablePath(candidate, rawCandidate) {
				continue
			}
			return candidate
		}
		if match := leadingVerbDeliverablePathPattern.FindStringSubmatch(description); len(match) >= 2 {
			rawCandidate := strings.TrimSpace(match[1])
			candidate := normalizeExplicitDeliverablePathCandidate(rawCandidate)
			if strings.Contains(candidate, "/") || strings.Contains(filepath.Base(candidate), ".") {
				return candidate
			}
		}
	}
	return ""
}

func taskContractDescriptionCandidates(taskRecord repo.ProjectTask) []string {
	candidates := make([]string, 0, 2)
	appendCandidate := func(raw string) {
		normalized := strings.TrimSpace(raw)
		if normalized == "" {
			return
		}
		for _, existing := range candidates {
			if existing == normalized {
				return
			}
		}
		candidates = append(candidates, normalized)
	}
	if taskRecord.Description != nil {
		appendCandidate(*taskRecord.Description)
	}
	metadata := messageMetadataMap(taskRecord.Metadata)
	decomposition, _ := metadata["decomposition"].(map[string]any)
	appendCandidate(anyString(decomposition["source_description"]))
	return candidates
}

func normalizeExplicitDeliverablePathCandidate(raw string) string {
	trimmed := strings.TrimSpace(raw)
	trimmed = strings.Trim(trimmed, "`'\"“”‘’()[]{}")
	trimmed = strings.TrimRight(trimmed, ".,:;!?")
	trimmed = strings.Trim(trimmed, "`'\"“”‘’()[]{}")
	return normalizeWorkspaceRelativePath(trimmed)
}

func looksLikeExplicitDeliverablePath(normalized, raw string) bool {
	if normalized == "" {
		return false
	}
	if workspacePathLooksParameterized(normalized) {
		return false
	}
	if _, ok := explicitDeliverableActionWords[strings.ToLower(strings.TrimSpace(normalized))]; ok {
		return false
	}
	if strings.Contains(normalized, "/") || strings.Contains(filepath.Base(normalized), ".") {
		return true
	}
	trimmedRaw := strings.TrimSpace(raw)
	if trimmedRaw == "" {
		return false
	}
	if _, ok := explicitDeliverableActionWords[strings.ToLower(trimmedRaw)]; ok {
		return false
	}
	for _, r := range trimmedRaw {
		if r >= 'A' && r <= 'Z' {
			return true
		}
	}
	return false
}

func looksLikePreferredDeliverableRootPath(normalized string) bool {
	normalized = normalizeWorkspaceRelativePath(normalized)
	if normalized == "" {
		return false
	}
	if !strings.HasPrefix(strings.ToLower(normalized), "content/") {
		return false
	}
	return !strings.Contains(filepath.Base(normalized), ".")
}

func workspacePathLooksParameterized(normalized string) bool {
	normalized = normalizeWorkspaceRelativePath(normalized)
	if normalized == "" {
		return false
	}
	return strings.ContainsAny(normalized, "{}[]<>*?")
}

func workspacePathWithinRoot(path, root string) bool {
	path = normalizeWorkspaceRelativePath(path)
	root = normalizeWorkspaceRelativePath(root)
	if path == "" || root == "" {
		return false
	}
	if sameWorkspaceRelativePath(path, root) {
		return true
	}
	return strings.HasPrefix(path, strings.TrimSuffix(root, "/")+"/")
}

func explicitExecutionDeliverableWriteCompleted(taskRecord repo.ProjectTask, result ToolResult) bool {
	if !strings.EqualFold(strings.TrimSpace(result.Name), "file.write") || strings.TrimSpace(result.Error) != "" {
		return false
	}
	writtenPath := normalizeWorkspaceRelativePath(anyString(result.Output["path"]))
	if writtenPath == "" || anyInt(result.Output["byte_size"]) <= 0 {
		return false
	}
	if preferredPath := normalizeWorkspaceRelativePath(preferredTaskDeliverablePath(taskRecord)); preferredPath != "" && sameWorkspaceRelativePath(writtenPath, preferredPath) {
		return true
	}
	plan, hasPlan := taskplan.Parse(taskRecord.Metadata)
	if !hasPlan || !strings.EqualFold(strings.TrimSpace(plan.Mode), taskplan.ModeExecutionFirst) {
		return false
	}
	deliverablePath := explicitDeliverablePath(taskRecord)
	if deliverablePath == "" {
		return false
	}
	if !writtenPathMatchesExplicitDeliverable(writtenPath, deliverablePath) {
		return false
	}
	return true
}

func writtenPathMatchesExplicitDeliverable(writtenPath, deliverablePath string) bool {
	if sameWorkspaceRelativePath(writtenPath, deliverablePath) {
		return true
	}
	directoryPrefix := strings.TrimSuffix(deliverablePath, "/")
	if directoryPrefix == "" {
		return false
	}
	return strings.HasPrefix(writtenPath, directoryPrefix+"/")
}

func shouldStopAfterExecutionArtifactWrite(taskRecord repo.ProjectTask, result ToolResult) bool {
	if explicitExecutionDeliverableWriteCompleted(taskRecord, result) {
		return true
	}
	if !strings.EqualFold(strings.TrimSpace(result.Name), "file.write") || strings.TrimSpace(result.Error) != "" {
		return false
	}
	plan, hasPlan := taskplan.Parse(taskRecord.Metadata)
	if !hasPlan || !strings.EqualFold(strings.TrimSpace(plan.Mode), taskplan.ModeExecutionFirst) {
		return false
	}
	if explicitDeliverablePath(taskRecord) != "" {
		return false
	}
	writtenPath := normalizeWorkspaceRelativePath(anyString(result.Output["path"]))
	if writtenPath == "" || anyInt(result.Output["byte_size"]) <= 0 {
		return false
	}
	for _, artifact := range plan.Artifacts {
		artifactPath := normalizeWorkspaceRelativePath(artifact.RepoPath)
		if artifactPath == "" {
			continue
		}
		if sameWorkspaceRelativePath(writtenPath, artifactPath) {
			return true
		}
	}
	return false
}

func normalizeWorkspaceRelativePath(value string) string {
	trimmed := strings.TrimSpace(value)
	if trimmed == "" {
		return ""
	}
	return filepath.ToSlash(filepath.Clean(filepath.FromSlash(trimmed)))
}

func parseToolResultMessage(content string) (string, map[string]any, string, bool) {
	trimmed := strings.TrimSpace(content)
	if trimmed == "" {
		return "", nil, "", false
	}
	var payload map[string]any
	if err := json.Unmarshal([]byte(trimmed), &payload); err != nil {
		return "", nil, "", false
	}
	if payload == nil {
		return "", nil, "", false
	}
	toolName := strings.TrimSpace(anyString(payload["tool_name"]))
	if toolName == "" {
		return "", nil, "", false
	}
	output, _ := payload["output"].(map[string]any)
	errText := strings.TrimSpace(anyString(payload["error"]))
	if errText == "" && output != nil {
		errText = strings.TrimSpace(anyString(output["error"]))
	}
	return toolName, output, errText, true
}

func anyString(raw any) string {
	if raw == nil {
		return ""
	}
	switch typed := raw.(type) {
	case string:
		return typed
	case fmt.Stringer:
		return typed.String()
	default:
		return fmt.Sprintf("%v", raw)
	}
}

func anyStrings(raw any) []string {
	switch typed := raw.(type) {
	case []string:
		out := make([]string, 0, len(typed))
		for _, item := range typed {
			trimmed := strings.TrimSpace(item)
			if trimmed != "" {
				out = append(out, trimmed)
			}
		}
		if len(out) == 0 {
			return nil
		}
		return out
	case []any:
		out := make([]string, 0, len(typed))
		for _, item := range typed {
			trimmed := strings.TrimSpace(anyString(item))
			if trimmed != "" {
				out = append(out, trimmed)
			}
		}
		if len(out) == 0 {
			return nil
		}
		return out
	default:
		return nil
	}
}

func anySliceLen(raw any) int {
	switch typed := raw.(type) {
	case []any:
		return len(typed)
	case []map[string]any:
		return len(typed)
	default:
		return 0
	}
}

func anyInt(raw any) int {
	switch typed := raw.(type) {
	case int:
		return typed
	case int32:
		return int(typed)
	case int64:
		return int(typed)
	case float64:
		return int(typed)
	default:
		return 0
	}
}

type rateLimitRetryAfterProvider interface {
	RateLimitRetryAfter() time.Duration
}

func rateLimitRetryAfterHint(err error) time.Duration {
	if err == nil {
		return 0
	}
	var provider rateLimitRetryAfterProvider
	if errors.As(err, &provider) {
		hint := provider.RateLimitRetryAfter()
		if hint > 0 {
			return hint
		}
	}
	return 0
}

type transientModelRetryAfterProvider interface {
	TransientModelRetryAfter() time.Duration
}

func transientModelRetryAfterHint(err error) time.Duration {
	if err == nil {
		return 0
	}
	var provider transientModelRetryAfterProvider
	if errors.As(err, &provider) {
		hint := provider.TransientModelRetryAfter()
		if hint > 0 {
			return hint
		}
	}
	return 0
}

func rateLimitRetryDelay(retryCount int, retryAfterHint time.Duration) time.Duration {
	if retryAfterHint > 0 {
		if retryAfterHint > maxRateLimitBackoff {
			return maxRateLimitBackoff
		}
		return retryAfterHint
	}
	if retryCount < 0 {
		retryCount = 0
	}

	delay := defaultRateLimitBackoff
	for i := 0; i < retryCount; i++ {
		if delay >= (maxRateLimitBackoff / 2) {
			return maxRateLimitBackoff
		}
		delay *= 2
	}
	if delay > maxRateLimitBackoff {
		return maxRateLimitBackoff
	}
	return delay
}

func transientModelRetryDelay(retryCount int, retryAfterHint time.Duration) time.Duration {
	if retryAfterHint > 0 {
		if retryAfterHint > maxTransientInfraBackoff {
			return maxTransientInfraBackoff
		}
		return retryAfterHint
	}
	return transientInfrastructureRetryDelay(retryCount)
}

func jitteredRateLimitRetryDelay(delay time.Duration, sessionID, messageID uuid.UUID, retryCount int) time.Duration {
	if delay < rateLimitRetryJitterThreshold || maxRateLimitRetryJitter <= 0 {
		return delay
	}
	hasher := fnv.New64a()
	_, _ = hasher.Write(sessionID[:])
	_, _ = hasher.Write(messageID[:])
	_, _ = hasher.Write([]byte(strconv.Itoa(retryCount)))
	jitterRange := uint64(maxRateLimitRetryJitter / time.Second)
	if jitterRange == 0 {
		return delay
	}
	jitterSeconds := hasher.Sum64() % (jitterRange + 1)
	return delay + time.Duration(jitterSeconds)*time.Second
}

func transientInfrastructureRetryDelay(retryCount int) time.Duration {
	if retryCount < 0 {
		retryCount = 0
	}

	delay := defaultTransientInfraBackoff
	for i := 0; i < retryCount; i++ {
		if delay >= (maxTransientInfraBackoff / 2) {
			return maxTransientInfraBackoff
		}
		delay *= 2
	}
	if delay > maxTransientInfraBackoff {
		return maxTransientInfraBackoff
	}
	return delay
}

func formatRetryDelay(delay time.Duration) string {
	if delay <= 0 {
		delay = time.Second
	}
	return delay.Round(time.Second).String()
}

func payloadUUID(payload map[string]any, key string) (uuid.UUID, bool) {
	value, ok := payload[key]
	if !ok {
		return uuid.Nil, false
	}
	text, ok := value.(string)
	if !ok {
		return uuid.Nil, false
	}
	parsed, err := uuid.Parse(strings.TrimSpace(text))
	if err != nil {
		return uuid.Nil, false
	}
	return parsed, true
}

func payloadString(payload map[string]any, key string) (string, bool) {
	value, ok := payload[key]
	if !ok {
		return "", false
	}
	text, ok := value.(string)
	if !ok {
		return "", false
	}
	return strings.TrimSpace(text), true
}

func runIDFromMetadata(metadata json.RawMessage) *uuid.UUID {
	return runAttributionIDFromMetadata(metadata, "run_id")
}

func runStepIDFromMetadata(metadata json.RawMessage) *uuid.UUID {
	return runAttributionIDFromMetadata(metadata, "run_step_id")
}

func runAttemptIDFromMetadata(metadata json.RawMessage) *uuid.UUID {
	return runAttributionIDFromMetadata(metadata, "run_attempt_id")
}

func (e *TurnEngine) sanitizeInheritedRunAttribution(ctx context.Context, runID, runStepID, runAttemptID *uuid.UUID) (*uuid.UUID, *uuid.UUID, *uuid.UUID) {
	if e == nil || e.pool == nil || runID == nil || *runID == uuid.Nil {
		return runID, runStepID, runAttemptID
	}
	var status string
	if err := e.pool.QueryRow(ctx, `SELECT status FROM run WHERE id = $1`, *runID).Scan(&status); err != nil {
		return nil, nil, nil
	}
	status = strings.TrimSpace(strings.ToLower(status))
	if status == "created" || status == "in_progress" {
		return runID, runStepID, runAttemptID
	}
	return nil, nil, nil
}

func runAttributionIDFromMetadata(metadata json.RawMessage, key string) *uuid.UUID {
	if len(metadata) == 0 || !json.Valid(metadata) {
		return nil
	}
	var payload map[string]any
	if err := json.Unmarshal(metadata, &payload); err != nil {
		return nil
	}
	id, ok := payloadUUID(payload, key)
	if !ok {
		return nil
	}
	return cloneUUIDPointer(&id)
}

func isRunAttributionConstraintError(err error) bool {
	if err == nil {
		return false
	}
	text := strings.ToLower(strings.TrimSpace(err.Error()))
	return strings.Contains(text, "model_invocation_run_id_fk") ||
		strings.Contains(text, "model_invocation_run_step_id_fk") ||
		strings.Contains(text, "model_invocation_run_attempt_id_fk")
}

func (e *TurnEngine) logicalMessageCancelled(ctx context.Context, sessionID, messageID uuid.UUID) (bool, error) {
	if e.turns == nil {
		return false, nil
	}
	turns, err := e.turns.ListBySession(ctx, sessionID)
	if err != nil {
		return false, err
	}
	var latest *repo.ChatTurn
	for _, turn := range turns {
		if turn.TriggerMessageID == nil || *turn.TriggerMessageID != messageID {
			continue
		}
		turnCopy := turn
		if latest == nil ||
			turnCopy.TurnNumber > latest.TurnNumber ||
			(turnCopy.TurnNumber == latest.TurnNumber && turnCopy.RetryCount > latest.RetryCount) {
			latest = &turnCopy
		}
	}
	if latest == nil {
		return false, nil
	}
	return strings.EqualFold(strings.TrimSpace(latest.Status), "cancelled"), nil
}

func reactionDelta(emoji string) (float64, bool) {
	normalized := strings.TrimSpace(strings.ToLower(emoji))
	switch normalized {
	case "👍", "✅", "❤️", ":thumbsup:", "thumbs_up", "heart":
		return 0.05, true
	case "👎", "❌", ":thumbsdown:", "thumbs_down":
		return -0.10, true
	default:
		return 0, false
	}
}

func resolveProjectID(ctx context.Context, session *chat.ChatSession, tasks taskRepository) *uuid.UUID {
	if session == nil {
		return nil
	}
	switch strings.TrimSpace(session.ScopeType) {
	case "project":
		projectID := session.ScopeID
		return &projectID
	case "project_task":
		if tasks == nil {
			return nil
		}
		taskRecord, err := tasks.GetByID(ctx, session.ScopeID)
		if err != nil {
			return nil
		}
		projectID := taskRecord.ProjectID
		return &projectID
	default:
		return nil
	}
}

func (e *TurnEngine) projectPausedForSession(ctx context.Context, session *chat.ChatSession) (bool, string, error) {
	if session == nil || e.projects == nil {
		return false, "", nil
	}
	projectID := resolveProjectID(ctx, session, e.tasks)
	if projectID == nil || *projectID == uuid.Nil {
		return false, "", nil
	}
	projectRecord, err := e.projects.GetByID(ctx, *projectID)
	if errors.Is(err, repo.ErrNotFound) {
		return false, "", nil
	}
	if err != nil {
		return false, "", err
	}
	pauseState := projectpause.Parse(projectRecord.Settings)
	if pauseState.IsPaused {
		if cleared, clearErr := e.clearStaleProjectBootstrapPause(ctx, projectRecord, pauseState); clearErr != nil {
			return false, "", clearErr
		} else if cleared {
			return false, "", nil
		}
		if cleared, clearErr := e.clearStaleTransientExecutionRuntimePause(ctx, session, projectRecord, pauseState); clearErr != nil {
			return false, "", clearErr
		} else if cleared {
			return false, "", nil
		}
	}
	return pauseState.IsPaused, pauseState.Reason, nil
}

func (e *TurnEngine) clearStaleProjectBootstrapPause(ctx context.Context, projectRecord repo.Project, pauseState projectpause.State) (bool, error) {
	if e == nil || e.pool == nil || projectRecord.ID == uuid.Nil || !pauseState.IsPaused {
		return false, nil
	}
	if !strings.Contains(strings.ToLower(strings.TrimSpace(string(pauseState.Metadata))), projectBootstrapSource) {
		return false, nil
	}
	storedState := projectBootstrapStateFromMetadata(projectRecord.Settings)
	if strings.TrimSpace(storedState.Status) == "" {
		return false, nil
	}
	progress, err := e.loadProjectBootstrapProgress(ctx, projectRecord.ID)
	if err != nil {
		return false, err
	}
	if !projectBootstrapPauseInvalidatedByCurrentProgress(storedState, progress) &&
		!projectBootstrapPauseMetadataInvalidatedByCurrentProgress(pauseState.Metadata, progress) {
		return false, nil
	}
	updated := projectRecord
	updated.Settings, err = projectpause.ClearPause(updated.Settings)
	if err != nil {
		return false, err
	}
	if _, err := repo.NewProjectRepo(e.pool).Update(ctx, updated); err != nil {
		return false, err
	}
	if e.logger != nil {
		e.logger.Info("cleared stale project bootstrap pause after progress advanced",
			"project_id", projectRecord.ID,
			"pause_reason", strings.TrimSpace(pauseState.Reason),
			"stored_first_wave_promoted_count", storedState.FirstWavePromotedCount,
			"current_first_wave_promoted_count", progress.FirstWavePromotedCount,
			"stored_first_wave_execution_count", storedState.FirstWaveExecutionCount,
			"current_first_wave_execution_count", progress.FirstWaveExecutionCount,
			"stored_first_wave_job_count", storedState.FirstWaveJobCount,
			"current_first_wave_job_count", progress.FirstWaveJobCount,
		)
	}
	return true, nil
}

func (e *TurnEngine) clearStaleTransientExecutionRuntimePause(ctx context.Context, session *chat.ChatSession, projectRecord repo.Project, pauseState projectpause.State) (bool, error) {
	if e == nil || e.pool == nil || projectRecord.ID == uuid.Nil || !shouldAutoClearTransientExecutionRuntimePauseForSession(session, pauseState) {
		return false, nil
	}
	updated := projectRecord
	var err error
	updated.Settings, err = projectpause.ClearPause(updated.Settings)
	if err != nil {
		return false, err
	}
	if _, err := repo.NewProjectRepo(e.pool).Update(ctx, updated); err != nil {
		return false, err
	}
	if e.logger != nil {
		e.logger.Info("cleared stale transient execution-runtime pause for task session",
			"project_id", projectRecord.ID,
			"session_id", session.ID,
			"pause_reason", strings.TrimSpace(pauseState.Reason),
		)
	}
	return true, nil
}

func shouldAutoClearTransientExecutionRuntimePauseForSession(session *chat.ChatSession, pauseState projectpause.State) bool {
	if session == nil || !pauseState.IsPaused {
		return false
	}
	if !strings.EqualFold(strings.TrimSpace(session.ScopeType), "project_task") || session.ScopeID == uuid.Nil {
		return false
	}
	metadata := map[string]any{}
	if len(pauseState.Metadata) > 0 && json.Valid(pauseState.Metadata) {
		_ = json.Unmarshal(pauseState.Metadata, &metadata)
	}
	source := strings.TrimSpace(fmt.Sprintf("%v", metadata["source"]))
	if !strings.EqualFold(source, projectFailureCategoryExecution) && !strings.EqualFold(source, "execution_runtime") {
		return false
	}
	reason := strings.TrimSpace(fmt.Sprintf("%v", metadata["failure_reason"]))
	if reason == "" {
		reason = strings.TrimSpace(pauseState.Reason)
	}
	if reason == "" {
		return false
	}
	cause := errors.New(reason)
	return isTransientModelError(cause) || isTransientInfrastructureError(cause)
}

func (e *TurnEngine) validationLoopBlockerForSession(ctx context.Context, session *chat.ChatSession) (bool, taskValidationGuardState, error) {
	if session == nil || e.tasks == nil {
		return false, taskValidationGuardState{}, nil
	}
	taskID := resolveTaskID(session)
	if taskID == nil || *taskID == uuid.Nil {
		return false, taskValidationGuardState{}, nil
	}
	taskRecord, err := e.tasks.GetByID(ctx, *taskID)
	if errors.Is(err, repo.ErrNotFound) {
		return false, taskValidationGuardState{}, nil
	}
	if err != nil {
		return false, taskValidationGuardState{}, err
	}
	guard, ok := parseTaskValidationGuard(taskRecord.Metadata)
	if !ok || !guard.Blocked {
		return false, taskValidationGuardState{}, nil
	}
	if invalidated, updatedTask, invalidateErr := e.invalidateStaleRecoveryFocusValidationGuard(ctx, taskRecord, guard); invalidateErr != nil {
		return false, taskValidationGuardState{}, invalidateErr
	} else if invalidated {
		taskRecord = updatedTask
		return false, taskValidationGuardState{}, nil
	}
	if !strings.EqualFold(strings.TrimSpace(taskRecord.WorkStatus), "blocked") {
		return false, taskValidationGuardState{}, nil
	}
	return true, guard, nil
}

func (e *TurnEngine) invalidateStaleRecoveryFocusValidationGuard(ctx context.Context, taskRecord repo.ProjectTask, guard taskValidationGuardState) (bool, repo.ProjectTask, error) {
	if e == nil || e.tasks == nil {
		return false, taskRecord, nil
	}
	if !strings.EqualFold(strings.TrimSpace(guard.FailureCode), "recovery_target_focus_required") {
		return false, taskRecord, nil
	}
	checkpoint, ok := taskcheckpoint.ParseRecoveryFileWriteCheckpoint(taskRecord.Metadata)
	if !ok {
		return false, taskRecord, nil
	}
	targetPath := strings.TrimSpace(checkpoint.TargetPath)
	if targetPath == "" {
		return false, taskRecord, nil
	}
	if looksLikeExplicitDeliverablePath(normalizeWorkspaceRelativePath(targetPath), targetPath) && !recoveryLowSignalPackageMarkerPath(targetPath) {
		return false, taskRecord, nil
	}
	cleared, err := clearTaskValidationGuardMetadata(taskRecord.Metadata)
	if err != nil {
		return false, taskRecord, err
	}
	taskRecord.Metadata = cleared
	checkpoint.TargetPath = ""
	merged, err := taskcheckpoint.MergeRecoveryFileWriteCheckpoint(taskRecord.Metadata, checkpoint)
	if err != nil {
		return false, taskRecord, err
	}
	taskRecord.Metadata = merged
	updatedTask, err := updateTurnTaskMetadata(ctx, e.tasks, taskRecord)
	if err != nil {
		return false, taskRecord, err
	}
	return true, updatedTask, nil
}

func (e *TurnEngine) enqueueAgentTurnIfActive(ctx context.Context, session *chat.ChatSession, payload AgentTurnPayload, runAfter *time.Time) (bool, error) {
	if paused, reason, err := e.projectPausedForSession(ctx, session); err != nil {
		return false, err
	} else if paused {
		e.logPausedTurnSkip("skipping agent turn enqueue for paused project", session, reason, payload.MessageID)
		return false, nil
	}
	if blocked, guard, err := e.validationLoopBlockerForSession(ctx, session); err != nil {
		return false, err
	} else if blocked {
		e.logValidationLoopSuppressed("skipping agent turn enqueue for blocked validation loop", session, payload.MessageID, guard)
		return false, nil
	}
	message, err := e.messages.GetByID(ctx, payload.MessageID)
	if err != nil {
		return false, err
	}
	if chat.AgentTurnDispatchCancelled(message.Metadata) {
		e.logger.Info("skipping enqueue for cancelled agent turn dispatch", "session_id", payload.SessionID, "message_id", payload.MessageID)
		return false, nil
	}
	cancelled, err := e.logicalMessageCancelled(ctx, payload.SessionID, payload.MessageID)
	if err != nil {
		return false, err
	}
	if cancelled {
		e.logger.Info("skipping enqueue after logical message cancellation", "session_id", payload.SessionID, "message_id", payload.MessageID)
		return false, nil
	}
	if payload.FlowNodeExecutionID == nil && session != nil {
		payload.FlowNodeExecutionID = cloneUUIDPointer(flowNodeExecutionIDFromSessionMetadata(session))
	}
	if suppressed, err := e.suppressRecoveryRetryForCompletedTurn(ctx, session, payload.MessageID); err != nil {
		return false, err
	} else if suppressed {
		e.logger.Info("skipping enqueue after completed recovery halt for message",
			"session_id", payload.SessionID,
			"message_id", payload.MessageID,
		)
		return false, nil
	}
	if _, err := e.enqueuer.Enqueue(ctx, nil, AgentTurnJobType, e.jobPriority, payload, runAfter); err != nil {
		return false, err
	}
	return true, nil
}

func (e *TurnEngine) enqueueAgentTurnForProjectResume(ctx context.Context, session *chat.ChatSession, payload AgentTurnPayload, runAfter *time.Time) (bool, error) {
	if blocked, guard, err := e.validationLoopBlockerForSession(ctx, session); err != nil {
		return false, err
	} else if blocked {
		e.logValidationLoopSuppressed("skipping project resume enqueue for blocked validation loop", session, payload.MessageID, guard)
		return false, nil
	}
	message, err := e.messages.GetByID(ctx, payload.MessageID)
	if err != nil {
		return false, err
	}
	if chat.AgentTurnDispatchCancelled(message.Metadata) {
		e.logger.Info("skipping project resume enqueue for cancelled agent turn dispatch", "session_id", payload.SessionID, "message_id", payload.MessageID)
		return false, nil
	}
	cancelled, err := e.logicalMessageCancelled(ctx, payload.SessionID, payload.MessageID)
	if err != nil {
		return false, err
	}
	if cancelled {
		e.logger.Info("skipping project resume enqueue after logical message cancellation", "session_id", payload.SessionID, "message_id", payload.MessageID)
		return false, nil
	}
	if payload.FlowNodeExecutionID == nil && session != nil {
		payload.FlowNodeExecutionID = cloneUUIDPointer(flowNodeExecutionIDFromSessionMetadata(session))
	}
	if suppressed, err := e.suppressRecoveryRetryForCompletedTurn(ctx, session, payload.MessageID); err != nil {
		return false, err
	} else if suppressed {
		e.logger.Info("skipping project resume enqueue after completed recovery halt for message",
			"session_id", payload.SessionID,
			"message_id", payload.MessageID,
		)
		return false, nil
	}
	if _, err := e.enqueuer.Enqueue(ctx, nil, AgentTurnJobType, e.jobPriority, payload, runAfter); err != nil {
		return false, err
	}
	return true, nil
}

func (e *TurnEngine) suppressRecoveryRetryForCompletedTurn(ctx context.Context, session *chat.ChatSession, messageID uuid.UUID) (bool, error) {
	if e == nil || e.turns == nil || session == nil || messageID == uuid.Nil {
		return false, nil
	}
	if !strings.EqualFold(strings.TrimSpace(session.ScopeType), "project_task") {
		return false, nil
	}
	turns, err := e.turns.ListBySession(ctx, session.ID)
	if err != nil {
		return false, err
	}
	for i := range turns {
		turn := turns[i]
		if turn.TriggerMessageID == nil || *turn.TriggerMessageID != messageID {
			continue
		}
		if !strings.EqualFold(strings.TrimSpace(turn.Status), "completed") {
			continue
		}
		if shouldSuppressAutoContinuationForStopReason(turn.StopReason) {
			return true, nil
		}
	}
	return false, nil
}

func (e *TurnEngine) logValidationLoopSuppressed(message string, session *chat.ChatSession, messageID uuid.UUID, guard taskValidationGuardState) {
	metrics.RecordAgentTurnDispatchSuppressed(validationLoopSuppressionReason)
	if e == nil || e.logger == nil || session == nil {
		return
	}
	attrs := []any{
		"session_id", session.ID,
		"scope_type", strings.TrimSpace(session.ScopeType),
		"tool_name", strings.TrimSpace(guard.ToolName),
		"failure_class", strings.TrimSpace(guard.FailureClass),
		"failure_code", strings.TrimSpace(guard.FailureCode),
		"failure_count", guard.Count,
	}
	if messageID != uuid.Nil {
		attrs = append(attrs, "message_id", messageID)
	}
	if taskID := resolveTaskID(session); taskID != nil && *taskID != uuid.Nil {
		attrs = append(attrs, "task_id", *taskID)
	}
	e.logger.Info(message, attrs...)
}

func (e *TurnEngine) logPausedTurnSkip(message string, session *chat.ChatSession, reason string, messageID uuid.UUID) {
	if e == nil || e.logger == nil || session == nil {
		return
	}
	attrs := []any{
		"session_id", session.ID,
		"scope_type", strings.TrimSpace(session.ScopeType),
	}
	if messageID != uuid.Nil {
		attrs = append(attrs, "message_id", messageID)
	}
	if trimmed := strings.TrimSpace(reason); trimmed != "" {
		attrs = append(attrs, "pause_reason", trimmed)
	}
	if projectID := resolveProjectID(context.Background(), session, e.tasks); projectID != nil && *projectID != uuid.Nil {
		attrs = append(attrs, "project_id", *projectID)
	}
	e.logger.Info(message, attrs...)
}

func resolveTaskID(session *chat.ChatSession) *uuid.UUID {
	if session == nil {
		return nil
	}
	if strings.TrimSpace(session.ScopeType) != "project_task" {
		return nil
	}
	id := session.ScopeID
	return &id
}

func flowNodeExecutionIDFromSessionMetadata(session *chat.ChatSession) *uuid.UUID {
	if session == nil || len(session.Metadata) == 0 || !json.Valid(session.Metadata) {
		return nil
	}
	var payload map[string]any
	if err := json.Unmarshal(session.Metadata, &payload); err != nil {
		return nil
	}
	executionID, ok := payloadUUID(payload, "flow_node_execution_id")
	if !ok || executionID == uuid.Nil {
		return nil
	}
	return &executionID
}

func (e *TurnEngine) syncBoundFlowExecutionTurnOwnership(ctx context.Context, session *chat.ChatSession, turnID, runID *uuid.UUID) error {
	if e == nil || e.pool == nil || session == nil {
		return nil
	}
	executionID := flowNodeExecutionIDFromSessionMetadata(session)
	if executionID == nil || *executionID == uuid.Nil {
		return nil
	}
	execution, err := repo.NewFlowNodeExecutionRepo(e.pool).GetByID(ctx, *executionID)
	if errors.Is(err, repo.ErrNotFound) {
		return nil
	}
	if err != nil {
		return err
	}
	updatedMetadata := execution.Metadata
	if head := e.boundExecutionEntryHeadSHA(ctx, session); head != "" {
		if entryHead := repo.FlowExecutionEntryHeadSHAFromMetadata(updatedMetadata); strings.TrimSpace(entryHead) != strings.TrimSpace(head) {
			updatedMetadata = repo.FlowExecutionMetadataWithEntryHeadSHA(updatedMetadata, head)
		}
	}
	updated := repo.FlowExecutionMetadataWithLiveOwner(updatedMetadata, repo.FlowExecutionLiveOwner{
		RunID:  cloneUUIDPointer(runID),
		TurnID: turnID,
	})
	executionRepo := repo.NewFlowNodeExecutionRepo(e.pool)
	if _, err := executionRepo.UpdateMetadata(ctx, execution.ID, updated); err != nil {
		return err
	}
	running := "running"
	_, err = executionRepo.UpdateRuntimeSubstate(ctx, execution.ID, &running)
	return err
}

func (e *TurnEngine) boundExecutionEntryHeadSHA(ctx context.Context, session *chat.ChatSession) string {
	if e == nil || e.tasks == nil || e.projects == nil || session == nil || !strings.EqualFold(strings.TrimSpace(session.ScopeType), "project_task") || session.ScopeID == uuid.Nil {
		return ""
	}
	taskRecord, err := e.tasks.GetByID(ctx, session.ScopeID)
	if err != nil {
		return ""
	}
	root, err := e.taskWorkspaceRoot(ctx, taskRecord)
	if err != nil {
		return ""
	}
	head, err := flowcommit.HeadSHA(ctx, root)
	if err != nil {
		return ""
	}
	return strings.TrimSpace(head)
}

func (e *TurnEngine) reconcileBoundFlowExecutionTurnOwnership(ctx context.Context, session *chat.ChatSession, turnID uuid.UUID) {
	if e == nil || e.pool == nil || e.chat == nil || session == nil || turnID == uuid.Nil {
		return
	}
	currentTurn, err := e.chat.GetTurn(ctx, turnID)
	if err != nil || currentTurn == nil {
		return
	}
	status := strings.ToLower(strings.TrimSpace(currentTurn.Status))
	if status != "completed" && status != "cancelled" && status != "failed" {
		return
	}
	executionID := flowNodeExecutionIDFromSessionMetadata(session)
	if executionID == nil || *executionID == uuid.Nil {
		return
	}
	executionRepo := repo.NewFlowNodeExecutionRepo(e.pool)
	execution, err := executionRepo.GetByID(ctx, *executionID)
	if err != nil {
		return
	}
	liveOwner := repo.FlowExecutionLiveOwnerFromMetadata(execution.Metadata)
	if liveOwner.TurnID == nil || *liveOwner.TurnID != turnID {
		return
	}
	updatedExecution, err := executionRepo.UpdateMetadata(ctx, execution.ID, repo.FlowExecutionMetadataWithLiveOwner(execution.Metadata, repo.FlowExecutionLiveOwner{
		RunID:  liveOwner.RunID,
		TurnID: nil,
	}))
	if err != nil {
		return
	}
	waiting := e.waitingBoundFlowExecutionRuntimeSubstate(ctx, session)
	if waiting == nil {
		return
	}
	_, _ = executionRepo.UpdateRuntimeSubstate(ctx, updatedExecution.ID, waiting)
}

func (e *TurnEngine) waitingBoundFlowExecutionRuntimeSubstate(ctx context.Context, session *chat.ChatSession) *string {
	if session == nil {
		return nil
	}
	if strings.EqualFold(strings.TrimSpace(session.ScopeType), "project_task") && session.ScopeID != uuid.Nil && e.tasks != nil {
		taskRecord, err := e.tasks.GetByID(ctx, session.ScopeID)
		if err == nil && strings.EqualFold(strings.TrimSpace(taskRecord.WorkStatus), "review") {
			value := "waiting_for_review"
			return &value
		}
	}
	value := "waiting_for_turn"
	return &value
}

type toolExecutionBinding struct {
	projectID *uuid.UUID
	taskID    *uuid.UUID
}

func (e *TurnEngine) resolveToolExecutionBinding(ctx context.Context, session *chat.ChatSession) (toolExecutionBinding, error) {
	if session == nil {
		return toolExecutionBinding{}, nil
	}
	scopeType := strings.ToLower(strings.TrimSpace(session.ScopeType))
	switch scopeType {
	case "project":
		if session.ScopeID == uuid.Nil {
			return toolExecutionBinding{}, fmt.Errorf("internal invariant: project-scoped session is missing project_id")
		}
		projectID := session.ScopeID
		return toolExecutionBinding{projectID: &projectID}, nil
	case "project_task":
		if session.ScopeID == uuid.Nil {
			return toolExecutionBinding{}, fmt.Errorf("internal invariant: task-scoped tool execution is missing bound task context: session is missing task_id")
		}
		if e.tasks == nil {
			return toolExecutionBinding{}, fmt.Errorf("internal invariant: task-scoped tool execution is missing bound task context: task repository unavailable")
		}
		taskRecord, err := e.tasks.GetByID(ctx, session.ScopeID)
		if err != nil {
			if errors.Is(err, repo.ErrNotFound) {
				return toolExecutionBinding{}, fmt.Errorf("internal invariant: task-scoped tool execution is missing bound task context: task record not found")
			}
			return toolExecutionBinding{}, err
		}
		if taskRecord.OrganizationID != uuid.Nil && taskRecord.OrganizationID != session.OrganizationID {
			return toolExecutionBinding{}, fmt.Errorf("internal invariant: task-scoped tool execution is missing bound task context: task organization mismatch")
		}
		if taskRecord.ProjectID == uuid.Nil {
			return toolExecutionBinding{}, fmt.Errorf("internal invariant: task-scoped tool execution is missing bound task context: project_id is missing for task")
		}
		taskID := session.ScopeID
		projectID := taskRecord.ProjectID
		return toolExecutionBinding{projectID: &projectID, taskID: &taskID}, nil
	default:
		return toolExecutionBinding{}, nil
	}
}

func isTransientModelError(err error) bool {
	if err == nil {
		return false
	}
	if errors.Is(err, ErrModelTransient) || errors.Is(err, context.DeadlineExceeded) {
		return true
	}
	if errors.Is(err, ErrRateLimited) {
		return true
	}
	var netErr net.Error
	if errors.As(err, &netErr) {
		return netErr.Timeout() || netErr.Temporary()
	}
	text := strings.ToLower(err.Error())
	if strings.Contains(text, "timeout") || strings.Contains(text, "rate limit") || strings.Contains(text, "temporar") {
		return true
	}
	if strings.Contains(text, "stream error") && (strings.Contains(text, "received from peer") || strings.Contains(text, "internal_error") || strings.Contains(text, "internal error")) {
		return true
	}
	if strings.Contains(text, "received from peer") && (strings.Contains(text, "internal_error") || strings.Contains(text, "internal error")) {
		return true
	}
	return false
}

func looksLikeTransientModelFailureText(text string) bool {
	trimmed := strings.TrimSpace(text)
	if trimmed == "" {
		return false
	}
	lower := strings.ToLower(trimmed)
	if strings.Contains(lower, "model provider rate limited") {
		return false
	}
	if strings.Contains(lower, "transient model failure") {
		return true
	}
	if strings.Contains(lower, "all provider connections are temporarily unavailable") {
		return true
	}
	if strings.Contains(lower, "timeout") || strings.Contains(lower, "temporar") {
		return true
	}
	if strings.Contains(lower, "stream error") && (strings.Contains(lower, "received from peer") || strings.Contains(lower, "internal_error") || strings.Contains(lower, "internal error")) {
		return true
	}
	if strings.Contains(lower, "received from peer") && (strings.Contains(lower, "internal_error") || strings.Contains(lower, "internal error")) {
		return true
	}
	return false
}

func isTransientInfrastructureError(err error) bool {
	if err == nil {
		return false
	}
	text := strings.ToLower(err.Error())
	return strings.Contains(text, "sqlstate 53300") ||
		strings.Contains(text, "remaining connection slots are reserved") ||
		strings.Contains(text, "too many clients")
}

func retryBackoff(attempt int) time.Duration {
	switch attempt {
	case 1:
		return 1 * time.Second
	case 2:
		return 2 * time.Second
	default:
		return 4 * time.Second
	}
}

func estimateTokensFromPrompt(assembled *prompt.AssembledPrompt) int {
	if assembled == nil {
		return 0
	}
	if assembled.TotalTokens > 0 {
		return assembled.TotalTokens
	}
	total := 0
	for _, message := range assembled.Messages {
		total += estimateTokens(message.Content)
	}
	if total == 0 {
		total = estimateTokens(assembled.SystemPrompt)
	}
	return total
}

func buildInvocationMetadata(assembled *prompt.AssembledPrompt) json.RawMessage {
	if assembled == nil {
		return json.RawMessage(`{}`)
	}

	layerTokens := make(map[string]any, len(assembled.LayerTokens)+1)
	for key, value := range assembled.LayerTokens {
		layerTokens[key] = value
	}
	memoryTokens := 0
	if value, ok := assembled.LayerTokens["layer5"]; ok && value > 0 {
		memoryTokens = value
	}
	layerTokens["memory_injection"] = memoryTokens

	payload := map[string]any{
		"layer_token_counts":  layerTokens,
		"memory_layer_tokens": memoryTokens,
	}
	raw, err := json.Marshal(payload)
	if err != nil {
		return json.RawMessage(`{}`)
	}
	return raw
}

func estimateTokens(content string) int {
	if strings.TrimSpace(content) == "" {
		return 0
	}
	return len([]rune(content)) / 4
}

func maxInt(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func stringPtr(value string) *string {
	trimmed := strings.TrimSpace(value)
	if trimmed == "" {
		return nil
	}
	copyValue := trimmed
	return &copyValue
}

func cloneUUIDPointer(value *uuid.UUID) *uuid.UUID {
	if value == nil {
		return nil
	}
	copied := *value
	return &copied
}

func lastNUserMessages(messages []repo.ChatMessage, n int) []string {
	if n <= 0 {
		return nil
	}
	items := make([]string, 0, n)
	for i := len(messages) - 1; i >= 0; i-- {
		message := messages[i]
		if !strings.EqualFold(strings.TrimSpace(message.Role), "user") {
			continue
		}
		text := strings.TrimSpace(message.Content)
		if text == "" {
			continue
		}
		items = append(items, text)
		if len(items) == n {
			break
		}
	}
	for i, j := 0, len(items)-1; i < j; i, j = i+1, j-1 {
		items[i], items[j] = items[j], items[i]
	}
	return items
}

func summarizeFailure(err error) string {
	if err == nil {
		return "unknown error"
	}
	text := strings.TrimSpace(err.Error())
	if text == "" {
		return "unknown error"
	}
	if len(text) > 240 {
		text = text[:240]
	}
	return text
}

func cloneMap(input map[string]any) map[string]any {
	if len(input) == 0 {
		return map[string]any{}
	}
	copied := make(map[string]any, len(input))
	for key, value := range input {
		copied[key] = value
	}
	return copied
}

func normalizeModelToolCalls(calls []ModelToolCall) []ModelToolCall {
	if len(calls) == 0 {
		return nil
	}
	normalized := make([]ModelToolCall, 0, len(calls))
	for _, call := range calls {
		callCopy := call
		callCopy.Arguments = toolargs.Normalize(call.Name, cloneMap(call.Arguments))
		normalized = append(normalized, callCopy)
	}
	return normalized
}

// buildToolCallMetadata serializes tool calls into JSONB metadata for the
// assistant chat_message. The prompt assembler reads this metadata so that
// the assistant message can carry its tool_calls in the conversation history.
func buildToolCallMetadata(calls []ModelToolCall) json.RawMessage {
	if len(calls) == 0 {
		return nil
	}
	type storedToolCall struct {
		ID        string         `json:"id"`
		Name      string         `json:"name"`
		Arguments map[string]any `json:"arguments,omitempty"`
	}
	stored := make([]storedToolCall, 0, len(calls))
	for _, c := range calls {
		stored = append(stored, storedToolCall{
			ID:        c.ID,
			Name:      c.Name,
			Arguments: c.Arguments,
		})
	}
	meta := map[string]any{"tool_calls": stored}
	raw, err := json.Marshal(meta)
	if err != nil {
		return nil
	}
	return raw
}
